// ==========================================
// ★ K 의 방 — C등급 직업 갈림길 · 연결
// ==========================================

// ──────────────────────────────────────────
// 협상가 (negotiator) · 자원 없음
// ──────────────────────────────────────────
kJob('negotiator', 'C', [

{ at:'C', t:'굴 앞 — 한 놈, 두 팀',
  x:`바닥에 핏자국이 길게 끌려 있다. 무언가 다쳐서 굴로 들어갔다.<br><br>
    굴 앞에 다른 팀이 있다. 이쪽보다 먼저 왔다. 창끝에 같은 피가 묻었다.<br>
    두 팀이 같은 놈을 쫓았다. 놈은 하나다. 굴 입구도 하나다.<br><br>
    저쪽 반장이 창을 굴 쪽으로 돌린다. 그리고 반쯤 이쪽으로.`,
  o:[
    { l:'① 같이 들어가고 몫은 나와서 정하자고 한다.', k:'bond', dc:14,
      ok:`몫은 나와서 정하자고 했다. 지금 정하면 굴 앞에서 싸운다.<br><br>저쪽 반장이 한참 본다. 창을 굴 쪽으로만 돌렸다.<br>두 팀이 같이 들어갔다. 굴은 좁고 놈은 컸다. 다섯으로는 못 잡았을 것이다. 열이라서 잡았다.<br><br>나와서 몫을 정했다. 다친 만큼씩. 이쪽이 덜 다쳤다. 덜 받았다. 손해 같지 않았다.<br>값을 먼저 정하지 않고 피를 먼저 같이 흘리게 하는 흥정. 손에 새 셈이 하나 붙었다.`,
      ng:`나와서 정하자는 말을 저쪽은 안 주겠다는 말로 들었다.<br><br>창이 다 이쪽으로 돌아왔다. 그 사이 굴에서 놈이 튀어나왔다.<br>두 팀 사이를 뚫고 지나갔다. 지나가며 이쪽 허벅지를 찢었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-14, mind:-6 }, wake:1 },
    { l:'② 굴을 양보하고 놈이 나올 뒷구멍을 찾는다.', k:'sense', dc:14,
      ok:`양보했다. 대신 굴 둘레를 돌았다.<br><br>스무 걸음 떨어진 데 바람이 나오는 구멍이 있다. 짐승도 뒷문을 판다.<br>안에서 저쪽 팀 고함이 났다. 놈이 뒷문으로 나왔다. 기다리던 이쪽 창에 걸렸다.<br><br>저쪽은 빈 굴을 들고 나왔다.`,
      ng:`구멍을 찾다가 다른 구멍을 찾았다. 그 안에 새끼들이 있었다.<br><br>새끼도 이빨은 다 있다. 손등이 너덜너덜해졌다.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ hp:-12, mind:-6 } },
    { l:'③ 저쪽이 정말 원하는 게 뭔지 본다.', k:'gaze', dc:14,
      ok:`저쪽 짐을 봤다. 고기 자루는 이미 찼다. 허리끈마다 이빨이 줄줄이 꿰어 있다.<br><br>먹으려는 게 아니다. 세려는 것이다. 이빨을.<br>이빨은 다 주겠다고 했다. 고기와 가죽만 달라고. 저쪽이 바로 손을 내밀었다.<br><br>같은 놈인데 원하는 데가 달랐다. 그럼 놈이 둘인 셈이다.`,
      ng:`짐을 보는 걸 저쪽이 봤다.<br><br>사냥터에서 남의 짐을 보는 건 몫을 세는 짓이다. 창자루가 이쪽 명치에 들어왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-10, spirit:-8 } }
  ] },

{ at:'C', t:'사냥 뒤 — 몫',
  x:`놈이 쓰러졌다. 셋이 찔렀고 하나가 붙들었고 하나가 맞았다.<br><br>
    이빨은 값이 나간다. 가죽은 질기다. 고기는 아마 먹을 만하다.<br>
    다섯이 놈을 둘러섰다. 아무도 먼저 칼을 안 댄다. 먼저 대는 쪽이 제일 좋은 데를 가진다.<br><br>
    협상가는 안다. 팀이 깨지는 건 사냥 중이 아니라 사냥 뒤다.`,
  o:[
    { l:'① 맞은 사람부터 고르게 한다.', k:'bond', dc:13,
      ok:`맞은 사람부터 고르라고 했다. 그다음 붙든 사람. 찌른 셋은 맨 끝.<br><br>찌른 셋이 입을 열려다 닫았다. 맞은 사람 어깨가 아직 피투성이다.<br>맞은 사람은 이빨을 안 골랐다. 고기를 골랐다. 배가 고팠다고.<br><br>제일 비싼 게 끝까지 남았다. 찌른 셋이 나눠 가졌다. 다들 조금씩 덜 받았고 아무도 덜 받았다고 하지 않았다.<br>순서만 정해도 값이 정해진다. 그걸 몸으로 안 건 처음이다.`,
      ng:`맞은 사람부터라는 말에 찌른 하나가 웃는다. 맞는 건 일이 아니라 실수라고.<br><br>맞은 사람이 칼을 뽑았다. 둘을 떼어 놓다가 이쪽 팔이 베였다.<br>놈은 그사이 식어서 굳었다.`,
      win:{ exp:20, dream:3, item:'짐승 고기' }, lose:{ hp:-10, mind:-8 }, wake:1 },
    { l:'② 다섯 무더기로 똑같이 자르고 제비를 뽑는다.', k:'fix', dc:14,
      ok:`똑같이 잘랐다. 저울이 없으니 손으로 들어 봤다.<br><br>다섯 무더기가 생겼다. 다들 제 무더기보다 남의 무더기를 본다.<br>무더기마다 돌을 하나씩 얹고 눈을 감고 고르게 했다. 불평은 운에 대고 하게 됐다.`,
      ng:`자르는데 놈 배가 꿈틀했다.<br><br>덜 죽었다. 마지막 숨에 꼬리가 돌았다. 칼 든 이쪽 손목을 쳤다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-12, spirit:-6 } }
  ] },

{ at:'C', t:'덫 — 흥정하는 소리',
  x:`덫에 무언가 걸렸다. 다리가 여섯이다. 하나가 쇠턱에 물렸다.<br><br>
    놈이 소리를 낸다. 끊었다 이었다 한다. 울음이 아니다. 흥정할 때 사람이 내는 박자다. 한 번 부르고, 기다리고, 깎아서 다시 부른다.<br>
    놈이 앞다리로 바닥을 긁는다. 한 방향을. 몇 번이고.<br><br>
    그쪽에 무언가 있다는 뜻이다. 풀어 주면 알려 준다는 뜻이고.`,
  o:[
    { l:'① 덫을 반만 풀어 주고 그쪽부터 보자고 한다.', k:'bond', dc:15,
      doom:{ title:'덫의 흥정', what:'덫에 걸린 놈에게 끌려갑니다', dc:15, sec:60,
        text:`쇠턱을 반만 벌렸다. 다리 하나 빠질 만큼만.<br><br>놈이 다리를 뺐다. 그리고 다른 다리로 이쪽 발목을 감았다. 흥정은 놈도 할 줄 안다. 반을 받았으니 반을 가져간다.<br>바닥을 긁던 방향으로 끌고 간다. 정말 그쪽에 무언가 있다.<br><br>놈의 굴이다.`,
        dieText:`놈은 약속을 지켰다.<br><br>그쪽에 정말 무언가 있었다. 놈이 모아 둔 것들. 뼈와 짐과 반쯤 벌어진 덫 몇 개.<br>이제 하나가 더 늘었다. 흥정하러 온 쪽.` },
      ok:`쇠턱을 반만 벌렸다. 나머지는 이쪽 무릎으로 눌렀다.<br><br>놈이 긁던 쪽을 다시 긁는다. 팀원이 그쪽 벽을 파니 물이 스며 나온다. 맑다.<br>무릎을 뗐다. 다 풀어 줬다. 흥정은 끝까지 지켜야 다음 흥정이 있다.<br><br>놈은 절룩이며 어둠으로 갔다. 다음 굴 앞에서 같은 놈을 또 만났다. 이번엔 놈이 먼저 바닥을 긁었다. 물이 아니라 놈 굴 반대쪽 길을.`,
      win:{ exp:22, dream:3, item:'맑은 물' } },
    { l:'② 흥정하지 않고 죽인다.', k:'break', dc:13,
      ok:`흥정할 상대가 아니라고 정했다. 팀원들이 창을 모았다.<br><br>다리 여섯이 다 멈출 때까지 한참 걸렸다. 놈은 끝까지 그 방향을 긁었다.<br>나중에 그쪽 벽을 파 봤다. 아무것도 없었다. 아니면 더 깊이 있었다.`,
      ng:`창이 들어가자 놈이 덫째로 몸을 비틀었다.<br><br>쇠턱이 풀리며 튀었다. 이쪽 정강이에 박혔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-16, mind:-4 } }
  ] },

{ at:'C', t:'굴 앞 — 주저앉은 팀원',
  x:`팀원 하나가 주저앉았다. 더는 못 간다고 한다.<br><br>
    앞 굴에서 놈이 운다. 이쪽 냄새를 맡았다. 다섯이 들어가야 잡는다. 넷이면 하나가 더 다친다.<br>
    팀원은 무릎을 끌어안았다. 손이 떨린다. 다친 데는 없다.<br><br>
    겁도 값을 부른다. 깎이는 값이 있고 안 깎이는 값이 있다.`,
  o:[
    { l:'① 끝까지 말고 이 굴 하나만 가자고 한다.', k:'bond', dc:14,
      ok:`끝까지 가자고 하지 않았다. 이 굴 하나만. 나오면 다시 묻겠다고.<br><br>팀원이 고개를 든다. 끝까지는 못 해도 하나는 한다.<br>굴 하나를 같이 들어갔다. 잡았다. 나와서 물었다. 하나만 더 가자고. 고개를 끄덕였다.<br><br>그렇게 네 번 물었다. 맨 아래에 닿았다.<br>겁은 한 번에 안 깎인다. 잘게 나누면 깎인다. 큰 흥정을 작은 흥정 여럿으로 쪼개는 법이 손에 익었다.`,
      ng:`하나만이라는 말에 팀원이 운다. 하나도 못 한다고.<br><br>달래는 동안 굴 안 울음이 가까워졌다. 넷이서 막았다. 다 같이 많이 다쳤다.`,
      win:{ exp:22, dream:3, mind:6 }, lose:{ hp:-12, mind:-8 }, wake:1 },
    { l:'② 남아서 짐을 지키라고 일을 준다.', k:'gaze', dc:13,
      ok:`남아서 짐을 지키라고 했다. 일을 하나 줬다.<br><br>겁먹은 사람은 할 일이 있으면 덜 떤다. 넷이 굴에 들어갔다. 힘들었다.<br>나와 보니 짐 옆에 놈 새끼 한 마리가 죽어 있었다. 남은 팀원 손에 피가 묻었다. 혼자 잡았다고.`,
      ng:`남겨 두고 들어갔다. 굴 안에서 뒤쪽 비명이 들렸다.<br><br>달려 나왔다. 팀원은 무사했다. 짐이 반 없어졌다. 혼자 남은 사람은 지킬 줄 모른다. 숨을 줄만 안다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-10, spirit:-8 } }
  ] },

{ at:'C', t:'벽 밑 — 지도 한 장',
  x:`다른 팀이 벽 밑에 모여 있다. 셋이 누웠고 둘이 앉았다.<br><br>
    앉은 하나가 종이를 흔든다. 지도다. 이 층 놈들 굴이 표시돼 있다고.<br>
    <span style="color:#d4af37;">"지도 줄게. 우리 셋 데리고 올라가 주면."</span><br><br>
    누운 셋 중 하나는 숨이 얕다. 다섯이 셋을 들고 사냥은 못 한다.`,
  o:[
    { l:'① 데려가는 대신 길을 치워 주겠다고 한다.', k:'bond', dc:15,
      ok:`데려가겠다고 하지 않았다. 길을 치워 주겠다고 했다. 지도에 표시된 굴 셋. 이쪽이 잡는다. 그쪽 둘이 셋을 옮긴다.<br><br>앉은 둘이 서로 본다. 그것도 일이다. 할 수 있는 일이다.<br>이쪽이 앞에서 굴 셋을 치웠다. 셋째 굴에서 팀원 하나가 크게 물렸다. 뒤에서 그쪽 둘이 셋을 끌고 따라왔다. 계단까지.<br><br>물건을 바꾼 게 아니라 일을 바꿨다. 그쪽이 못 하는 걸 이쪽이 했고 이쪽이 안 할 걸 그쪽이 했다. 흥정판이 하나 넓어졌다.`,
      ng:`길을 치워 주겠다는데 그쪽이 못 믿는다. 치우고 가 버릴 거라고.<br><br>지도를 안 준다. 결국 지도 없이 갔다. 첫 굴을 못 보고 지나쳤다. 등 뒤에서 놈이 나왔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-14, mind:-6 }, wake:1 },
    { l:'② 고기를 주고 지도만 산다.', k:'luck', dc:14,
      ok:`고기 두 줌에 지도를 샀다. 그쪽도 그게 낫다고 했다. 먹어야 기다린다.<br><br>지도는 정확했다. 굴 셋을 다 피해 갔다.<br>계단 앞에서 돌아봤다. 그쪽은 안 보였다.`,
      ng:`샀는데 지도가 틀렸다. 그린 사람이 틀렸다. 일부러는 아니었을 것이다.<br><br>표시 없는 데서 놈이 나왔다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-12, spirit:-8 } },
    { l:'③ 흥정 전에 숨 얕은 사람부터 본다.', k:'heal', dc:14,
      ok:`숨 얕은 사람의 붕대를 풀었다. 상처가 검다. 놈 독이다.<br><br>독은 물로 씻어야 한다. 이쪽 물을 썼다. 반 통.<br>앉은 사람이 지도를 그냥 내밀었다. 흥정 전에 값부터 치르면 상대는 값을 안 부른다.`,
      ng:`붕대를 풀자 냄새가 확 올라온다. 숨을 들이켰다.<br><br>머리가 핑 돈다. 독이 숨으로도 온다. 한참 토했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-10, mind:-8 } }
  ] },

{ at:'C', t:'통로 가운데 — 손가락을 세는 장사꾼',
  x:`통로 가운데 좌판이 있다. 판자 하나에 물건 셋. 말린 고기, 약초, 쇠갈고리.<br><br>
    좌판 뒤에 앉은 것은 사람 모양이다. 대충. 팔꿈치가 하나 더 있다.<br>
    값은 안 적혀 있다. 그것이 이쪽 손가락을 본다. 하나하나 센다.<br><br>
    값을 안 부르는 장사꾼이 제일 비싸다. 이건 그보다 비싸다.`,
  o:[
    { l:'① 손가락 대신 다시 나는 것을 내민다.', k:'bond', dc:15,
      ok:`손가락은 못 준다고 했다. 대신 손톱을 깎아 내밀었다. 다시 나는 것.<br><br>그것이 손톱을 받아 들고 오래 본다. 팔꿈치 셋이 다 접혔다 펴진다.<br>약초 뭉치를 이쪽으로 밀었다.<br><br>다시 나는 것만 받는 장사꾼이다. 머리카락이었으면 고기도 샀을 것이다. 다음엔 기르고 오겠다고 했다.`,
      ng:`말린 고기 셋이라고 불렀다. 그것이 고개를 젓는다. 손가락을 가리킨다.<br><br>안 된다고 손을 거두는데 그것 손이 더 빨랐다. 손등에 손톱자국이 넷 남았다. 넷까지 센 것이다.`,
      win:{ exp:18, dream:2, item:'약초 뭉치' }, lose:{ hp:-10, spirit:-8 } },
    { l:'② 아무것도 안 사고 지나간다.', k:'steady', dc:13,
      ok:`안 산다고 했다. 고개를 숙이고 지나갔다.<br><br>그것은 붙잡지 않았다. 손가락을 끝까지 셌다. 다섯이 다 지나갈 때까지.<br>안 사는 것도 흥정이다. 제일 싼 흥정.`,
      ng:`지나가는데 팀원 하나가 쇠갈고리에 손을 뻗었다.<br><br>만지기만 했다. 그것이 일어선다. 키가 천장에 닿는다. 다섯이 뛰었다. 뒤에서 팔꿈치 접히는 소리가 오래 따라왔다.`,
      win:{ exp:12, dream:1 }, lose:{ mind:-8, spirit:-10 } }
  ] },

{ at:'C', t:'굴 앞 — 외다리 사냥꾼',
  x:`굴 앞에 늙은 사냥꾼이 앉아 있다. 혼자다. 다리 하나가 무릎 아래로 없다.<br><br>
    안에 있는 놈의 약점을 안다고 한다. 어디를 찔러야 한 번에 눕는지.<br>
    값은 꿈결 한 줌. 아니면 이쪽 팀원 하나를 지팡이로 빌려 달라고. 계단까지.<br><br>
    놈이 안에서 숨을 쉰다. 굴 입구 흙이 들썩인다.`,
  o:[
    { l:'① 값은 놈을 잡은 다음에 치르겠다고 한다.', k:'bond', dc:14,
      ok:`팀원을 빌려주지 않았다. 놈을 잡고 나서 팀 전체가 지팡이가 되겠다고 했다.<br><br>노인이 웃는다. 그럼 꼭 잡아야겠다고. 귓속말로 알려 줬다. 목 뒤 비늘 셋째 줄. 거기만 무르다.<br>셋째 줄을 찔렀다. 한 번에 누웠다. 노인을 계단까지 날랐다.<br><br>값을 이긴 다음으로 미루자 파는 쪽도 이쪽이 이기길 바랐다. 값을 앞날에 걸면 상대가 한편이 된다. 그 셈을 처음 써 봤다.`,
      ng:`이긴 다음에 치르겠다는 말에 노인이 고개를 젓는다. 죽은 사람한테는 못 받는다고.<br><br>약점을 못 들었다. 들어가서 아무 데나 찔렀다. 다 단단했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-14, mind:-6 }, wake:1 },
    { l:'② 노인의 다리를 보고 약점을 짐작한다.', k:'gaze', dc:15,
      ok:`노인의 바짓단을 봤다. 찢긴 자리. 이빨 자국이 무릎 높이에서 끝난다.<br><br>놈은 낮게 문다. 그럼 머리가 낮다. 머리가 낮은 놈은 위를 못 본다.<br>굴 천장 쪽에서 내리찍었다. 노인이 그걸 보고 혀를 찼다. 공짜로 알아냈다고.`,
      ng:`짐작이 틀렸다. 놈은 낮게도 물고 높게도 문다.<br><br>노인 다리는 운이 좋았던 쪽이었다. 이쪽 팀원 하나가 어깨를 물렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, spirit:-6 } }
  ] },

{ at:'C', t:'쉬는 자리 — 셋째 순번',
  x:`쉬는 자리. 놈들이 밤에 돈다. 누군가 깨어 있어야 한다.<br><br>
    순번을 정하는데 다들 첫째를 하겠다고 한다. 첫째가 제일 덜 졸리다.<br>
    제일 나쁜 건 셋째다. 한밤이고 놈들이 제일 많이 도는 때다.<br><br>
    아무도 셋째를 안 하겠다고 한다.`,
  o:[
    { l:'① 셋째를 반으로 쪼개 앞 반을 이쪽이 맡는다.', k:'bond', dc:13,
      ok:`셋째를 반으로 갈랐다. 앞 반은 이쪽이 한다고 했다. 뒤 반은 제일 많이 잔 사람.<br><br>이쪽이 먼저 나쁜 걸 집으니 다들 말이 없다. 순번이 금방 정해졌다.<br>한밤에 놈 하나가 불가로 왔다. 깨어 있던 이쪽이 먼저 봤다. 다 깨워 같이 쫓았다.`,
      ng:`쪼갰는데 뒤 반을 맡을 사람이 끝내 안 일어났다.<br><br>이쪽이 셋째를 통으로 섰다. 새벽에 눈을 뜬 채 졸았다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-10, spirit:-4 } },
    { l:'② 막대 다섯으로 제비를 뽑게 한다.', k:'luck', dc:13,
      ok:`손가락 길이로 꺾은 막대 다섯. 하나만 짧게.<br><br>짧은 걸 뽑은 사람이 이쪽을 노려본다. 그래도 군말 없이 섰다. 운한테는 따질 데가 없다.`,
      ng:`짧은 걸 이쪽이 뽑았다. 만든 사람이 뽑았다.<br><br>다들 웃는다. 웃음은 공짜였다. 밤은 길었다.`,
      win:{ exp:12, dream:1 }, lose:{ mind:-8, hp:-8 } },
    { l:'③ 사람 대신 소리 나는 덫을 두르자고 한다.', k:'fix', dc:14,
      ok:`깨어 있는 사람 대신 소리 나는 것을 세웠다. 빈 수통, 쇠붙이, 뼈.<br><br>한밤에 뼈가 울렸다. 다섯이 한꺼번에 깼다. 놈이 줄에 발이 걸려 버둥거리고 있었다.<br>다섯 다 잤다. 다섯 다 깼다. 그게 공평하다.`,
      ng:`줄을 너무 낮게 맸다. 팀원이 볼일 보러 가다 걸렸다.<br><br>쇠붙이가 와르르 울렸다. 그 소리에 진짜 놈들이 모였다.`,
      win:{ exp:15, dream:2, hp:5 }, lose:{ hp:-10, mind:-6 } }
  ] },

{ at:'C1', t:'갈고리 줄 — 수만 맞으면',
  x:`천장 레일을 따라 갈고리가 돈다. 갈고리마다 고깃덩이가 걸렸다. 잘린 자리에 새 살이 오르고 있다.<br><br>
    그중 하나에 사람이 걸렸다. 다른 팀 옷이다. 갈고리가 허리띠에 걸렸다. 살아 있다.<br>
    줄 끝에 앞치마 두른 것이 서서 갈고리를 센다. 하나 지날 때마다 손가락을 하나 꺾는다.<br><br>
    세는 것은 수가 맞으면 아무 말도 안 한다.`,
  o:[
    { l:'① 사람을 내리고 빈 갈고리에 고깃덩이를 대신 건다.', k:'bond', dc:15,
      ok:`사람을 내리고 빈 갈고리에 바닥의 고깃덩이를 걸었다. 무게가 비슷한 것으로.<br><br>줄 끝의 것이 손가락을 꺾는다. 하나. 멈추지 않는다. 다음 갈고리로 간다.<br>수만 맞으면 된다. 뭐가 걸렸는지는 안 본다. 사람을 셀 줄 모르는 것이다. 고기만 셀 줄 안다.<br><br>내린 사람이 이쪽 소매를 잡고 떤다.<br>상대가 무엇을 세는지 알면 무엇을 바꿔 줘도 되는지 안다. 사람 아닌 것과도 값을 맞췄다.`,
      ng:`사람을 내리는 사이 줄이 한 칸 갔다. 빈 갈고리가 그대로 지나갔다.<br><br>줄 끝의 것이 손가락을 꺾다 멈춘다. 고개가 이쪽으로 돈다. 모자라는 하나를 찾는 눈이다.<br>사람을 둘러업고 뛰었다. 갈고리 하나가 레일을 벗어나 따라왔다. 등을 긁고 갔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-8 }, wake:1 },
    { l:'② 손가락을 꺾는 박자를 보고 틈을 노린다.', k:'gaze', dc:14,
      ok:`손가락 꺾는 박자를 셌다. 열을 꺾으면 손을 털고 다시 편다. 그때 한 박자 쉰다.<br><br>그 한 박자에 사람을 내렸다. 빈 갈고리가 지나갔다. 세는 것은 손을 다 털고 나서 다시 셌다. 처음부터.<br>세던 것을 놓치면 처음부터 센다. 그건 사람이나 저것이나 같다.`,
      ng:`쉬는 박자가 아니었다. 손을 털다가 이쪽을 봤다.<br><br>앞치마 주머니에서 갈고리가 하나 더 나왔다. 이쪽 몫이다. 다들 뛰었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-10, spirit:-10 } }
  ] },

{ at:'C1', t:'계근대 — 수평이 되면 열린다',
  x:`큰 저울이 통로를 막았다. 한쪽 접시에 추가 올라 있다. 다른 쪽은 비었다.<br><br>
    저울 너머에 문이 있다. 접시가 수평이 되면 열린다. 문틀에 손바닥 자국이 겹겹이 찍혔다.<br>
    바닥에 고깃덩이가 쌓여 있다. 썰어 놓은 것들이다. 보는 사이 한 덩이가 꿈틀하며 조금 커졌다.<br><br>
    흥정하는 사람은 저울을 보면 누가 속였는지부터 본다.`,
  o:[
    { l:'① 저울추를 들어 본다.', k:'gaze', dc:14,
      ok:`추를 들어 봤다. 생긴 것보다 가볍다. 속이 비었다.<br><br>속에 뭔가 들었다. 꺼내 보니 소금 덩이다. 누가 추를 파내고 소금을 숨겼다.<br>소금을 빼고 추를 올렸다. 가벼워진 만큼 고기를 덜 올려도 맞았다.`,
      ng:`추를 드는 순간 반대쪽 접시가 튀어 올랐다.<br><br>문이 아니라 바닥 덮개가 열렸다. 다리 하나가 빠졌다. 아래에서 무언가 핥았다.`,
      win:{ exp:16, dream:2, item:'소금 덩이' }, lose:{ hp:-12, spirit:-6 } },
    { l:'② 고깃덩이를 하나씩 올려 맞춘다.', k:'fix', dc:14,
      ok:`한 덩이씩 올렸다. 접시가 조금씩 내려온다.<br><br>마지막 덩이를 올리기 직전 접시가 수평에 닿았다. 올려 둔 고기가 그사이 자란 것이다. 문이 열렸다.<br>자라는 고기는 저울을 속인다. 이번엔 이쪽 편이었다.`,
      ng:`올리는 사이 고기가 계속 자랐다. 수평을 지나 기울었다.<br><br>덜려고 손을 넣었다. 접시 위 고기가 손을 물었다. 이빨이 없는데 물었다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-14, mind:-6 } },
    { l:'③ 다섯이 같이 접시에 올라선다.', k:'bond', dc:15,
      ok:`한 사람이 올라가면 그 사람이 값이 된다. 다섯이 같이 올라갔다. 어깨를 붙이고.<br><br>접시가 내려온다. 수평이 되고 문이 열렸다. 다섯이 같이 내려섰다. 접시가 튀어 올랐지만 문은 열린 채다.<br>문틀의 손바닥 자국은 다 하나씩이었다. 혼자 올라섰던 사람들이다.`,
      ng:`맨 끝 사람이 먼저 내렸다. 겁이 났다고.<br><br>접시가 기울며 넷이 고기더미 쪽으로 쏟아졌다. 미끄러웠다. 따뜻했다. 기어 나오는 데 한참 걸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, mind:-8 } }
  ] },

{ at:'C1', t:'라인 끝 — 지워지지 않은 칸',
  x:`줄 맨 끝에 그것이 있다. 앞치마는 젖었고 칼은 크다. 쉬지 않는다.<br><br>
    갈고리가 오면 썰고 썬 것을 바닥에 던진다. 던진 것이 다시 자라 갈고리에 오른다. 끝이 없다.<br>
    벽에 판이 걸려 있다. 근무표다. 칸마다 손가락으로 문질러 지웠다. 마지막 칸만 안 지워졌다.<br><br>
    일하는 쪽이 원하는 건 다 알면 누구든 같다. 일이 끝나는 것이다.`,
  o:[
    { l:'① 근무표 마지막 칸을 지워 준다.', k:'bond', dc:15,
      ok:`바닥에 고인 것을 손가락에 묻혀 마지막 칸을 그었다. 그것이 볼 수 있게 천천히.<br><br>칼이 멈춘다. 그것이 판을 본다. 오래. 그리고 앞치마 끈을 푼다.<br>바닥에 앉았다. 줄이 멈췄다. 갈고리들이 덜컥거리다 조용해졌다.<br><br>지나가는 동안 그것은 고개를 숙이고 있었다. 일이 끝난 쪽은 길을 막지 않는다.`,
      ng:`칸을 그었는데 판 아래에 칸이 하나 더 생겼다.<br><br>판이 길어진다. 칸이 계속 생긴다. 그것이 이쪽을 봤다. 일을 늘린 쪽을.<br>칼이 이쪽으로 왔다. 팀원들이 끌어냈다. 소매가 없어졌다. 소매만.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-16, spirit:-8 } },
    { l:'② 던진 고기가 다시 자라는 틈에 줄 아래로 지나간다.', k:'hide', dc:15,
      ok:`던진 고기가 다시 자라 오르는 데 열을 센다. 그 열 사이에 줄 아래로 지나갔다. 한 사람씩.<br><br>마지막 사람이 지날 때 칼이 머리 위를 지나갔다. 머리카락 한 줌이 떨어졌다.<br>떨어진 머리카락은 안 자랐다. 사람 것이니까.`,
      ng:`열을 세다가 자라는 게 빨라졌다. 일곱에 다 자랐다.<br><br>고기가 갈고리에 오르며 이쪽 어깨를 밀었다. 그것의 칼 아래로.<br>팀원이 허리를 잡아당겼다. 어깨에 칼날이 스쳤다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-18, mind:-6 } }
  ] },

{ at:'C2', t:'진열장 — 값표',
  x:`진열장에 인형이 줄지어 섰다. 사기 얼굴. 입이 살짝 벌어졌다. 안에 이가 있다. 사람 이다. 작다.<br><br>
    목마다 값표가 걸렸다. 숫자가 아니다. '앞니 둘.' '송곳니 하나.' '어금니.'<br>
    맨 끝 하나는 이가 없다. 값표에 '흥정함'이라고 적혔다.<br><br>
    그 인형 발밑에 서랍이 있다. 틈으로 꿀 냄새가 난다. 인형이 서랍 앞을 막고 섰다.`,
  o:[
    { l:'① 이 없는 인형과 흥정한다.', k:'bond', dc:15,
      ok:`사냥한 놈 이빨을 하나 꺼냈다. 아래층에서 뽑아 둔 것이다.<br><br>인형 입에 대 주니 문다. 잇몸에 끼운다. 하나가 생겼다. 인형이 반 걸음 비켜선다.<br>서랍에 꿀 한 줌이 굳어 있었다.<br><br>나오며 돌아보니 인형이 이쪽 팀원들 입을 보고 있다. 다음 흥정을 준비하는 눈이다. 다들 입을 다물고 나왔다.`,
      ng:`말린 고기를 내밀었다. 인형이 고개를 젓는다.<br><br>그리고 이쪽 입을 본다. 진열장 인형들이 다 같이 이쪽 입을 본다. 값표를 하나 더 쓰는 소리가 났다. 뒷걸음쳤다. 한 놈이 따라와 종아리를 물었다.`,
      win:{ exp:20, dream:2, item:'꿀 한 줌' }, lose:{ hp:-12, spirit:-8 } },
    { l:'② 인형이 고개를 돌린 틈에 서랍째 빼낸다.', k:'evade', dc:15,
      ok:`인형이 고개를 다른 데로 돌리는 순간을 기다렸다. 서랍을 통째로 빼냈다.<br><br>꿀이 있다. 굳었다. 인형이 돌아본다. 서랍이 없는 걸 본다.<br>값표에 글자가 늘었다. '도둑.' 진열장 전체가 그 글자를 읽었다. 뛰었다.`,
      ng:`빼내는데 서랍이 걸렸다. 인형 손이 이쪽 손목을 짚는다. 사기 손인데 따뜻하다.<br><br>손목 살을 꼬집듯 물었다. 손바닥에도 이가 있었다.`,
      win:{ exp:15, dream:2, item:'꿀 한 줌' }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C2', t:'천장의 실 — 위층에 대고',
  x:`천장에서 실이 내려와 팀원 손목에 감겼다. 발목에도. 팀원이 걷는다. 자기 걸음이 아니다.<br><br>
    실은 위층 바닥 틈으로 올라간다. 위에서 누가 쥐고 있다. 손가락 움직이는 박자가 실을 타고 내려온다.<br>
    팀원 눈은 울고 입은 웃는다. 위에서 웃게 했다.<br><br>
    협상가는 위를 본다. 쥔 쪽과 말을 해야 한다.`,
  o:[
    { l:'① 위를 향해 더 나은 재료를 대 준다.', k:'bond', dc:15,
      doom:{ title:'위층의 손', what:'인형 실에 매달려 위층으로 끌려갑니다', dc:15, sec:60,
        text:`위에 대고 말했다. 그 사람을 놓으면 대신 무엇을 주겠다고.<br><br>실이 멈춘다. 그리고 새 실이 내려온다. 이쪽 손목으로. 대답이다.<br>값을 부르면 듣는 쪽이 고른다. 위에서 이쪽을 골랐다.<br><br>발이 바닥에서 뜬다. 천장 틈이 가까워진다.`,
        dieText:`위층에 인형이 하나 늘었다.<br><br>손은 흥정할 때처럼 펴져 있다. 손바닥이 위로.<br>입은 웃는다. 위에서 웃게 했다.` },
      ok:`위에 대고 말했다. 그 사람은 손이 느리다고. 실을 당겨도 굼뜰 거라고. 이 층 인형들이 훨씬 잘 움직인다고.<br><br>한참 조용하다. 팀원 손목의 실이 느슨해진다. 위에서 팀원을 놓고 진열장 인형 하나를 집어 올린다.<br>물건을 더 좋은 물건으로 바꾸자고 했다. 위에 있는 것은 장사꾼이 아니라 장인이었다. 장인은 더 좋은 재료를 마다하지 않는다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 실을 한 가닥씩 끊는다.', k:'break', dc:14,
      ok:`칼로 실을 끊었다. 손목, 발목.<br><br>팀원이 쓰러진다. 끊긴 실 끝이 위로 빨려 올라간다. 위층에서 쿵 소리가 났다. 무언가 일어섰다.<br>그 뒤로 머리 위에서 발소리가 따라다녔다.`,
      ng:`끊은 자리에서 실이 다시 내려왔다. 둘이 되어.<br><br>둘은 이쪽 손목으로 왔다. 겨우 칼로 걷어 냈다. 손목에 실 자국이 하얗게 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-10 } }
  ] },

{ at:'C2', t:'선반 — 다섯 자리, 여섯 인형',
  x:`선반 하나에 자리가 다섯. 인형은 여섯이다.<br><br>
    밀려난 하나가 선반 아래서 다른 것들 발목을 문다. 물린 것이 떨어진다. 떨어진 것이 또 문다.<br>
    사기 깨지는 소리가 쉬지 않는다. 깨진 데서 이가 쏟아진다. 소리를 듣고 다른 방 인형들이 모여든다.<br><br>
    여섯이 다섯 자리에 서는 법은 없다. 자리를 하나 더 만드는 법은 있다.`,
  o:[
    { l:'① 이쪽 배낭을 선반 끝에 놓아 자리를 하나 만든다.', k:'bond', dc:14,
      ok:`배낭을 선반 끝에 올렸다. 평평하게 눌러 자리를 만들었다.<br><br>밀려난 것을 집어 그 위에 세웠다. 이가 손가락을 스쳤다. 세워 두니 물기를 멈춘다. 여섯이 섰다.<br>깨지는 소리가 그쳤다. 모여들던 것들이 제자리로 돌아간다.<br><br>배낭은 거기 두고 왔다. 다툼을 멎게 하는 게 몫을 나누는 것만은 아니다. 놓을 자리를 하나 더 만드는 것. 손이 먼저 했고 머리는 나중에 알았다.`,
      ng:`배낭을 올리는데 인형 둘이 같이 그 자리로 왔다.<br><br>자리 하나에 둘. 다시 다툼이다. 이번엔 배낭을 문다. 배낭 끈을 잡고 있던 이쪽 손도.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-12, mind:-8 }, wake:1 },
    { l:'② 밀려난 것을 깨서 다섯으로 맞춘다.', k:'break', dc:14,
      ok:`밀려난 것의 머리를 쳤다. 사기가 갈라진다. 안에서 이가 쏟아진다.<br><br>다섯이 남았다. 다섯 자리에. 조용해졌다.<br>그 대신 진열장 전부가 이쪽을 본다. 수를 맞춘 쪽을.`,
      ng:`쳤는데 머리만 깨졌다. 몸이 이쪽 다리를 타고 오른다.<br><br>머리 없이도 문다. 손바닥에도 이가 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C3', t:'둥근 천장 골 — 거꾸로 달린 헌금함',
  x:`성당이 뒤집혔다. 발밑은 둥근 천장이다. 머리 위에 의자들이 거꾸로 박혀 있다.<br><br>
    둥근 천장 골을 따라 걷는다. 길 한가운데 헌금함이 있다. 거꾸로. 돈 넣는 구멍이 아래로 났다.<br>
    그 앞을 지나는 사람마다 무언가 넣고 갔다. 골 바닥에 넣다 흘린 것들이 있다. 단추. 이. 반지.<br><br>
    헌금함 둘레에 종 같은 것들이 놓였다. 아가리를 위로 하고. 아무것도 안 넣고 지나가는 쪽을 기다린다.`,
  o:[
    { l:'① 흘린 것들을 보고 무엇을 받는지 짐작한다.', k:'gaze', dc:15,
      ok:`흘린 것을 하나씩 봤다. 다 넣다가 떨어진 것이다. 구멍이 아래로 나서.<br><br>떨어진 건 받아 주지 않은 것이다. 단추, 반지, 이. 그럼 받아 준 건 남지 않은 것이다.<br>숨을 불어 넣었다. 구멍에 대고 길게. 함 속에서 짤랑 소리가 났다. 종 같은 것들이 다 같이 한 번 울렸다. 그리고 비켜났다.`,
      ng:`반지를 주워 다시 넣었다. 떨어졌다. 이쪽 손등으로.<br><br>반지가 손가락을 찾아 굴러온다. 끼워진다. 빠지지 않는다. 차다. 손가락 끝이 하얘진다.`,
      win:{ exp:18, dream:2 }, lose:{ spirit:-12, mind:-6 } },
    { l:'② 골에서 내려서 비탈로 크게 돌아간다.', k:'evade', dc:15,
      ok:`골에서 내려섰다. 둥근 천장은 비탈이다. 바깥쪽으로 비스듬히 걸었다.<br><br>헌금함 옆을 크게 돌았다. 종 같은 것들이 이쪽을 따라 돌아본다. 안 넣고 지나가는 쪽을.<br>울리지는 않았다. 대신 그 뒤로 내내 팀 뒤에 하나가 따라왔다. 굴러서.`,
      ng:`비탈에서 발이 미끄러졌다. 둥근 천장 아래로. 아래라는 게 원래는 위다.<br><br>골 바닥의 종 같은 것이 입처럼 벌어졌다. 팀원이 발목을 잡았다. 신발 한 짝이 들어갔다. 안에서 짤랑 소리가 났다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-12, spirit:-8 } }
  ] },

{ at:'C3', t:'성가대석 — 빈 성부',
  x:`성가대석이 머리 위에 거꾸로 붙어 있다. 거기 앉은 것들이 노래한다.<br><br>
    한 몸에 입이 여럿이다. 목에도, 손바닥에도. 입마다 다른 소리를 낸다. 그래도 화음이다.<br>
    노래가 이쪽을 향하면 팀원들 입이 따라 벌어진다. 소리는 안 나는데 입이 벌어진다.<br><br>
    맨 앞의 것이 손바닥 입으로 이쪽을 가리킨다. 한 성부가 비었다. 채워 달라는 것이다.`,
  o:[
    { l:'① 저 문까지만 채워 주겠다고 끝을 정한다.', k:'bond', dc:15,
      ok:`한 곡이 아니라 저 문 앞까지라고 했다. 거기서 끝내자고.<br><br>맨 앞의 것이 고개를 끄덕인다. 목의 입 하나가 웃는다.<br>흥얼거리며 걸었다. 빈 성부를. 노래가 팀원들을 비껴갔다. 벌어졌던 입들이 닫혔다.<br><br>문 앞에서 멈췄다. 노래도 멈췄다. 약속한 데까지. 한 소절도 더 부르지 않고 덜 부르지도 않았다.<br>값을 다 치르고 정확히 거기서 끊는 것. 끝을 정하는 것도 흥정이었다. 목이 쉬었다. 끊는 자리는 또렷이 남았다.`,
      ng:`문까지라는 말에 성가대가 웃는다. 입이 다 같이.<br><br>노래에 끝이 없다. 문 앞까지 갔는데 멈출 수가 없다. 팀원이 입을 손으로 막아 줬다. 목에서 피 맛이 났다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-12, spirit:-8 }, wake:1 },
    { l:'② 귀를 틀어막고 입을 손으로 누르며 지나간다.', k:'steady', dc:14,
      ok:`천을 찢어 귀를 막았다. 다들 손바닥을 입에 댔다. 벌어지지 않게.<br><br>노래가 몸을 지나간다. 들리지 않아도 이가 떨린다.<br>문까지 갔다. 성가대가 끝까지 이쪽을 봤다. 한 성부가 빈 채로.`,
      ng:`귀를 막았는데 소리가 손바닥으로 들어온다.<br><br>팀원 하나가 따라 불렀다. 목에서 다른 사람 목소리가 나왔다. 입을 막고 끌고 나왔다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-10, spirit:-10 } }
  ] },

{ at:'C3', t:'고해실 — 비밀 하나에 길 하나',
  x:`거꾸로 매달린 고해실이 있다. 지붕이 둥근 천장에 박혔다. 창살이 이쪽 눈높이다.<br><br>
    창살 너머에서 무언가 숨 쉰다. 말을 건다. 비밀 하나를 주면 길 하나를 알려 주겠다고.<br>
    비밀에도 값이 있다. 남의 비밀은 싸고 제 비밀은 비싸다.<br><br>
    창살 아래 손톱자국이 있다. 다 안쪽으로 긁혔다.`,
  o:[
    { l:'① 팔기 전에 그쪽 비밀부터 들어 보자고 한다.', k:'bond', dc:15,
      doom:{ title:'고해실', what:'고해실 창살 안으로 끌려 들어갑니다', dc:15, sec:55,
        text:`비밀을 사려면 그쪽 비밀부터 들어 보자고 했다.<br><br>창살 너머가 조용하다. 그리고 속삭인다. 너무 작아서 안 들린다. 귀를 댔다.<br>창살 사이로 손이 나와 귀를 잡는다. 더 가까이. 비밀은 가까이서만 들린다고.<br><br>얼굴이 창살에 눌린다. 창살이 벌어진다.`,
        dieText:`비밀은 하나였다.<br><br>창살 안에 있던 것은 처음부터 하나가 아니었다는 것.<br>이제 창살 너머에서 둘이 숨 쉰다. 다음 사람에게 길을 판다.` },
      ok:`그쪽 비밀부터 들어 보자고 했다. 창살 너머가 오래 조용하다.<br><br>사는 쪽이 팔기를 바라니 저것도 망설인다. 팔기만 해 봤지 사 줄 사람을 만난 적은 없었던 것이다.<br>그러다 작게 말한다. 내려가는 구멍은 고해실 밑이라고. 자기는 거기로 못 나간다고. 그게 비밀이었다.<br><br>이쪽은 아무것도 안 팔았다. 길을 공짜로 얻었다. 저것은 비밀을 팔고 나서 처음으로 가벼운 숨을 쉬었다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 하찮은 비밀 하나를 판다.', k:'luck', dc:14,
      ok:`어릴 적 남의 감을 몰래 딴 일을 팔았다. 하찮다.<br><br>창살 너머가 웃는다. 그래도 받는다. 하찮아도 비밀은 비밀이다.<br>길을 알려 줬다. 왼쪽 골 셋째 갈빗대 밑. 가 보니 내려가는 구멍이 있었다.`,
      ng:`하찮은 걸 팔았다. 창살 너머가 실망한다.<br><br>대신 이쪽이 잊고 있던 비밀 하나를 말해 준다. 이쪽도 모르던 것을. 그걸 듣고 한참 걷지 못했다.`,
      win:{ exp:16, dream:2 }, lose:{ spirit:-14, mind:-6 } }
  ] },

{ at:'C4', t:'물 주는 시간 — 작업복을 입은 것',
  x:`온실 통로에 정원사가 물뿌리개를 들고 있다. 작업복, 장화, 챙 넓은 모자.<br><br>
    모자 아래가 버섯이다. 소매 끝에서 하얀 실이 손가락처럼 갈라진다. 옷 안에 사람은 없다. 옷만 일한다.<br>
    버섯마다 물을 준다. 이쪽 팀이 지나야 할 통로에도. 물이 닿은 자리에서 포자가 핀다.<br><br>
    일하는 쪽과는 말할 수 있다. 일만 안 막으면 된다.`,
  o:[
    { l:'① 대신 물을 주겠다며 물뿌리개를 넘겨받는다.', k:'bond', dc:15,
      ok:`다가가서 물뿌리개 손잡이를 같이 쥐었다. 이쪽이 하겠다고. 쉬라고.<br><br>작업복이 멈춘다. 모자가 기운다. 손을 놓는다. 그 자리에 앉는다. 앉으니 그냥 옷더미 같다.<br>물뿌리개를 들고 통로를 지나갔다. 버섯 없는 쪽에만 물을 줬다. 아무도 따지지 않았다.<br><br>통에 남은 물은 맑았다. 버섯 주던 물이 아니라 사람 먹던 물이다. 옛날 정원사가 받아 둔.`,
      ng:`손잡이를 쥐자 소매 끝 하얀 실이 이쪽 손등을 덮는다.<br><br>일을 넘겨받는 게 아니라 옷을 넘겨받을 뻔했다. 손등을 칼로 긁어 냈다. 따끔한 게 오래갔다.`,
      win:{ exp:20, dream:3, item:'맑은 물' }, lose:{ hp:-12, spirit:-8 } },
    { l:'② 모자를 쳐서 떨어뜨린다.', k:'break', dc:14,
      ok:`모자를 쳤다. 버섯 머리가 통째로 떨어진다. 작업복이 무너진다.<br><br>무너진 옷 안에서 포자가 한숨처럼 나왔다. 천으로 입을 막았다.<br>장화 안에 산나물이 한 줌 말라 있었다. 정원사가 일하다 먹던 것이다.`,
      ng:`쳤는데 모자만 날아갔다. 버섯 머리가 이쪽을 본다.<br><br>포자가 얼굴로 터졌다. 눈이 따갑다. 기침에 녹색이 섞였다.`,
      win:{ exp:16, dream:2, item:'산나물' }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C4', t:'양치식물 사이 — 가루가 안 닿는 거리',
  x:`양치식물 사이에 포자 짐승이 엎드렸다. 등이 버섯으로 덮였다. 숨 쉴 때마다 등에서 가루가 오른다.<br><br>
    안 다가온다. 안 물러난다. 이쪽과 짐승 사이가 딱 가루가 안 닿는 만큼이다.<br>
    그 너머가 다음 단으로 내려가는 길이다.<br><br>
    거리를 정하는 것도 흥정이다. 짐승은 이미 정했다. 지나가려면 다시 정해야 한다.`,
  o:[
    { l:'① 고기를 길에서 먼 쪽으로 던져 거리를 옮긴다.', k:'bond', dc:14,
      ok:`짐승 고기 한 점을 던졌다. 길에서 먼 쪽으로.<br><br>짐승이 일어나 고기 쪽으로 간다. 거리는 그대로다. 짐승이 움직였으니 거리가 같이 움직였다. 가루가 안 닿는 원이 길에서 비켜났다.<br>그 틈으로 지나갔다. 짐승은 고기를 먹으며 끝까지 이쪽과 거리를 지켰다.`,
      ng:`너무 가깝게 던졌다. 짐승이 고기를 물러 오며 거리가 반으로 줄었다.<br><br>가루가 닿았다. 눈물이 그치지 않았다. 팀원 하나는 목이 부었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, mind:-6 } },
    { l:'② 바람을 등지고 크게 돌아간다.', k:'sense', dc:14,
      ok:`유리에 금 간 데가 있다. 바람이 들어온다. 그 바람을 등지고 돌았다.<br><br>가루는 바람을 거슬러 못 온다. 짐승 등 가루가 반대쪽으로 날린다.<br>한참 돌아서 길에 닿았다. 짐승이 이쪽을 보고 돌아앉았다. 거리를 다시 정한 것이다.`,
      ng:`돌다 보니 바람이 바뀌었다. 온실은 바람도 갇혀서 돌고 돈다.<br><br>가루가 등 뒤에서 왔다. 목덜미가 가렵다. 가려운 데가 단단해진다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-10, spirit:-8 } }
  ] },

{ at:'C4', t:'약초 상자 — 한 뭉치, 두 팀',
  x:`온실 구석에 약초 상자가 있다. 포자에 안 먹힌 풀이다. 한 뭉치뿐이다.<br><br>
    다른 팀이 먼저 손을 댔다. 저쪽에 하나, 이쪽에 하나. 포자를 마신 사람이 있다. 둘 다 숨에서 쇳소리가 난다.<br>
    한 뭉치를 둘이 나누면 둘 다 반만 낫는다. 여기서 반만 나으면 안 나은 것이다.<br><br>
    저쪽 반장이 칼자루에 손을 얹는다. 이쪽 반장도.`,
  o:[
    { l:'① 먼저 손댄 쪽에 주고, 다음 뭉치는 같이 찾자고 한다.', k:'bond', dc:15,
      ok:`먼저 손댄 쪽이 먼저라고 했다. 이쪽 팀원 숨소리가 등 뒤에서 거칠다. 그래도 그렇게 말했다.<br><br>대신 다음 뭉치는 두 팀이 같이 찾자고. 찾으면 이쪽 것이다. 저쪽 반장이 칼자루에서 손을 뗐다.<br>상자 바닥에 모종 칸 번호가 적혀 있다. 열이 그 칸을 뚫었다. 포자 짐승 둘을 잡았다. 풀이 있었다.<br><br>이쪽 팀원 숨이 고르게 돌아왔다.<br>제 몫을 뒤로 미는 흥정은 처음이다. 미는 동안 한편이 생겼다. 그 한편이 몫을 찾아다 줬다.`,
      ng:`먼저 손댄 쪽이 먼저라고 하자 이쪽 반장이 이쪽을 본다. 남의 편을 드냐는 눈이다.<br><br>두 팀이 갈라섰다. 이쪽은 혼자 모종 칸을 뚫었다. 다섯으로는 짐승 둘이 버거웠다. 풀은 찾았다. 많이 다쳤다.`,
      win:{ exp:25, dream:4, item:'약초 뭉치' }, lose:{ hp:-16, mind:-8 }, wake:1 },
    { l:'② 통째로 끓여 둘이 김을 같이 쐬게 한다.', k:'heal', dc:15,
      ok:`반씩 먹이는 대신 통째로 끓였다. 두 사람을 김 위에 마주 앉혔다.<br><br>김이 둘에게 고르게 간다. 반씩이 아니라 같이 다. 쇳소리가 잦아든다.<br>두 반장이 칼에서 손을 뗀 건 김이 다 오르고 나서였다.`,
      ng:`끓이는데 불이 포자에 닿았다. 퍽 하고 가루가 터졌다.<br><br>김 대신 가루를 다 같이 마셨다. 쇳소리가 넷이 됐다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-12, mind:-8 } }
  ] }

]);

// ──────────────────────────────────────────
// 결속술사 (binder) · 마력
// ──────────────────────────────────────────
kJob('binder', 'C', [

{ at:'C', t:'사냥 전 — 늘어나는 실',
  x:`사냥에 들어가기 전에 실을 꼰다. 이번엔 길게.<br><br>
    사냥은 흩어진다. 몰고, 숨고, 돌아서 막는다. 실이 짧으면 끊기고 길면 엉킨다.<br>
    결속술사는 실 길이를 사람 사이 거리로 잰다. 오늘 거리는 모른다. 놈이 정한다.<br><br>
    마력을 많이 넣으면 실이 늘어난다. 많이 넣으면 많이 빠진다.`,
  o:[
    { l:'① 마력을 감아 넣어 늘었다 줄었다 하는 실을 꼰다.', k:'bond', dc:14, cost:{ mana:18 },
      ok:`마력을 실 속에 감아 넣었다. 당기면 늘고 놓으면 줄게.<br><br>사냥이 시작되자 다섯이 흩어졌다. 실이 따라 늘었다. 놈이 막내 쪽으로 돌자 막내 실이 팽팽해졌다. 당기기도 전에 알았다.<br>네 가닥을 한꺼번에 당겼다. 넷이 막내 쪽으로 모였다. 놈을 거기서 잡았다.<br><br>실은 묶는 것이라고 배웠다. 오늘 실은 모으는 것이었다. 늘었다 줄었다 하는 꼼을 손가락이 기억했다.`,
      ng:`많이 넣었더니 실이 너무 늘었다. 흩어진 사람들 사이에서 축 처진다.<br><br>처진 실은 아무것도 안 알려 준다. 놈이 실 사이로 지나갔다. 두 가닥이 놈 다리에 걸려 끌려갔다. 끊었다. 손목이 탔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-10, mind:-8 }, wake:1 },
    { l:'② 짧은 실로 둘씩 짝지어 묶는다.', k:'fix', dc:13,
      ok:`다섯을 둘, 둘, 하나로 묶었다. 하나는 이쪽이다.<br><br>둘씩 묶인 사람들은 서로를 놓치지 않는다. 사냥 내내 짝이 짝을 끌었다.<br>이쪽은 혼자였다. 혼자인 쪽이 제일 많이 다쳤다.`,
      ng:`짝끼리 실이 엉켰다. 둘이 반대로 뛰다 같이 넘어졌다.<br><br>넘어진 둘 위로 놈이 지나갔다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-14, mind:-4 } }
  ] },

{ at:'C', t:'사냥 — 기둥 같은 다리',
  x:`놈이 크다. 다리가 넷이다. 창이 안 들어간다. 너무 빨리 돈다.<br><br>
    팀원들이 이쪽을 본다. 다리를 묶으면 선다.<br>
    마력 실은 사람 손목 굵기로 꼬는 것이다. 놈 다리는 기둥만 하다.<br><br>
    실은 양쪽을 다 묶는다. 이쪽 끝은 이쪽 손목이다.`,
  o:[
    { l:'① 마력을 쏟아 굵은 실로 앞다리 둘을 묶는다.', k:'bond', dc:15, cost:{ mana:22 },
      doom:{ title:'묶인 쪽', what:'묶은 놈에게 끌려갑니다', dc:15, sec:60,
        text:`실을 던졌다. 앞다리 둘에 감겼다. 마력을 쏟아 조였다.<br><br>놈이 넘어지지 않는다. 대신 돈다. 묶인 다리로 버티고 몸을 틀어 뛴다.<br>실 반대쪽 끝은 이쪽 손목이다. 바닥에 끌린다. 돌에 부딪힌다.<br><br>끊으면 놈이 풀린다. 안 끊으면 끌려간다. 팀원들이 실을 잡으러 달려온다. 실은 이쪽 눈에만 보인다.`,
        dieText:`놈은 굴로 들어갔다. 실을 끌고.<br><br>굴 입구에 실 한 가닥이 남아 빛난다. 당기면 한참 뒤에 한 번 당겨 온다.<br>누가 당기는지는 들어가 봐야 안다. 아무도 안 들어갔다.` },
      ok:`앞다리 둘에 감고 조였다. 놈이 몸을 튼다.<br><br>이쪽은 버티지 않았다. 실 끝을 손목에서 풀어 바닥 바위에 감았다. 묶은 쪽을 바꿨다. 놈은 바위와 묶였다.<br>놈이 넘어졌다. 창 셋이 들어갔다.<br><br>실을 거두는데 손목이 저리다. 바위에 감을 생각을 반 박자만 늦게 했으면 바위 대신 이쪽이었다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 창 다섯을 실로 이어 울타리를 친다.', k:'fix', dc:14,
      ok:`창 다섯을 실로 이어 세웠다. 울타리처럼.<br><br>놈이 돌다가 울타리에 걸렸다. 창끝이 사방에서 놈을 막는다. 돌 데가 없어지자 섰다.<br>선 놈은 잡힌다.`,
      ng:`울타리가 놈보다 약했다. 한 번 들이받자 창 다섯이 다 쓰러졌다.<br><br>쓰러진 창에 실이 엉켰다. 다섯이 다 실에 걸려 넘어졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C', t:'어둠 속 — 가벼워진 한 가닥',
  x:`어둠 속에서 한 가닥이 끊겼다. 셋째 팀원 것이다.<br><br>
    당겨지지 않았다. 그냥 가벼워졌다. 실 끝이 축 늘어진다.<br>
    끊긴 실은 끊긴 자리를 기억한다. 끝을 만지면 어떻게 끊겼는지 안다. 잘렸는지, 물렸는지, 녹았는지.<br><br>
    끝이 젖었다. 따뜻하다.`,
  o:[
    { l:'① 끝을 쥐고 끊긴 자리를 읽는다.', k:'gaze', dc:14,
      ok:`끝을 손가락으로 비볐다. 이빨에 끊긴 게 아니다. 녹았다. 놈 침이다. 침 흘리는 놈은 낮게 엎드린다.<br><br>바닥을 따라갔다. 낮은 굴이다. 셋째가 안에 있다. 놈은 셋째 실만 먹고 셋째는 아직 안 먹었다. 실이 먼저 맛있었던 것이다.<br>마력 냄새가 놈을 부른다는 걸 그때 알았다.<br><br>끊긴 끝에서 끊은 것을 읽었다. 실에는 무엇이 다녀갔는지 남는다. 손끝이 그걸 듣기 시작했다.`,
      ng:`끝을 비비는데 침 묻은 손가락이 저려 온다.<br><br>마력이 녹아 나간다. 손가락 끝 감각이 없어졌다. 셋째는 다른 팀원이 소리로 찾았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-10, spirit:-6 }, wake:1 },
    { l:'② 남은 넷의 실을 거둬 둘씩 짝지어 찾는다.', k:'bond', dc:14,
      ok:`넷의 실을 거둬 둘씩 이었다. 한 짝은 왼쪽, 한 짝은 오른쪽.<br><br>왼쪽 짝이 먼저 찾았다. 실을 두 번 당겨 왔다. 오른쪽 짝을 끌고 갔다.<br>셋째는 낮은 굴 앞에 쓰러져 있었다. 굴 안에서 놈이 실 끝을 씹고 있었다.`,
      ng:`둘씩 묶는 사이 한 짝이 너무 멀리 갔다. 실이 끊겼다.<br><br>찾을 사람이 셋으로 늘었다. 다 찾는 데 반나절이 걸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-10, spirit:-8 } }
  ] },

{ at:'C', t:'떠는 실 — 밟고 오는 것',
  x:`넷째 팀원 실이 떤다. 당기는 게 아니라 떤다.<br><br>
    무언가 실을 타고 온다. 실은 이쪽 눈에만 보이는데, 그것은 실을 밟고 온다. 다리가 많고 가볍다.<br>
    넷째는 저 멀리서 놈과 싸우고 있다. 실에 신경 쓸 틈이 없다.<br><br>
    실 끝은 이쪽 손목이다. 그것이 반쯤 왔다.`,
  o:[
    { l:'① 실을 세게 튕겨 떨어뜨린다.', k:'bond', dc:14,
      ok:`실을 손가락에 걸고 세게 튕겼다. 활시위처럼.<br><br>밟고 오던 것이 공중에 뜬다. 떨어진다. 바닥에서 버둥거린다. 손바닥만 하다. 등에 눈이 줄지어 났다.<br>밟아 죽였다. 실은 안 끊었다. 넷째는 끝까지 몰랐다.`,
      ng:`튕겼는데 그것이 다리를 실에 감고 버틴다.<br><br>튕긴 반동으로 이쪽 쪽으로 날아왔다. 손목에 붙었다. 문다. 끊었다. 끊는 순간 넷째 쪽에서 비명이 났다. 실이 알려 주던 게 끊긴 것이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-8 } },
    { l:'② 손목에서 실을 풀어 바위에 옮겨 맨다.', k:'fix', dc:13,
      ok:`손목에서 실을 풀어 바위에 맸다. 끝을 바꿨다.<br><br>그것이 바위에 닿는다. 더듬는다. 손목이 없다. 한참 바위를 돌다 내려간다.<br>바위에 묶인 실은 넷째 소식을 더는 안 알려 준다. 대신 이쪽 손목이 남았다.`,
      ng:`푸는 사이 그것이 손가락까지 왔다. 손가락 사이를 지나 소매로 들어간다.<br><br>털어 냈다. 소매 안이 따끔따끔하다. 한 군데가 붓기 시작했다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-10, mind:-6 } }
  ] },

{ at:'C', t:'찢긴 옆구리 — 숨을 나눈다',
  x:`팀원이 크게 찢겼다. 옆구리다. 피가 멎지 않는다.<br><br>
    치유할 사람은 다른 팀원을 보는 중이다. 기다려야 한다. 기다리는 동안 숨이 얕아진다.<br>
    결속술사는 실로 기운을 넘긴다. 온기를 넘겨 본 적은 있다. 이번엔 온기로 모자란다.<br><br>
    숨을 넘겨야 한다.`,
  o:[
    { l:'① 두 손목을 짧게 이어 숨 박자를 묶는다.', k:'bond', dc:15, cost:{ mana:20 },
      ok:`두 손목을 실로 이었다. 짧게. 이쪽 숨을 크게 쉬었다. 실을 타고 박자가 건너간다.<br><br>들이쉴 때 같이 들이쉬고 내쉴 때 같이 내쉰다. 얕던 숨이 이쪽 숨에 맞춰 깊어진다.<br>치유할 사람이 왔을 때 둘은 같은 박자로 숨 쉬고 있었다. 이쪽 숨은 반쯤 짧아져 있었다.<br><br>실로 나누는 게 기운만이 아니었다. 박자도 묶인다. 묶인 박자는 약한 쪽이 강한 쪽을 따라온다. 그 반대가 아니라서 다행이었다.`,
      ng:`박자를 묶었는데 저쪽 박자가 이쪽을 끌어간다.<br><br>숨이 같이 얕아진다. 눈앞이 하얘졌다. 실을 끊었다. 둘 다 바닥에서 헐떡였다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-12, mind:-10 }, wake:1 },
    { l:'② 실을 세게 둘러 상처를 묶는다.', k:'heal', dc:14,
      ok:`실을 옆구리에 둘렀다. 마력 없이 그냥 실로. 세게.<br><br>피가 실에서 멈춘다. 실은 안 보이니 피가 허공에서 멎은 것 같다. 팀원이 그걸 보고 웃었다. 웃을 힘이 남았다.`,
      ng:`감는데 실이 미끄럽다. 피에 젖었다. 마력 실은 젖으면 풀린다.<br><br>세 번 감았다 세 번 풀렸다. 손이 피투성이가 됐다.`,
      win:{ exp:16, dream:2, hp:5 }, lose:{ mind:-8, spirit:-6 } }
  ] },

{ at:'C', t:'쉬는 자리 — 겁으로 묶은 매듭',
  x:`다른 팀이 쉬고 있다. 다친 둘을 자기들 허리에 묶었다. 끌고 다닌 것이다.<br><br>
    매듭이 이상하다. 묶은 사람이 풀 수 없게 묶었다. 풀면 다친 사람을 두고 갈 것 같아서.<br>
    그 팀 반장 허리가 쓸려서 피가 배었다. 그래도 매듭을 안 푼다.<br><br>
    매듭을 보면 묶은 마음이 보인다. 이건 겁으로 묶었다. 겁은 질기다. 오래는 못 간다.`,
  o:[
    { l:'① 겁 매듭을 풀고 다시 맨다.', k:'bond', dc:14,
      ok:`반장 앞에 앉았다. 매듭을 풀겠다고 했다. 대신 더 질긴 걸로 매 주겠다고.<br><br>반장이 한참 본다. 고개를 끄덕인다. 풀었다. 다친 둘을 들것에 눕히고 실로 들것과 넷을 이었다. 허리 대신 손목에. 당기면 다 같이 알게.<br>반장 허리가 처음으로 쉬었다.<br><br>사람을 사람에게 묶지 않고 짐에, 짐을 여럿에 묶었다. 매듭이 하는 일을 바꾸니 묶인 쪽이 가벼워졌다. 손이 새 매듭을 하나 기억했다.`,
      ng:`풀겠다는 말에 반장이 칼을 뽑았다.<br><br>매듭에 손대는 사람은 다친 사람을 떼어 가려는 사람이다. 그쪽은 그렇게 믿었다. 손등을 베였다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-12, spirit:-6 }, wake:1 },
    { l:'② 마력 실로 다친 둘의 무게를 열 손목에 나눠 단다.', k:'steady', dc:14, cost:{ mana:15 },
      ok:`다친 둘 허리에 실을 걸어 두 팀 열 손목에 나눠 이었다. 무게가 열에게 고르게 간다.<br><br>그 팀 반장이 이상한 얼굴을 한다. 갑자기 가벼워졌다고.<br>다음 계단까지 같이 갔다. 마력이 실을 타고 계속 빠졌다.`,
      ng:`나누는 데 마력이 모자랐다. 무게가 이쪽 손목 하나로 몰린다.<br><br>손목이 꺾였다. 실을 놓았다. 다친 사람이 바닥에 떨어졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, mind:-6 } },
    { l:'③ 남의 매듭은 남의 일이라며 지나간다.', k:'hide', dc:13,
      ok:`지나갔다.<br><br>계단 앞에서 그 팀이 따라붙었다. 허리에 묶인 채로. 느렸다. 놈이 그 느린 쪽을 먼저 봤다. 이쪽은 그 덕에 빨리 내려갔다.<br>계단을 내려가는 동안 손목 실이 이유 없이 무거웠다.`,
      ng:`지나가는데 반장이 이쪽 소매를 잡는다. 묶을 줄 아는 사람이라는 걸 알아봤다.<br><br>뿌리쳤다. 뿌리친 손이 오래 무거웠다.`,
      win:{ exp:12, dream:1 }, lose:{ spirit:-10, mind:-6 } }
  ] },

{ at:'C', t:'쉬는 자리 — 자는 동안의 매듭',
  x:`쉬는 자리. 다섯이 잔다. 결속술사도 자야 한다.<br><br>
    자면 실이 풀린다. 마력은 깨어 있는 동안만 실을 붙든다.<br>
    놈들은 자는 사람을 안다. 실 풀린 사람도 안다.<br><br>
    매듭만으로 묶으면 마력 없이도 남는다. 그런 매듭은 배운 적이 없다.`,
  o:[
    { l:'① 매듭 하나마다 숨을 한 번씩 넣어 묶는다.', k:'bond', dc:15,
      ok:`마력을 넣지 않았다. 매듭을 지을 때마다 숨을 길게 한 번 쉬었다. 매듭에 박자를 넣었다.<br><br>자는 동안 꿈에서 실이 당겨졌다. 눈을 떴다. 막내 쪽이다. 놈 하나가 막내 발치를 핥고 있었다.<br>다 깨웠다. 쫓았다.<br><br>실은 이쪽이 자는 동안에도 일했다. 마력이 아니라 매듭이 기억했다. 매듭이 기억을 품을 수 있다는 걸 알았다. 손가락이 그 매듭을 몇 번이고 다시 지었다.`,
      ng:`숨을 넣었는데 매듭이 숨을 안 품는다.<br><br>자고 일어나니 실이 다 풀려 있다. 막내 발목에 잇자국이 있다. 막내는 몰랐다고 한다. 자면서 물렸다고.`,
      win:{ exp:22, dream:3, spirit:5 }, lose:{ hp:-10, spirit:-8 }, wake:1 },
    { l:'② 자지 않고 실을 쥐고 밤을 샌다.', k:'steady', dc:14,
      ok:`안 잤다. 다섯 가닥을 손에 감고 앉아 있었다.<br><br>밤새 실이 세 번 떨었다. 세 번 다 일어나 불을 들었다. 세 번 다 무언가 물러갔다.<br>아침에 다섯이 다 멀쩡했다. 이쪽 눈만 빨갰다.`,
      ng:`새벽에 졸았다. 실이 손에서 풀렸다.<br><br>눈을 뜨니 실 한 가닥이 바닥에 떨어져 씹혀 있다. 그 끝의 팀원은 무사했다. 운이었다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-12, spirit:-4 } }
  ] },

{ at:'C', t:'굴 앞 — 남이 묶어 둔 놈',
  x:`굴 앞에 놈 하나가 묶여 있다. 마력 실이다. 매듭이 셋.<br><br>
    누가 사냥하다 묶어 두고 갔다. 돌아오지 않았다. 실이 흐려졌다. 마지막 매듭도 반쯤 풀렸다.<br>
    놈은 묶인 채 살이 빠졌다. 그래도 이빨은 그대로다. 이쪽을 본다.<br><br>
    매듭이 다 풀리면 놈이 나온다. 굶은 놈이다.`,
  o:[
    { l:'① 남은 매듭 위에 이쪽 실을 덧감는다.', k:'bond', dc:14,
      ok:`남은 매듭에 이쪽 실을 덧감았다. 남이 지은 매듭 위에 이쪽 것을.<br><br>놈이 다시 꼼짝 못 한다. 팀원들이 창을 댔다.<br>남이 묶은 걸 이쪽이 끝냈다. 매듭 셋을 지은 사람은 돌아오지 않았지만 그 사람 사냥은 끝났다.`,
      ng:`덧감는데 남의 매듭이 이쪽 실을 밀어낸다.<br><br>지은 사람만 받는 매듭이었다. 반쯤 풀린 매듭이 마저 풀렸다. 놈이 나왔다. 굶은 놈은 빨랐다.`,
      win:{ exp:18, dream:2, item:'짐승 고기' }, lose:{ hp:-16, mind:-6 } },
    { l:'② 매듭을 읽어 묶은 사람의 행방을 찾는다.', k:'gaze', dc:14,
      ok:`매듭 셋을 짚었다. 서두른 매듭이다. 마지막 것만 공을 들였다. 다 묶고 나서 쉬었다는 뜻이다.<br><br>굴 옆을 보니 그 사람이 쉰 자리가 있다. 배낭이 남았다. 사람은 굴 반대쪽으로 끌려간 자국을 남겼다. 묶인 놈 말고 한 마리가 더 있었다.<br>배낭 안에 말린 고기가 있었다.`,
      ng:`매듭을 짚는 사이 놈이 실을 씹었다.<br><br>마지막 매듭이 풀렸다. 놈이 덮쳤다. 실을 쥔 이쪽 손부터.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C1', t:'도마 — 다시 붙는 살',
  x:`도마 위 고깃덩이가 반으로 갈라져 있다. 갈라진 사이가 실 같은 것으로 이어졌다.<br><br>
    힘줄이다. 가늘게 뻗어 반대쪽을 붙든다. 당긴다. 조금씩 붙는다.<br>
    결속술사는 그걸 본다. 손목에서 실을 꼴 때와 똑같은 모양이다. 꼬는 방향까지.<br><br>
    이 도축장 고기는 다 이렇게 다시 붙는다. 푸는 법을 알면 자라는 것들을 멈출 수 있다.`,
  o:[
    { l:'① 힘줄 꼼을 거꾸로 비틀어 푼다.', k:'bond', dc:15,
      ok:`힘줄 끝을 손끝으로 짚었다. 꼰 방향 반대로 비틀었다. 실을 풀 때처럼.<br><br>힘줄이 스르르 풀린다. 두 덩이가 떨어진다. 다시 붙지 않는다. 그냥 고기가 됐다.<br>팀원들이 그 고기를 챙겼다. 이제 안 자란다.<br><br>마력으로 꼰 게 아니어도 꼰 것은 꼰 것이다. 살이 묶이는 법도 실이 묶이는 법과 같았다. 손끝이 처음 보는 매듭을 읽었다.`,
      ng:`비틀었는데 반대가 아니었다. 이쪽 방향으로 꼬는 것이었다.<br><br>힘줄이 더 빨리 붙는다. 붙으면서 이쪽 손가락을 사이에 끼우고 붙었다. 칼로 갈라 손을 뺐다.`,
      win:{ exp:24, dream:3, item:'짐승 고기' }, lose:{ hp:-14, mind:-6 }, wake:1 },
    { l:'② 등잔불에 힘줄을 그슬린다.', k:'break', dc:14,
      ok:`등잔불에 힘줄을 댔다. 오그라든다. 탄 냄새가 난다.<br><br>두 덩이가 떨어진 채 남았다. 그을린 쪽은 안 붙는다.<br>도축장 전체가 그 냄새에 고개를 든 것 같았다.`,
      ng:`불이 닿자 고기가 움찔하며 등잔을 쳤다.<br><br>기름이 이쪽 소매에 튀었다. 불이 붙었다. 껐다. 팔뚝이 쓰라리다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-14, spirit:-4 } }
  ] },

{ at:'C1', t:'갈고리 줄 — 낚인 팀원',
  x:`갈고리 하나가 레일에서 내려와 팀원 어깨끈을 걸었다.<br><br>
    들려 올라간다. 레일이 돈다. 팀원이 고깃덩이들 사이로 실려 간다. 저 끝에서 칼 소리가 난다.<br>
    팀원 손목에 실이 있다. 이쪽 손목에 이어진.<br><br>
    실을 기둥에 감으면 갈고리가 못 끌고 간다. 대신 실이 팀원과 레일 사이에서 버텨야 한다.`,
  o:[
    { l:'① 마력을 부어 실을 기둥에 감는다.', k:'bond', dc:15, cost:{ mana:20 },
      doom:{ title:'갈고리 줄', what:'갈고리 줄에 실려 끌려갑니다', dc:15, sec:60,
        text:`기둥에 실을 감았다. 마력을 부었다. 팀원이 공중에서 멈춘다.<br><br>레일은 멈추지 않는다. 갈고리가 버틴다. 실이 버틴다. 그 사이에서 팀원 어깨가 비명을 지른다.<br>실이 기둥에서 미끄러진다. 기둥이 아니라 이쪽 손목에 감겨 있다. 언제 바뀌었는지 모른다.<br><br>이쪽도 들린다. 다음 갈고리가 내려온다.`,
        dieText:`레일은 멈추지 않았다.<br><br>줄 끝에서 고깃덩이 둘이 내려졌다. 썰렸다. 바닥에 던져졌다.<br>던진 자리에서 둘이 다시 자란다. 실 한 가닥으로 이어진 채.` },
      ok:`실을 기둥에 세 번 감았다. 마력을 부었다. 팀원이 공중에서 멈춘다.<br><br>레일이 덜컥거린다. 갈고리가 버티다 어깨끈이 끊어졌다. 팀원이 떨어졌다. 받았다.<br>빈 갈고리가 지나간다. 줄 끝의 칼 소리가 한 번 멈췄다. 하나 모자란다는 걸 안 것이다.<br><br>다음 갈고리부터는 다들 어깨끈을 풀고 걸었다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 뛰어올라 어깨끈을 자른다.', k:'evade', dc:15,
      ok:`고깃덩이를 밟고 뛰어올랐다. 칼로 어깨끈을 그었다.<br><br>팀원이 떨어진다. 이쪽도 떨어진다. 둘이 바닥 고기 더미에 박혔다. 미지근했다.<br>기어 나왔다. 더미가 둘이 빠져나간 자리를 메우며 조금 부풀었다.`,
      ng:`밟은 고깃덩이가 미끄러졌다. 칼이 끈을 놓쳤다.<br><br>팀원은 세 갈고리 더 실려 갔다. 셋이 뛰어가 겨우 내렸다. 줄 끝 바로 앞이었다. 이쪽은 떨어지며 발목을 접질렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-8 } }
  ] },

{ at:'C1', t:'라인 끝 — 칼 든 팔과 레일',
  x:`줄 끝의 그것이 칼을 든다. 앞치마가 젖었다. 쉬지 않는다.<br><br>
    칼 든 팔과 레일 사이가 가깝다. 팔이 올라갈 때마다 레일에 거의 닿는다.<br>
    가까운 두 개를 보면 묶고 싶어진다. 결속술사의 버릇이다.<br><br>
    팔을 레일에 묶으면 레일이 팔을 끌고 간다.`,
  o:[
    { l:'① 마력 실로 칼 든 팔목을 빈 갈고리에 묶는다.', k:'bond', dc:15, cost:{ mana:22 },
      ok:`실을 던져 팔목에 감았다. 반대쪽을 지나가던 빈 갈고리에 걸었다. 조였다.<br><br>레일이 돈다. 갈고리가 팔을 끌고 간다. 그것이 칼을 놓지 않은 채 레일을 따라 끌려간다. 레일은 길다.<br>그것이 한 바퀴 돌아오기 전에 줄 아래를 다 지났다.<br><br>멀리서 칼 소리가 났다. 끌려가면서도 일은 했다.`,
      ng:`실을 던졌는데 팔이 내려오며 실을 썰었다.<br><br>그것이 끊어진 실을 본다. 실을 따라 이쪽을 본다. 앞치마 주머니에서 갈고리 하나를 꺼내 던졌다. 허벅지에 걸렸다. 빼는 동안 팀원들이 막아 줬다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-18, mind:-6 } },
    { l:'② 다섯을 짧게 이어 한 덩이처럼 지나간다.', k:'fix', dc:14,
      ok:`다섯을 짧게 이었다. 붙어서 걸으면 한 덩이처럼 보인다. 그것은 덩이를 센다.<br><br>그것이 손가락을 하나 꺾는다. 하나. 덩이 하나를 지나보낸 것이다. 고기인 줄 안다.<br>다섯이 한 덩이로 줄 끝을 지났다. 다섯 다 숨을 참았다.`,
      ng:`붙어서 걷다 하나가 발을 밟았다. 덩이가 둘로 갈라졌다.<br><br>그것이 손가락을 꺾다 멈춘다. 둘. 하나가 더 많다. 칼이 남는 하나 쪽으로 왔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } },
    { l:'③ 고깃덩이를 발치로 던져 일을 하나 늘려 준다.', k:'luck', dc:14,
      ok:`바닥 고깃덩이를 그것 발치로 던졌다. 그것이 줍는다. 갈고리에 건다. 일이 늘었다.<br><br>일 하나 느는 동안 다섯이 지나갔다. 그것은 끝까지 돌아보지 않았다. 일이 늘면 고개를 못 든다.`,
      ng:`던진 고기가 바닥에서 자라 이쪽으로 기어 온다. 미끼가 되기 싫은 고기다.<br><br>팀원 발목에 달라붙었다. 떼어 내는 소리에 그것이 고개를 들었다.`,
      win:{ exp:14, dream:1 }, lose:{ hp:-10, mind:-6 } }
  ] },

{ at:'C2', t:'천장의 실 — 같은 꼼',
  x:`공방 천장에서 실이 수백 가닥 내려온다. 끝마다 인형이 매달렸다.<br><br>
    실을 보면 꼰 손이 보인다. 이건 마력으로 꼰 실이다. 이쪽 것과 같은 꼼이다. 더 가늘고 더 오래됐다.<br>
    위층의 누군가도 실을 꼰다. 이쪽보다 훨씬 오래.<br><br>
    실 하나가 내려와 이쪽 손목 실에 감긴다. 인사하듯.`,
  o:[
    { l:'① 감긴 실을 따라 위층의 손을 읽는다.', k:'gaze', dc:15,
      ok:`감긴 실에 손가락을 얹었다. 실을 타고 위가 느껴진다. 손가락 열. 아니, 스물. 실마다 하나씩.<br><br>위에 있는 것은 손가락 하나로 실 하나를 쥔다. 실이 수백이면 손가락도 수백이다.<br>감긴 실을 살살 풀어 돌려보냈다. 위에서 한참 반응이 없다. 그리고 진열장 쪽 실들이 일제히 이쪽을 비켜 갔다.<br><br>같은 일을 하는 것끼리는 알아본다. 위의 것이 이쪽을 알아봤다. 이쪽도 남의 실을 쥔 손까지 거슬러 읽는 법을 얻었다.`,
      ng:`손가락을 얹는 순간 실이 손가락을 감는다. 하나씩.<br><br>위에서 이쪽 손가락을 센다. 다섯. 쓸 만하다고. 칼로 실을 끊었다. 손가락마다 하얀 줄이 남았다.`,
      win:{ exp:22, dream:3, mind:6 }, lose:{ spirit:-12, mind:-6 }, wake:1 },
    { l:'② 감긴 실을 바로 끊는다.', k:'break', dc:14,
      ok:`끊었다. 망설이지 않았다.<br><br>끊긴 실이 위로 빨려 올라간다. 인사를 받지 않은 쪽을 위에서 기억할 것이다.<br>그래도 손목은 이쪽 것으로 남았다.`,
      ng:`끊었는데 끊긴 끝이 이쪽 실을 물고 올라간다.<br><br>이쪽 실이 위층으로 딸려 간다. 팀원 다섯 손목이 같이 당겨졌다. 실을 다 끊고 새로 꼬았다. 머리가 텅 비었다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-10, spirit:-8 } }
  ] },

{ at:'C2', t:'달려드는 인형 — 정수리의 실',
  x:`인형 하나가 팀원에게 달려든다. 사기 턱이 열린다. 사람 이가 줄지어 있다.<br><br>
    인형 정수리에 실이 붙어 있다. 위로 이어진다. 위에서 당기면 뛰고 놓으면 선다.<br>
    결속술사는 실 다루는 사람이다. 남의 실이라고 못 다룰 것은 없다.<br><br>
    실 중간을 쥐면 위에서 당기는 힘이 이쪽 손에 걸린다.`,
  o:[
    { l:'① 마력을 흘려 실 중간을 쥐고 이쪽으로 당긴다.', k:'bond', dc:15, cost:{ mana:18 },
      ok:`실 중간을 쥐었다. 마력을 흘렸다. 위에서 오는 박자를 이쪽 박자로 덮었다.<br><br>인형이 공중에서 멈춘다. 이쪽이 당기니 이쪽으로 온다. 돌려서 진열장에 처박았다. 사기가 깨졌다.<br>위층에서 실을 당기는 힘이 한참 이쪽 손을 당겼다. 놓지 않았다. 위에서 먼저 놓았다.`,
      ng:`쥐었는데 위의 힘이 세다. 이쪽 손이 인형처럼 들린다.<br><br>팔이 머리 위로 끌려 올라간다. 팀원이 허리를 안고 버텼다. 실을 놓았다. 어깨가 빠질 뻔했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-14, mind:-8 } },
    { l:'② 인형 턱에 실을 감아 다물게 묶는다.', k:'fix', dc:14,
      ok:`인형 턱 밑으로 실을 돌려 정수리에 감았다. 위아래로.<br><br>턱이 닫힌 채 안 열린다. 인형이 팀원 팔에 머리를 들이받는다. 멍만 들었다.<br>묶인 입으로 인형이 한참 웅웅거렸다. 위층에 무언가 이르는 소리 같았다.`,
      ng:`감는 사이 턱이 열렸다. 이쪽 손가락이 이 사이에 있었다.<br><br>사람 이는 사람 손가락을 잘 문다. 빼는 데 둘이 붙었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C2', t:'쏟아지는 태엽 인형',
  x:`진열장 문이 일제히 열렸다. 작은 인형들이 바닥으로 쏟아진다. 무릎 높이. 수십.<br><br>
    달릴 때마다 이가 딱딱 부딪친다. 다 이쪽 발목 높이다.<br>
    이것들은 정수리에 실이 없다. 등에 태엽 열쇠가 꽂혀 돈다.<br><br>
    실 없이 움직이는 것은 결속술사가 제일 다루기 어렵다.`,
  o:[
    { l:'① 다섯 발목을 실로 이어 낮은 원을 친다.', k:'bond', dc:14,
      ok:`다섯이 둥글게 섰다. 발목과 발목을 실로 이었다. 정강이 높이로.<br><br>인형들이 달려와 실에 걸린다. 넘어진다. 사기가 깨진다. 뒤에 오던 것이 앞의 것에 걸려 또 넘어진다.<br>원 바깥에 깨진 것들이 쌓였다. 원 안의 다섯은 발목 하나 안 물렸다.`,
      ng:`원을 치는데 한 사람이 발을 뺐다. 원이 터졌다.<br><br>그 틈으로 수십이 들어왔다. 실이 다리 사이에서 엉켜 다들 제대로 못 뛰었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } },
    { l:'② 태엽 열쇠마다 실을 걸어 한꺼번에 붙든다.', k:'fix', dc:15,
      ok:`실을 그물처럼 던졌다. 돌아가는 열쇠마다 걸렸다.<br><br>열쇠가 실을 감는다. 감을수록 실이 조인다. 조이면 열쇠가 못 돈다. 못 돌면 선다.<br>수십이 한꺼번에 멈췄다. 이를 벌린 채로. 하나씩 깨며 지나갔다.`,
      ng:`열쇠가 실을 감는데 멈추지 않는다. 실을 감아 당긴다.<br><br>실 끝의 이쪽 손이 인형들 쪽으로 끌려간다. 실을 놓았다. 놓는 순간 손바닥 살이 쓸렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-12, spirit:-8 } },
    { l:'③ 작업대 위로 올라간다.', k:'evade', dc:14,
      ok:`작업대 위로 뛰어올랐다. 다섯이 다.<br><br>인형들이 작업대 다리를 둘러싼다. 못 올라온다. 태엽이 다 풀릴 때까지 기다렸다. 하나씩 멈췄다.<br>작업대 위에 공구와 사람 이가 든 통이 있었다. 아무도 통은 안 만졌다.`,
      ng:`올라가다 작업대가 기울었다.<br><br>공구가 쏟아졌다. 끌이 종아리를 그었다. 인형들이 그 피 냄새로 몰려왔다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-14, mind:-4 } }
  ] },

{ at:'C3', t:'골 바닥 — 종 안의 혀',
  x:`뒤집힌 성당 골마다 종 같은 것이 놓였다. 아가리를 위로.<br><br>
    종 안에 혀가 있다. 쇠가 아니다. 살이다. 길고 축축하다. 사람이 지나가면 혀가 종벽을 친다. 운다.<br>
    울리면 둥근 천장 전체가 같이 운다. 그리고 무언가 온다.<br><br>
    혀를 묶으면 안 운다. 혀는 종 안에 있다.`,
  o:[
    { l:'① 실을 늘어뜨려 혀를 종벽에 묶는다.', k:'bond', dc:15, cost:{ mana:18 },
      ok:`실을 종 아가리로 천천히 늘어뜨렸다. 마력을 실 끝에 모아 혀에 감았다.<br><br>혀가 실을 핥는다. 맛을 본다. 마력 맛. 핥는 사이 혀 밑동을 종벽 고리에 묶었다.<br>종이 흔들린다. 혀가 못 친다. 안 운다.<br><br>다섯이 지나갔다. 종 안에서 혀가 실을 계속 핥는 소리가 났다. 맛있었던 모양이다.`,
      ng:`늘어뜨린 실을 혀가 먼저 감았다. 끌어당긴다.<br><br>이쪽 팔이 아가리 안으로 끌려 들어간다. 팀원이 어깨를 잡아 뺐다. 혀가 종벽을 쳤다. 성당 전체가 울었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-14, spirit:-10 } },
    { l:'② 숨을 죽이고 한 사람씩 지나간다.', k:'hide', dc:14,
      ok:`발끝으로 걸었다. 숨을 아꼈다. 한 사람씩.<br><br>종 안의 혀가 꿈틀거린다. 기척은 느끼는데 어디인지 모른다. 혀가 허공을 핥다 멈췄다.<br>다섯째가 지날 때 종이 아주 작게 한 번 울었다. 아무것도 오지 않았다. 다행이었다.`,
      ng:`넷째가 숨을 내쉬었다. 크게.<br><br>혀가 종벽을 쳤다. 둥근 천장이 울었다. 머리 위 의자들 사이에서 무언가 거꾸로 기어 내려왔다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-12, mind:-8 } }
  ] },

{ at:'C3', t:'둥근 천장 — 위로 떨어지는 팀원',
  x:`팀원 하나가 휘청한다. 발이 둥근 천장에서 뜬다.<br><br>
    이 성당의 것은 위로 떨어진다. 바깥에서 온 것만 아래로 떨어진다. 그런데 오래 머물면 바깥 것도 여기 것이 되어 간다.<br>
    팀원이 천천히 떠오른다. 머리 위 거꾸로 박힌 의자들 쪽으로. 의자 사이에 무언가 매달려 있다. 먼저 위로 떨어진 것들이다.<br><br>
    팀원 손목에 실이 있다.`,
  o:[
    { l:'① 실을 감아 끌어내리고 둘의 발목을 바닥에 묶는다.', k:'bond', dc:15,
      doom:{ title:'위로 떨어짐', what:'거꾸로 박힌 의자들 쪽으로 떨어져 올라갑니다', dc:15, sec:55,
        text:`실을 감았다. 끌어내렸다. 팀원 발이 둥근 천장에 닿는다.<br><br>그 순간 이쪽 발이 뜬다. 실은 양쪽을 다 묶는다. 무게도 나눈다. 위로 떨어지는 무게까지.<br>둘이 같이 떠오른다. 천천히. 의자들 사이로.<br><br>나머지 팀원들이 실을 붙잡으려 한다. 실은 이쪽 눈에만 보인다. 팀원들은 허공을 붙잡는다.`,
        dieText:`거꾸로 박힌 의자들 사이에 둘이 매달렸다.<br><br>실 한 가닥으로 이어진 채.<br>아래에서 올려다보면 둘은 의자에 앉아 있다. 예배를 기다리는 사람들처럼.` },
      ok:`실을 감아 끌어내렸다. 팀원 발이 닿자마자 발목을 골 바닥 갈빗대에 묶었다. 이쪽 발목도. 둘 다 아래에 묶었다.<br><br>팀원이 다시 뜨려 한다. 발목 실이 붙든다. 몸이 위를 보고 기울다 돌아온다.<br>한참 뒤에 무게가 제 방향으로 돌아왔다. 팀원이 주저앉았다.<br><br>위로 떨어지는 사람은 아래에 묶으면 된다. 말은 쉽다. 손목이 아직 떤다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 넷이 달려들어 다리를 안는다.', k:'steady', dc:15,
      ok:`넷이 달려들어 다리를 안았다. 넷의 무게가 하나의 위를 이긴다.<br><br>천천히 내려왔다. 다 같이 엎드려 숨을 골랐다. 아무도 일어서지 않았다. 기어서 다음 골까지 갔다.`,
      ng:`안았는데 안은 사람 발도 뜬다.<br><br>둘이 떴다. 남은 셋이 둘을 끌어내렸다. 내려오다 의자 다리에 머리를 부딪쳤다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-8 } }
  ] },

{ at:'C3', t:'성가대 — 엇갈리는 숨',
  x:`성가대가 노래한다. 한 몸에 입이 여럿. 입마다 다른 높이.<br><br>
    입이 많으면 숨도 많다. 숨이 엇갈린다. 결속술사는 엇갈린 것을 보면 이을 자리를 본다.<br>
    입과 입 사이에 실을 걸면 숨이 묶인다. 묶인 숨은 같이 쉰다. 같이 쉬면 화음이 깨진다.<br><br>
    화음이 깨지면 노래가 멈출 것이다. 아니면 더 커질 것이다.`,
  o:[
    { l:'① 한 몸의 두 입을 실로 이어 숨을 하나로 묶는다.', k:'bond', dc:15,
      ok:`가는 실을 던졌다. 앞줄 것의 목 입과 손바닥 입을 이었다. 같이 쉬도록.<br><br>두 입이 같은 높이를 낸다. 화음 하나가 비었다. 옆의 것이 빈 데를 채우려다 박자를 놓친다. 노래가 엉킨다. 엉킨 노래가 멈췄다.<br>성가대가 서로를 본다. 처음으로 입을 다 다물었다.<br><br>손목 말고 숨을 묶었다. 묶음은 둘을 하나로 만들기도 하고, 하나로 돌던 것을 깨뜨리기도 한다. 실의 양쪽 끝을 한꺼번에 보는 눈이 생겼다.`,
      ng:`실을 걸었는데 두 입이 실을 같이 문다.<br><br>실을 타고 노래가 이쪽으로 온다. 손목에서 목소리가 났다. 이쪽 것이 아니다. 실을 끊었다. 손목이 한참 웅웅거렸다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-12, spirit:-8 }, wake:1 },
    { l:'② 다섯 손목을 이어 노래를 나눠 견딘다.', k:'steady', dc:14, cost:{ mana:15 },
      ok:`다섯 손목을 원으로 이었다. 마력을 돌렸다.<br><br>노래가 한 사람에게 쏠리면 실이 그 무게를 넷에게 나눈다. 다섯이 다 조금씩 어지럽다. 아무도 따라 부르지 않았다.<br>성가대 앞을 다 지났다. 다들 귀에서 피가 조금씩 났다. 조금씩만.`,
      ng:`잇는 데 마력이 모자랐다. 원이 반쯤 끊겼다.<br><br>끊긴 쪽 둘이 노래를 따라 입을 벌렸다. 끌고 나오는 동안 이쪽 귀도 먹먹해졌다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-10, spirit:-8 } }
  ] },

{ at:'C4', t:'하얀 바닥 — 스스로 꼬이는 실',
  x:`온실 바닥이 하얗다. 실 같은 것이 깔렸다. 균사다.<br><br>
    실을 보면 묶은 방향이 보인다. 이건 사방으로 묶었다. 화분과 화분을. 기둥과 기둥을. 쓰러진 작업복과 바닥을.<br>
    꼬는 손은 없다. 실이 스스로 꼬인다.<br><br>
    모든 실이 한쪽으로 기울었다. 온실 한가운데로.`,
  o:[
    { l:'① 균사 매듭을 짚어 무엇을 나르는지 읽는다.', k:'gaze', dc:15,
      ok:`쪼그려 앉아 균사를 손끝으로 짚었다. 장갑 위로.<br><br>매듭이 있다. 실이 실을 붙든 자리. 화분과 화분을 묶은 게 아니었다. 화분에서 화분으로 무언가를 나르고 있었다. 물을. 작업복 입은 것들이 준 물을. 한가운데로.<br>한가운데로 가는 실이 제일 굵다. 거기서 받아먹는 것이 있다.<br><br>손으로 꼬지 않은 실도 묶는다. 묶은 것은 나른다. 무엇을 나르는지 읽으면 그 끝에 무엇이 있는지 안다. 손끝이 실 너머를 읽기 시작했다.`,
      ng:`짚는데 균사가 장갑 위로 기어오른다. 손목 실을 찾는다. 같은 실인 줄 안다.<br><br>손목 실에 감겼다. 마력을 빨아 간다. 장갑을 벗어 던졌다. 장갑이 하얗게 덮였다. 수칙대로 버렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-10, spirit:-8 }, wake:1 },
    { l:'② 균사를 안 밟고 화분 테두리로 건너간다.', k:'evade', dc:14,
      ok:`화분 테두리를 밟고 건넜다. 하나에서 하나로.<br><br>균사가 안 닿는 데만 디뎠다. 한 번 기우뚱했다. 팀원이 손을 잡아 줬다.<br>건너편에서 돌아보니 바닥 균사가 이쪽 발자국 자리로 몰려 있다. 밟지 않았는데도.`,
      ng:`테두리가 깨졌다. 발이 균사 위에 떨어졌다.<br><br>신발 바닥에 하얀 것이 붙었다. 떼어 냈는데 한 올이 남았다. 걸을 때마다 조금씩 길어진다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-10, spirit:-8 } }
  ] },

{ at:'C4', t:'쉬는 자리 — 바닥에 붙은 발',
  x:`팀원이 쉬다 일어나지 못한다. 발바닥이 바닥에 붙었다.<br><br>
    신발을 뚫고 균사가 올라왔다. 발목까지 하얗다. 바닥과 묶였다.<br>
    칼로 자르면 신발 바닥과 발바닥이 같이 간다. 균사는 깊다.<br><br>
    결속술사는 묶는 사람이다. 묶은 것을 푸는 사람이기도 하다.`,
  o:[
    { l:'① 마력 실을 균사에 엮어 매듭째 끌어낸다.', k:'bond', dc:15, cost:{ mana:20 },
      ok:`실을 균사에 엮었다. 균사가 이쪽 실을 제 실로 안다. 감겨 온다. 그걸 그대로 당겼다.<br><br>균사가 이쪽 실을 따라 발바닥에서 빠져나온다. 하얀 뿌리가 한 묶음. 빠져나오며 팀원이 비명을 질렀다.<br>뿌리째 실에 감긴 채 이쪽으로 왔다. 마력을 끊었다. 실과 균사가 같이 바닥에 떨어져 시들었다.`,
      ng:`엮었는데 균사가 이쪽 실을 타고 손목까지 왔다.<br><br>팀원 발과 이쪽 손목이 한 실에 묶였다. 둘 다 바닥에 붙을 판이다. 칼로 이쪽 실을 끊었다. 마력이 다 쏟아졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-12, mind:-10 } },
    { l:'② 신발 바닥째 잘라 낸다.', k:'break', dc:14,
      ok:`신발 바닥을 칼로 갈랐다. 균사가 신발 안에 남았다. 발바닥은 하얗게 얼룩졌지만 붙어 있지는 않다.<br><br>맨발로 걸어야 한다. 균사 깔린 바닥을. 이쪽 신발을 줬다. 이쪽은 천을 감았다.`,
      ng:`갈랐는데 발바닥까지 깊다. 피가 나자 균사가 더 빨리 핀다.<br><br>겨우 떼어 냈다. 팀원은 그 뒤로 절룩였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C4', t:'중앙 돔 앞 — 실이 모이는 매듭',
  x:`모든 균사가 한쪽으로 모인다. 온실 한가운데 유리 돔.<br><br>
    돔 안에 큰 갓이 있다. 부풀었다 꺼진다. 숨 쉰다. 균사가 다 그것에 묶였다.<br>
    작업복 입은 것들도, 포자 짐승도, 화분도. 다 그것에서 나온 실 끝에 있다.<br><br>
    실을 다 끊을 수는 없다. 수천이다. 실이 모이는 매듭은 하나다.`,
  o:[
    { l:'① 굵은 실을 거슬러 매듭 자리를 찾는다.', k:'sense', dc:15,
      ok:`제일 굵은 균사를 따라갔다. 돔 유리 아래 틈으로 들어간다.<br><br>틈 안쪽에 매듭이 있다. 주먹만 하다. 실 수천이 거기서 꼬였다 갈라진다.<br>칼을 넣었다. 매듭이 갈라지자 온실 전체가 움찔한다. 작업복 입은 것들이 한꺼번에 무릎을 꺾었다.<br><br>돔 안의 갓은 그래도 숨을 쉰다. 다만 이제 혼자 쉰다.`,
      ng:`따라가는데 굵은 실이 셋으로 갈라진다. 둘은 가짜다.<br><br>가짜 쪽에서 포자 짐승이 일어났다. 실은 짐승 등으로 이어져 있었다. 이쪽이 그 등을 짚고 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-6 } },
    { l:'② 다섯 손목을 한 매듭에 모아 같이 친다.', k:'bond', dc:15,
      ok:`다섯 손목 실을 짧게 걷어 한 매듭에 모았다. 이쪽 손목에.<br><br>당기면 다섯이 같이 안다. 하나, 둘, 셋에 당겼다. 다섯 칼이 같은 순간 돔 유리 밑 매듭에 들어갔다.<br>한 칼로는 안 갈렸을 것이다. 다섯이 같은 순간이라 갈렸다.<br><br>돔 안의 갓이 처음으로 숨을 멈췄다. 한 박자. 다시 쉬었다. 이번엔 얕게.`,
      ng:`당겼는데 하나가 늦었다. 넷만 들어갔다.<br><br>매듭이 갈렸다 다시 붙는다. 붙는 자리에서 포자가 터졌다. 다섯이 다 기침을 했다. 하나는 한참 멈추지 못했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-14, mind:-8 } }
  ] }

]);

// ──────────────────────────────────────────
// 견습 기사 (knight) · 무력
// ──────────────────────────────────────────
kJob('knight', 'C', [

{ at:'C', t:'굴 입구 — 뿔 셋 달린 놈',
  x:`굴에서 놈이 나온다. 머리를 낮추고. 뿔이 셋이다.<br><br>
    팀원들은 옆으로 흩어지기로 했다. 놈이 지나간 자리를 찌르기로. 그러려면 누군가 놈 앞에 있어야 한다. 놈이 똑바로 달려오도록.<br>
    견습 기사가 앞에 섰다. 방패는 아직 없다.<br><br>
    놈이 땅을 긁는다. 이쪽만 본다.`,
  o:[
    { l:'① 무력을 발끝까지 내려 땅에 박고 받는다.', k:'steady', dc:15, cost:{ might:20 },
      ok:`발을 앞뒤로 벌렸다. 무력을 아래로 내렸다. 무릎, 발목, 발바닥. 땅에 박았다.<br><br>뿔이 칼등에 걸렸다. 몸이 밀린다. 두 뼘. 거기서 멈췄다. 놈이 멈췄다.<br>멈춘 놈 옆구리에 창 넷이 들어갔다.<br><br>막는 건 팔이 아니라 발이었다. 힘을 땅에 맡기면 땅이 같이 막는다. 서는 법이 하나 늘었다.`,
      ng:`박은 발이 미끄러졌다. 바닥이 젖었다.<br><br>뿔 하나가 허벅지를 스쳤다. 굴렀다. 놈이 지나간 자리를 팀원들이 찔렀다. 반은 빗나갔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-6 }, wake:1 },
    { l:'② 닿기 직전에 옆으로 구르며 놈을 벽으로 보낸다.', k:'evade', dc:14,
      ok:`서 있다가 뿔이 닿기 직전에 옆으로 굴렀다.<br><br>놈은 이쪽이 있던 자리로 그대로 달려 벽에 박혔다. 뿔 하나가 벽에 꽂혔다. 팀원들이 덮쳤다.<br>비켜선 것이다. 등을 보인 건 아니다. 스스로 그렇게 말했다.`,
      ng:`너무 일찍 굴렀다. 놈이 같이 꺾었다.<br><br>옆구리를 받혔다. 숨이 한참 안 쉬어졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-18, spirit:-4 } }
  ] },

{ at:'C', t:'굴 앞 — 미끼',
  x:`놈이 굴에서 안 나온다. 굴 안에서는 못 잡는다. 좁다.<br><br>
    밖으로 끌어내야 한다. 놈은 피 냄새를 따라 나온다. 다친 것을 노린다.<br>
    팀원 중 다친 사람이 있다. 그 사람을 굴 앞에 두면 나온다.<br><br>
    맹세 첫 줄. 약한 자를 지킨다. 약한 자를 미끼로 두는 법은 없다.`,
  o:[
    { l:'① 이쪽 팔을 그어 피를 내고 굴 앞에 선다.', k:'bond', dc:15,
      doom:{ title:'미끼', what:'굴 속으로 끌려 들어갑니다', dc:15, sec:60,
        text:`팔뚝을 칼끝으로 그었다. 얕게. 굴 앞에 섰다.<br><br>놈이 나왔다. 생각보다 빨리. 생각보다 낮게. 발목을 물었다.<br>밖으로 끌어내는 게 아니라 안으로 끌고 들어간다. 굴은 좁다. 팀원들 창이 안 닿는다.<br><br>손톱으로 굴 입구를 긁는다. 팀원 손이 손목을 잡는다.`,
        dieText:`굴 안은 좁았다.<br><br>그래도 끝까지 등을 보이지 않았다. 굴 안을 보고 끌려갔다.<br>굴 입구에 손톱자국이 다섯 줄 남았다. 바깥쪽을 향해.` },
      ok:`팔뚝을 그었다. 얕게. 굴 앞에 섰다. 다친 팀원은 뒤에 뒀다.<br><br>놈이 나왔다. 발목을 노렸다. 발을 들어 칼로 내리찍었다. 놈 머리가 굴 밖에 걸렸다.<br>팀원들이 꼬리를 잡아 끌어냈다. 밖에서 잡았다.<br><br>팔뚝을 묶으며 다친 팀원이 이쪽을 본다. 대신 피를 낸 사람을 보는 눈이다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 굴 입구에 젖은 풀을 태워 연기를 들여보낸다.', k:'fix', dc:14,
      ok:`젖은 풀을 모아 굴 입구에서 태웠다. 연기를 웃옷으로 부쳐 들여보냈다.<br><br>안에서 기침 소리가 난다. 짐승도 기침을 한다. 놈이 뛰쳐나왔다. 눈이 반쯤 감겼다.<br>못 보는 놈은 잡기 쉽다.`,
      ng:`연기가 굴로 안 들어가고 이쪽으로 왔다. 바람이 굴에서 나온다.<br><br>다섯이 다 눈물을 흘리는데 놈이 나왔다. 놈은 눈이 멀쩡했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C', t:'사냥터 — 깔린 사람',
  x:`다른 팀 사냥꾼이 놈 밑에 깔렸다. 놈이 앞발로 누르고 있다. 아직 안 문다. 고르는 중이다.<br><br>
    그 팀 나머지는 멀리 흩어졌다. 소리를 지르며 돌을 던진다. 아무도 안 다가간다.<br>
    견습 기사와 놈 사이 열 걸음.<br><br>
    놈 입이 내려온다.`,
  o:[
    { l:'① 소리 지르며 달려들어 놈 눈을 이쪽으로 끈다.', k:'bond', dc:15,
      ok:`소리를 질렀다. 이름도 모르는 사람을 부르듯. 달렸다.<br><br>놈이 고개를 든다. 이쪽을 본다. 깔린 사람에게서 눈을 뗐다. 그걸로 됐다.<br>칼로 놈 코끝을 쳤다. 놈이 물러난다. 깔린 사람을 끌어냈다. 그 팀이 그제야 달려왔다.<br><br>막는 데 몸만 쓰는 게 아니었다. 눈길을 끌어오는 것도 막는 것이다. 놈 눈을 제 쪽으로 받는 법을 처음 써 봤다.`,
      ng:`소리를 질렀는데 놈이 안 돌아본다. 먼저 잡은 걸 놓지 않는다.<br><br>가까이 가서 칼을 댔다. 그제야 돌아봤다. 이쪽 어깨를 물었다. 깔린 사람은 그 틈에 기어 나갔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-18, mind:-6 }, wake:1 },
    { l:'② 무력을 어깨에 실어 옆구리를 들이받는다.', k:'break', dc:15, cost:{ might:18 },
      ok:`무력을 어깨에 모아 들이받았다. 놈이 옆으로 밀려 넘어진다.<br><br>넘어진 놈 위로 그 팀이 돌 대신 창을 들고 왔다. 한 사람이 다가오니 다 다가온다.<br>깔렸던 사람이 이쪽 소매를 잡고 일어섰다. 갈비가 나갔다고 한다. 살았다.`,
      ng:`들이받았는데 놈이 무겁다. 이쪽 어깨가 울렸다.<br><br>놈이 깔린 사람을 놓고 이쪽을 눌렀다. 둘이 같이 깔렸다. 그 팀이 그제야 달려왔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-6 } },
    { l:'③ 흩어진 그 팀을 불러 모아 같이 간다.', k:'fix', dc:14,
      ok:`그 팀에게 소리쳤다. 돌 던지지 말고 모이라고. 셋 세면 같이 가자고.<br><br>셋. 다섯이 아니라 아홉이 갔다. 놈이 아홉을 보고 깔린 사람을 놓았다. 물러났다.<br>모인 사람은 혼자일 때보다 덜 무섭다. 그 팀 반장이 그걸 늦게 알았다.`,
      ng:`모으는 동안 놈이 골랐다. 깔린 사람 다리를 물었다.<br><br>아홉이 달려갔을 때 놈은 다리를 물고 물러났다. 다리를 놓고 가게 하는 데 한참 걸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ spirit:-12, mind:-6 } }
  ] },

{ at:'C', t:'벽 틈 — 침 뱉는 것들',
  x:`놈들이 침을 뱉는다. 멀리서. 침이 닿은 돌이 연기를 낸다.<br><br>
    세 마리다. 벽 틈에 붙어 번갈아 뱉는다. 다가가야 잡는다. 다가가는 동안 맞는다.<br>
    바닥에 큰 짐승 등딱지가 하나 있다. 먼저 잡힌 놈 것이다. 무겁고 두껍다.<br><br>
    방패가 없는 견습은 방패가 될 만한 것부터 본다.`,
  o:[
    { l:'① 무력으로 등딱지를 들고 앞장선다.', k:'steady', dc:15, cost:{ might:20 },
      ok:`들었다. 팔이 떨린다. 등딱지 뒤로 다섯이 붙었다.<br><br>침이 등딱지에 떨어진다. 치익. 치익. 바깥이 끓는다. 안쪽은 멀쩡하다.<br>벽 앞까지 갔다. 등딱지를 내리찍었다. 한 마리가 깔렸다. 둘은 팀원들이 잡았다.<br><br>등딱지에 구멍이 셋 났다. 손바닥 하나만큼만 더 갔으면 이쪽 얼굴이었다.`,
      ng:`들었는데 반쯤 가다 팔이 내려왔다.<br><br>침 한 덩이가 등딱지 위로 넘어왔다. 정수리를 스쳤다. 머리카락이 탔다. 두피가 쓰라리다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-16, spirit:-6 } },
    { l:'② 침 뱉는 박자를 세어 틈마다 달린다.', k:'sense', dc:14,
      ok:`셋이 번갈아 뱉는다. 하나, 둘, 셋, 쉼. 셋째 다음에 숨을 고른다.<br><br>쉼마다 다섯 걸음씩 달렸다. 다섯이 다 같이. 네 번째 쉼에 벽에 닿았다.<br>벽에 닿은 놈들은 뱉을 거리가 없다. 가까우면 침보다 칼이 빠르다.`,
      ng:`셋째 다음에 넷째가 있었다. 벽 위쪽에 하나 더 붙어 있었다.<br><br>쉼인 줄 알고 달렸다. 왼팔에 맞았다. 소매가 녹아 살에 붙었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-16, mind:-4 } }
  ] },

{ at:'C', t:'굴 구석 — 떠는 새끼',
  x:`굴 구석에 작은 것이 웅크렸다. 놈 새끼다. 털이 덜 났다. 떤다.<br><br>
    팀원 하나가 창을 든다. 새끼도 자라면 놈이 된다고.<br>
    맹세 첫 줄. 약한 자를 지킨다.<br>
    약한 자가 사람이어야 한다고는 안 적혀 있다.<br><br>
    새끼가 운다. 가늘게. 굴 안쪽 어딘가에서 같은 소리가 굵게 대답한다.`,
  o:[
    { l:'① 창을 막고 새끼를 건드리지 않은 채 물러난다.', k:'bond', dc:15,
      ok:`팀원 창을 손으로 눌렀다. 새끼를 건드리지 말자고 했다.<br><br>굴 안쪽 굵은 소리가 가까워진다. 다섯이 뒷걸음쳤다. 새끼를 사이에 두고.<br>큰 것이 나왔다. 새끼를 핥는다. 이쪽을 본다. 한참. 그리고 새끼를 물고 안으로 들어갔다.<br><br>쫓아오지 않았다. 지킨 건 새끼만이 아니었다. 첫 줄이 한 줄보다 길다는 걸 알았다. 누구를 지키느냐는 그때마다 새로 정해야 한다.`,
      ng:`창을 눌렀는데 팀원이 뿌리친다. 새끼가 비명을 지른다.<br><br>창은 빗나갔다. 굵은 소리가 달려왔다. 어미는 새끼 앞의 누구든 문다. 이쪽이 앞에 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-18, mind:-6 }, wake:1 },
    { l:'② 새끼 소리로 어미를 끌어내 잡는다.', k:'hide', dc:14,
      ok:`새끼를 건드리지 않았다. 새끼가 울게 두고 다섯이 굴 입구 양옆에 숨었다.<br><br>어미가 나왔다. 새끼한테 가는 길에 창 다섯이 있었다.<br>잡았다. 새끼는 그 자리에서 계속 울었다.<br><br>맹세에 안 적힌 일을 했다. 안 적혀 있으니 어긴 것도 아니다. 마음은 그걸 믿지 않았다.`,
      ng:`숨었는데 어미가 입구에서 멈췄다. 냄새를 맡는다.<br><br>새끼를 물고 안으로 들어가 버렸다. 그리고 안쪽에서 길게 울었다. 다른 놈들이 그 소리를 듣고 모여들었다.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ hp:-12, spirit:-10 } }
  ] },

{ at:'C', t:'물러날 때 — 둘째 줄',
  x:`놈이 너무 크다. 반장이 물러나자고 한다. 지금.<br><br>
    다섯이 돌아서 뛰면 놈이 등을 문다. 놈은 뛰는 걸 쫓는다.<br>
    맹세 둘째 줄. 등을 보이지 않는다.<br><br>
    물러나야 하는데 등을 보이면 안 된다.`,
  o:[
    { l:'① 놈을 마주 본 채 뒷걸음으로 맨 뒤를 맡는다.', k:'steady', dc:15,
      ok:`돌아서지 않았다. 놈을 본 채 한 걸음씩 뒤로 갔다. 칼끝을 놈 코앞에 두고.<br><br>팀원들은 뒤에서 뛰어 계단에 닿았다. 이쪽은 걸었다. 뒤로. 놈은 뛰는 걸 쫓는 놈이다. 걷는 건 쫓지 않는다. 노려본다.<br>계단 첫 칸에 발뒤꿈치가 닿았다. 그제야 돌아섰다.<br><br>물러나는 것과 등을 보이는 것은 다르다. 둘째 줄을 지키면서 물러났다. 발이 뒤로 걷는 법을 배웠다.`,
      ng:`뒷걸음치다 돌부리에 걸렸다. 넘어졌다.<br><br>넘어진 건 등이 아니라 엉덩이였다. 놈은 그 차이를 모른다. 덮쳐 왔다. 칼을 세워 막았다. 팀원들이 돌을 던지며 끌어올렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-8 }, wake:1 },
    { l:'② 맹세는 이쪽 것이라며 다 같이 돌아서 뛴다.', k:'evade', dc:14,
      ok:`맹세는 이쪽 것이다. 팀원들 것은 아니다. 다 같이 돌아서 뛰었다. 이쪽도.<br><br>놈이 쫓아왔다. 계단에서 멈췄다. 다 살았다.<br>계단에 앉아 숨을 고르며 이쪽만 오래 말이 없었다.`,
      ng:`뛰다 맨 뒤 사람이 넘어졌다. 놈이 그 등에 닿았다.<br><br>돌아서서 칼을 휘둘렀다. 결국 등을 안 보인 셈이다. 늦게. 팔을 깊게 긁혔다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-16, spirit:-8 } }
  ] },

{ at:'C', t:'쉬는 자리 — 시체 옆 보초',
  x:`사냥한 놈 시체를 두고 쉰다. 시체 냄새가 다른 것들을 부른다. 누가 깨어 있어야 한다.<br><br>
    견습 기사가 일어섰다. 보초는 막내 몫이라고 배웠다. 여기서 이쪽은 막내가 아니다. 그래도 일어섰다.<br>
    시체 쪽에서 무언가 뜯는 소리가 난다. 작은 것들이다. 여럿.<br><br>
    작은 것들은 뜯다가 커진다.`,
  o:[
    { l:'① 무력으로 졸음을 누르고 시체 옆에 선다.', k:'steady', dc:14, cost:{ might:15 },
      ok:`시체와 잠든 다섯 사이에 섰다. 무력으로 졸음을 눌렀다.<br><br>작은 것들이 시체를 뜯다가 이쪽을 본다. 서 있는 것은 먹이가 아니다. 다시 시체로 고개를 돌린다.<br>밤새 시체만 줄었다. 사람은 안 줄었다.`,
      ng:`새벽에 무릎이 꺾였다. 선 채로 졸았다.<br><br>눈을 뜨니 작은 것 하나가 이쪽 신발끈을 씹고 있었다. 커진 것이다. 걷어찼다. 발등을 물렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, mind:-8 } },
    { l:'② 시체를 끌어다 멀리 버린다.', k:'break', dc:14,
      ok:`시체 다리를 잡고 끌었다. 무겁다. 모퉁이 둘 너머에 버렸다.<br><br>뜯는 소리가 시체를 따라갔다. 모퉁이 너머에서 밤새 났다. 쉬는 자리는 조용했다.`,
      ng:`끄는데 시체 배에서 작은 것들이 쏟아져 나왔다. 안에서 뜯고 있었다.<br><br>팔을 타고 올라왔다. 털어 내는 데 한참 걸렸다. 팔이 붉게 부었다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-14, spirit:-6 } },
    { l:'③ 뜯기기 전에 먹을 만한 고기부터 떼어 둔다.', k:'sense', dc:14,
      ok:`작은 것들이 뜯기 전에 칼을 댔다. 등심 쪽. 제일 깨끗한 데.<br><br>떼어 낸 고기를 불가에 걸었다. 나머지는 작은 것들 몫으로 뒀다. 다 같이 먹으면 아무도 이쪽으로 안 온다.`,
      ng:`칼을 대는데 고기가 퍼렇다. 속부터 상했다.<br><br>상한 냄새가 확 퍼졌다. 작은 것들이 더 모였다. 밤새 쫓았다.`,
      win:{ exp:14, dream:2, item:'짐승 고기' }, lose:{ mind:-10, hp:-8 } }
  ] },

{ at:'C', t:'벽에 기댄 사냥꾼 — 가슴판 안쪽',
  x:`쓰러진 사냥꾼이 벽에 기대 앉았다. 오래됐다. 가슴판이 멀쩡하다. 그 아래가 멀쩡하지 않다.<br><br>
    가슴판 안쪽에 글씨가 새겨져 있다. 칼끝으로. 세 줄.<br>
    견습 기사가 외는 세 줄이 아니다. 비슷하다. 한 사람을 지킨다. 그 사람 앞에서 쓰러진다. 그 사람은 살아 나갔다.<br><br>
    가슴판은 이쪽 몸에 맞을 것 같다.`,
  o:[
    { l:'① 그 세 줄 밑에 이쪽 세 줄을 새기고 덮어 준다.', k:'bond', dc:14,
      ok:`칼끝으로 가슴판 안쪽 아래에 새겼다. 이쪽 세 줄. 그 사람 세 줄 밑에.<br><br>새기다 보니 이쪽 셋째 줄이 그 사람 셋째 줄과 닮았다. 맹세를 버리지 않는다. 그 사람은 버리지 않았다. 다 지켰다.<br>가슴판을 그 사람에게 도로 덮어 줬다.<br><br>세 줄을 외우기만 했었다. 오늘은 남의 세 줄 옆에 놓아 봤다. 놓아 보니 이쪽 줄 뜻이 조금 더 깊어졌다. 맹세가 입에서 손으로 내려왔다.`,
      ng:`새기는데 칼끝이 미끄러져 그 사람 줄을 긁었다.<br><br>둘째 줄이 지워졌다. 다시 새겨도 안 된다. 남의 맹세를 망쳤다. 손이 오래 떨렸다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ spirit:-12, mind:-6 }, wake:1 },
    { l:'② 가슴판을 벗겨 이쪽에 맞춘다.', k:'steady', dc:14,
      ok:`끈을 풀어 가슴판을 벗겼다. 이쪽에 댔다. 맞는다.<br><br>무겁다. 숨이 한 뼘 짧아진다. 대신 가슴은 단단하다.<br>안쪽 글씨가 이쪽 가슴에 닿는다. 걸을 때마다 남의 맹세가 살갗에 눌린다.`,
      ng:`벗기는데 그 사람 몸이 무너졌다. 오래된 것이다.<br><br>가슴판 안쪽에서 무언가 기어 나왔다. 그 안에 살던 것이다. 손등을 물고 달아났다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-8 } }
  ] },

{ at:'C1', t:'고기 숲 — 흔들리는 덩이들',
  x:`갈고리마다 고깃덩이가 걸려 흔들린다. 통로가 고기 숲이다.<br><br>
    덩이들이 흔들리는 박자가 안 맞는다. 바람이 없는데 흔들린다. 지나가는 사람 쪽으로 기운다.<br>
    덩이 하나가 사람 키만 하다. 부딪히면 넘어진다. 넘어지면 바닥 고기가 붙는다.<br><br>
    견습 기사가 맨 앞에 섰다. 고기 숲에서도 앞은 앞이다.`,
  o:[
    { l:'① 무력을 어깨에 실어 덩이를 밀어 길을 연다.', k:'steady', dc:15, cost:{ might:18 },
      ok:`어깨로 덩이를 밀었다. 무겁다. 미지근하다. 밀린 덩이가 옆 덩이를 밀고, 옆 덩이가 또 옆 덩이를 민다.<br><br>사람 하나 지날 틈이 났다. 그 틈에 몸을 세워 버텼다. 뒤의 다섯이 지나갔다.<br>마지막 사람이 지나자 어깨를 뺐다. 덩이들이 한꺼번에 제자리로 돌아오며 이쪽 등을 쳤다.`,
      ng:`미는 덩이가 미는 만큼 자란다. 어깨가 고기에 파묻힌다.<br><br>빼내는데 살이 들러붙었다. 옷째 뜯어냈다. 어깨가 쓰라리다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
    { l:'② 덩이 사이 박자를 보고 한 사람씩 들여보낸다.', k:'bond', dc:14,
      ok:`앞에 서서 덩이들을 봤다. 흔들림이 겹치지 않는 때가 있다. 그때마다 뒷사람 등을 밀었다. 하나. 하나.<br><br>다섯을 다 들여보내고 이쪽이 마지막으로 들어갔다. 다섯이 건너편에서 이쪽을 기다렸다.<br>앞에 서는 일에 뒤를 보내는 일이 있었다. 문간에 서서 하나씩 세어 보내는 손. 맨 앞이 맨 뒤까지 맡는 법을 하나 배웠다.`,
      ng:`셋째를 미는데 덩이가 한 박자 일찍 왔다.<br><br>셋째가 덩이에 부딪혀 넘어졌다. 바닥 고기에 반쯤 묻혔다. 달려가 끌어냈다. 이쪽 무릎도 묻혔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-14, spirit:-6 }, wake:1 },
    { l:'③ 갈고리 줄을 쳐서 덩이를 떨군다.', k:'break', dc:15,
      ok:`칼로 갈고리 끈을 쳤다. 덩이가 떨어진다. 하나, 둘, 셋.<br><br>떨어진 덩이가 바닥에서 꿈틀거리며 서로 붙는다. 붙는 데 시간이 걸린다. 그 사이 지나갔다.`,
      ng:`떨어진 덩이가 이쪽 발 위로 떨어졌다.<br><br>무겁다. 그리고 붙는다. 발등에 고기가 자라 올라온다. 셋이 달려들어 칼로 떼어 냈다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-18, mind:-4 } }
  ] },

{ at:'C1', t:'도축대 — 칼과 팀원 사이',
  x:`줄 끝의 그것이 칼을 든다. 앞치마가 무릎까지 젖었다.<br><br>
    팀원 하나가 고기 더미에 발이 붙었다. 못 움직인다. 그것이 그쪽으로 온다. 고깃덩이인 줄 안다.<br>
    칼이 올라간다. 팀원은 고개만 든다.<br><br>
    이쪽과 팀원 사이 다섯 걸음. 칼과 팀원 사이 한 걸음.`,
  o:[
    { l:'① 사이로 뛰어들어 칼을 받는다.', k:'bond', dc:15,
      doom:{ title:'도축대', what:'도축대 위로 끌려 올라갑니다', dc:15, sec:55,
        text:`뛰어들었다. 칼등으로 칼을 받았다. 팔꿈치까지 울린다.<br><br>그것이 멈춘다. 받은 쪽을 본다. 고깃덩이가 칼을 막은 건 처음일 것이다.<br>칼을 거두지 않는다. 대신 다른 손으로 이쪽 허리띠를 잡는다. 든다. 도축대 위로.<br><br>도축대가 차다. 넓다. 사람 하나 눕기 딱 맞다.`,
        dieText:`도축대 위의 것은 썰렸다.<br><br>바닥에 던져졌다. 던져진 자리에서 다시 자라기 시작했다.<br>자라는 것은 무릎을 꿇은 모양이다. 칼을 막던 자세 그대로.` },
      ok:`뛰어들었다. 칼등으로 칼을 받았다. 무릎이 꺾일 뻔했다.<br><br>버텼다. 그것이 칼을 누른다. 더 버텼다. 그 사이 팀원들이 붙은 발을 고기째 떼어 냈다.<br>그것이 칼을 거둔다. 받은 쪽을 오래 본다. 그리고 다음 갈고리로 돌아섰다. 일이 밀렸다.<br><br>칼등에 금이 갔다. 이쪽 팔에도 금이 간 것 같다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 더 큰 덩이를 던져 그것의 일을 바꿔 준다.', k:'luck', dc:14,
      ok:`옆 갈고리의 큰 덩이를 끊어 도축대 앞에 던졌다. 그것이 고개를 돌린다. 더 큰 일감이다.<br><br>그쪽을 썰기 시작했다. 그 사이 팀원을 떼어 냈다.<br>그것은 끝까지 이쪽을 안 봤다. 일 앞에서는 사람이 안 보인다.`,
      ng:`던진 덩이가 작았다. 그것은 작은 걸 두고 팀원 쪽 칼을 내렸다.<br><br>팀원이 몸을 틀어 피했다. 칼이 팔뚝을 스쳤다. 피가 고기 더미에 떨어지자 더미가 들썩였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-16, spirit:-8 } }
  ] },

{ at:'C1', t:'갈고리 레일 — 남의 막내',
  x:`갈고리 하나에 사람이 걸렸다. 작다. 다른 팀 막내다. 겉옷 등판이 갈고리에 꿰였다.<br><br>
    막내가 운다. 발이 바닥에 안 닿는다. 레일이 막내를 줄 끝으로 데려간다.<br>
    그 팀은 저쪽에서 다른 것과 싸우고 있다. 못 본다.<br><br>
    견습도 막내였던 적이 있다. 그때 기다려 준 사람은 없었다. 그래서 기다리는 쪽이 되기로 했다.`,
  o:[
    { l:'① 무력으로 갈고리째 레일에서 뽑아낸다.', k:'break', dc:15, cost:{ might:22 },
      ok:`갈고리를 잡고 무력을 끌어올렸다. 레일에서 뽑았다. 쇠가 비명을 질렀다.<br><br>막내를 안고 떨어졌다. 갈고리는 아직 막내 등에 걸린 채다. 천을 찢어 뺐다.<br>막내를 그 팀에 데려다줬다. 그쪽 반장이 이쪽 손을 본다. 손바닥이 갈고리 모양으로 패였다.`,
      ng:`뽑는데 레일이 이쪽을 끌고 간다. 막내와 같이.<br><br>둘이 줄 끝 가까이 갔다. 갈고리를 놓고 막내 옷을 찢었다. 같이 떨어졌다. 무릎이 고기 더미에 박혔다. 끈적했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-8 } },
    { l:'② 레일 아래로 따라 뛰며 그 팀을 부른다.', k:'bond', dc:14,
      ok:`레일 아래를 따라 뛰며 그 팀을 불렀다. 이름을 몰라서 막내라고.<br><br>그 팀 반장이 돌아봤다. 둘이 같이 뛰어 막내를 내렸다. 반장이 막내를 안고 이쪽을 봤다.<br>그 팀 일은 그 팀이 했다. 이쪽은 부르기만 했다. 그래도 기다린 셈이다.`,
      ng:`부르는 소리에 그 팀이 아니라 그 팀이 싸우던 것이 돌아봤다.<br><br>그것이 이쪽으로 왔다. 떼어 내고 막내를 내렸을 때 막내 등에 칼자국이 하나 있었다. 얕았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-8 } }
  ] },

{ at:'C2', t:'작업대 — 사기 병정',
  x:`공방 한쪽에 사기 병정들이 줄지어 섰다. 손가락 길이. 수백.<br><br>
    창을 들었다. 방패를 들었다. 얼굴마다 사람 이가 박혔다. 웃는 모양으로.<br>
    맨 앞 병정이 방패를 내리고 한 걸음 나온다. 혼자. 이쪽을 보고.<br><br>
    견습 기사가 맨 앞에 선 자세 그대로다. 발 벌린 너비까지.`,
  o:[
    { l:'① 같은 자세로 마주 서서 받는다.', k:'steady', dc:15,
      ok:`발을 맞췄다. 칼을 들었다. 병정이 창을 든다.<br><br>병정이 찔렀다. 작아서 빠르다. 칼등으로 쳐냈다. 다시 찌른다. 쳐냈다. 세 번째에 병정의 창이 부러졌다. 병정이 무릎을 꿇었다.<br>뒤의 수백이 일제히 방패를 내렸다. 길을 냈다.<br><br>맨 앞의 자세를 저것들이 베꼈다. 맨 앞이 무릎 꿇으면 다 내린다. 앞에 선 하나가 뒤 전부를 정한다는 걸 처음 눈으로 봤다. 이쪽 뒤에도 다섯이 있다. 그 다섯도 이쪽 자세를 보고 있었다.`,
      ng:`발을 맞추는데 병정이 이쪽 발을 찔렀다. 신발을 뚫고 들어왔다.<br><br>수백이 같이 한 걸음 나왔다. 다 발등을 노린다. 뒷걸음쳤다. 둘째 줄을 떠올릴 틈이 없었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-14, mind:-8 }, wake:1 },
    { l:'② 다 같이 밟고 지나간다.', k:'break', dc:14,
      ok:`병정은 작다. 밟으면 깨진다. 다섯이 같이 달려 밟았다.<br><br>사기 깨지는 소리가 공방을 채웠다. 깨진 데서 이가 튀어 발목에 박혔다. 작은 이 수십 개.<br>다 지나고 나서 발목에서 이를 하나씩 뽑았다.`,
      ng:`밟는데 방패가 단단하다. 발이 미끄러졌다.<br><br>넘어진 위로 수백이 올라온다. 작은 창이 수백. 팀원들이 옷째 들어 올려 털어 냈다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-16, spirit:-6 } }
  ] },

{ at:'C2', t:'천장 실 — 끌려가는 팀원',
  x:`팀원 등에 실이 붙었다. 천장으로 이어진다. 팀원이 뒤로 끌려간다. 발끝이 바닥을 긁는다.<br><br>
    위층으로 끌려 올라가면 인형이 된다. 진열장에 그렇게 된 것들이 있다. 사람 크기로.<br>
    실은 가늘다. 칼로 끊으면 다른 실이 붙는다. 붙는 것보다 빨리 끌어내야 한다.<br><br>
    팀원 허리를 안았다.`,
  o:[
    { l:'① 무력을 발에 내려 버티며 끌어낸다.', k:'steady', dc:15, cost:{ might:20 },
      ok:`허리를 안고 무력을 내렸다. 발에. 바닥에. 위에서 당기는 힘과 이쪽이 줄다리기를 한다.<br><br>실이 팽팽해진다. 위층 바닥에서 삐걱 소리가 난다. 위에서 버티는 쪽이 지쳤다. 실이 툭 끊겼다.<br>둘이 바닥에 나뒹굴었다. 팀원 등에 실 자국이 하얗게 남았다. 위층에서 화난 발소리가 났다.`,
      ng:`버티는데 실이 하나 더 내려와 이쪽 등에 붙는다.<br><br>둘이 같이 끌린다. 팀원들이 둘을 안았다. 다섯이 다 같이 버텼다. 실이 끊길 때 다섯이 다 넘어졌다. 이쪽이 맨 아래였다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-8 } },
    { l:'② 겉옷을 벗겨 실만 끌려가게 한다.', k:'fix', dc:14,
      ok:`실이 겉옷에 붙었다. 단추를 뜯어 벗겼다. 겉옷만 날아 올라갔다.<br><br>위층 바닥 틈으로 겉옷이 빨려 들어간다. 한참 뒤에 틈에서 겉옷이 도로 떨어졌다. 단추 자리마다 이가 박혀 있었다.`,
      ng:`단추가 안 뜯어진다. 실이 단추마다 감겼다.<br><br>겉옷째 팀원이 들렸다. 칼로 겉옷을 찢었다. 팀원 등까지 같이 그었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-8 } }
  ] },

{ at:'C2', t:'바닥 — 손을 노리는 인형',
  x:`작은 인형들이 바닥을 기어 온다. 이를 딱딱 부딪친다.<br><br>
    견습의 장갑은 두껍다. 받은 장비는 그것 하나다. 사람 이가 못 뚫을 것이다.<br>
    팀원들 손은 맨손이다. 인형들은 손을 노린다. 손가락 다섯이 다 이처럼 생겨서 좋아하는 것 같다.<br><br>
    장갑은 한 켤레다.`,
  o:[
    { l:'① 장갑을 벗어 제일 손 많이 쓰는 팀원에게 끼운다.', k:'bond', dc:14,
      ok:`장갑을 벗어 창 쓰는 팀원에게 끼웠다. 창은 손으로 쥔다.<br><br>그 팀원이 인형을 쥐고 깨뜨렸다. 하나, 둘, 열. 장갑 위로 이가 미끄러진다.<br>이쪽 맨손은 겨드랑이에 끼우고 발로 찼다. 칼은 팔꿈치로 쥐었다. 서툴렀다. 그래도 됐다.`,
      ng:`벗어 주는데 팀원이 거절한다. 견습 장갑인 걸 안다.<br><br>실랑이하는 사이 인형 하나가 이쪽 맨손을 물었다. 결국 억지로 끼워 줬다. 손가락 하나가 부었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, mind:-6 } },
    { l:'② 장갑 낀 손으로 인형들을 잡아 깨뜨린다.', k:'break', dc:15,
      ok:`장갑 낀 손으로 잡히는 대로 쥐었다. 바닥에 내리쳤다.<br><br>사기가 깨진다. 이가 장갑을 문다. 못 뚫는다. 계속 쥐고 깼다.<br>팀원들 손이 닿기 전에 이쪽 손이 먼저 갔다. 장갑에 잇자국이 수십 개 남았다.`,
      ng:`쥐는데 인형이 장갑 손목 틈을 물었다.<br><br>틈은 장갑이 못 막는다. 손목에 이가 줄지어 박혔다. 떼어 내는 데 셋이 붙었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } },
    { l:'③ 장갑을 벗어 멀리 던져 미끼로 쓴다.', k:'luck', dc:14,
      ok:`장갑을 벗어 공방 반대편으로 던졌다. 손가락 다섯 달린 것이 날아간다.<br><br>인형들이 장갑으로 몰려간다. 물고 뜯는다. 그 사이 지나갔다.<br>받은 단 하나의 장비를 버렸다. 버리고 나니 손이 가벼웠다. 가벼운 게 마음에 걸렸다.`,
      ng:`던진 장갑이 가깝게 떨어졌다.<br><br>인형들이 장갑을 물고 이쪽으로 왔다. 장갑을 낀 이쪽 손인 줄 알고. 맨손이 물렸다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-12, mind:-6 } }
  ] },

{ at:'C3', t:'골 바닥 — 떨어진 기도대',
  x:`뒤집힌 성당. 머리 위에 기도대가 줄지어 박혀 있다. 거꾸로.<br><br>
    골 바닥 한 곳에 기도대 하나가 떨어져 있다. 발밑에. 바로 놓였다. 무릎 놓는 자리가 닳았다.<br>
    견습은 무릎을 꿇는 법을 안다. 맹세할 때 꿇는다.<br><br>
    기도대 앞에서는 종 같은 것들이 조용하다. 다른 데서는 사람이 지나가면 운다.`,
  o:[
    { l:'① 기도대에 무릎을 꿇고 세 줄을 읊는다.', k:'steady', dc:15,
      ok:`무릎을 꿇었다. 닳은 자리에 무릎이 맞는다. 세 줄을 입술로 읊었다.<br><br>종 같은 것들이 한쪽으로 기운다. 듣고 있다. 셋째 줄이 끝나자 하나가 한 번 울었다. 낮게. 들었다는 소리 같다.<br>그동안 팀원들이 골을 지나갔다. 아무것도 오지 않았다.<br><br>일어서니 무릎이 차다. 이 기도대에 무릎 꿇은 사람이 이쪽 말고도 많았다. 다들 바깥에서 온 사람이었을 것이다.`,
      ng:`무릎을 꿇었는데 기도대가 들썩한다. 위로 떨어지려 한다.<br><br>무릎이 같이 뜬다. 팀원이 어깨를 눌러 줬다. 기도대만 위로 떨어져 올라갔다. 이쪽 무릎 살갗을 조금 가져갔다.`,
      win:{ exp:18, dream:2, spirit:6 }, lose:{ hp:-10, spirit:-10 } },
    { l:'② 기도대는 두고 종들 사이로 숨어 지나간다.', k:'hide', dc:14,
      ok:`기도대를 건드리지 않았다. 종 같은 것들 그림자 쪽으로 붙어서 갔다.<br><br>종이 한 번 기울었다. 이쪽을 찾다가 기도대 쪽을 봤다. 아무도 꿇지 않은 기도대를.<br>다섯이 다 지나갔다. 종은 끝까지 기도대를 보고 있었다.`,
      ng:`그림자 쪽 바닥에 촛농이 굳어 있었다. 위로 떨어지다 만 것이다.<br><br>밟았다. 미끄러졌다. 종이 울었다. 길게. 머리 위 의자들 사이에서 무언가 깼다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-12, mind:-8 } }
  ] },

{ at:'C3', t:'골을 타고 — 굴러오는 종',
  x:`둥근 천장 골마다 종 같은 것들이 놓였다. 아가리를 위로.<br><br>
    하나가 흔들린다. 받침에서 빠진다. 이쪽으로 기운다. 여기서 쓰러진다는 건 골을 타고 굴러온다는 뜻이다.<br>
    골 바닥에 팀원 둘이 쉬고 있다.<br><br>
    종은 사람보다 크다. 굴러오면서 아가리가 열렸다 닫힌다.`,
  o:[
    { l:'① 골 바닥으로 뛰어내려 둘 앞에서 종을 받는다.', k:'steady', dc:15, cost:{ might:22 },
      doom:{ title:'굴러오는 종', what:'종 아가리 속에 갇혔습니다', dc:15, sec:55,
        text:`골 바닥으로 뛰어내려 둘 앞에 섰다. 무력을 끌어올렸다.<br><br>종이 굴러온다. 어깨로 받았다. 종이 멈춘다. 멈춘 종의 아가리가 이쪽을 향해 열린다.<br>안에 혀가 있다. 길고 축축하다. 혀가 이쪽 허리를 감는다. 안으로 들인다.<br><br>종이 닫힌다. 안에서 무릎 꿇는 소리가 난다. 종이 운다.`,
        dieText:`종은 다시 골 바닥에 섰다.<br><br>사람이 지나가면 운다. 이제 소리가 조금 다르다. 낮게. 세 번씩.<br>세 줄을 읊는 박자다.` },
      ok:`둘 앞에 섰다. 종이 굴러온다. 어깨로 받았다. 무력이 다 빠진다. 멈췄다.<br><br>아가리가 열리기 전에 종 테두리를 들어 엎었다. 아가리가 바닥으로. 혀가 바닥에 깔렸다.<br>엎어진 종은 운다. 아무 소리도 안 나게.<br><br>쉬던 둘이 종 옆을 기어 나왔다. 어깨가 종 모양으로 멍들었다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 소리쳐 둘을 골 밖으로 굴리게 한다.', k:'bond', dc:14,
      ok:`<span style="color:#d4af37;">"굴러요! 옆으로!"</span> 한 번 소리쳤다.<br><br>둘이 골 바깥 비탈로 굴렀다. 종이 둘이 있던 자리를 지나갔다. 아가리가 허공을 물었다.<br>몸으로 막을 수 없으면 목소리로 막는다. 목소리도 앞에 서는 것이다.`,
      ng:`소리쳤는데 둘이 위를 본다. 종이 어디서 오는지 모른다. 여기서는 위아래가 헷갈린다.<br><br>하나가 늦었다. 종 테두리에 다리를 치였다. 끌어내는 데 둘이 붙었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-8 } }
  ] },

{ at:'C3', t:'성가대 — 넷째 줄',
  x:`성가대가 노래한다. 입이 많은 것들. 가사가 들린다.<br><br>
    약한 자를 지킨다. 등을 보이지 않는다. 맹세를 버리지 않는다.<br>
    견습의 세 줄이다. 입마다 한 줄씩 나눠 부른다. 그리고 넷째 줄로 넘어간다. 여기에 남는다.<br><br>
    넷째 줄을 부르는 입이 이쪽으로 늘어난다. 같이 부르자고.`,
  o:[
    { l:'① 넷째 줄이 올 때마다 셋째 줄을 소리 내 되풀이한다.', k:'steady', dc:15,
      ok:`넷째 줄이 시작될 때 셋째 줄을 소리 내 읊었다. 맹세를 버리지 않는다. 크게.<br><br>성가대가 넷째 줄을 다시 부른다. 이쪽은 셋째를 다시 읊는다. 다시. 다시. 넷째 줄이 셋째 줄에 덮여 끝까지 못 간다.<br>입들이 하나씩 다물렸다. 끝을 못 맺은 노래는 오래 못 간다.<br><br>맹세는 지키는 것인 줄 알았다. 오늘은 맹세로 막았다. 세 줄이 방패가 되는 걸 처음 봤다. 목이 쉬어도 그 소리는 남았다.`,
      ng:`셋째 줄을 읊는데 성가대가 그걸 받아 넷째로 잇는다. 이쪽 목소리로.<br><br>입이 저절로 넷째 줄을 따라가려 한다. 팀원이 이쪽 입을 손으로 막았다. 손바닥 안에서 넷째 줄 첫 글자가 나왔다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-12, spirit:-10 }, wake:1 },
    { l:'② 팀원들 귀를 막아 주고 끌고 지나간다.', k:'bond', dc:14,
      ok:`천을 찢어 다섯 귀를 다 막았다. 이쪽 귀는 마지막에.<br><br>막기 전까지 이쪽만 노래를 들었다. 넷째 줄을 네 번 들었다. 안 따라 했다.<br>다섯을 끌고 문까지 갔다. 문 앞에서 이쪽 귀를 막았다. 그제야 무릎이 떨렸다.`,
      ng:`셋째를 막는데 넷째가 노래를 따라 입을 벌렸다.<br><br>그쪽 입을 막느라 이쪽 귀를 못 막았다. 넷째 줄이 머리에 박혔다. 걸을 때마다 들린다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-10, spirit:-10 } }
  ] },

{ at:'C4', t:'화분 사이 — 늦게 입혀진 것',
  x:`작업복을 입은 것이 화분 사이에 쓰러져 있다. 일어나려 한다. 못 일어난다.<br><br>
    옷 안쪽이 반은 버섯이고 반은 사람이다. 늦게 입혀졌다. 얼굴이 남았다. 눈이 이쪽을 본다.<br>
    입이 움직인다. 소리 없이. 두 글자.<br><br>
    맹세 첫 줄. 약한 자를 지킨다. 지킬 수 없는 약한 자를 어떻게 하는지는 맹세에 없다.`,
  o:[
    { l:'① 옆에 앉아 손을 잡고 끝까지 있는다.', k:'bond', dc:15,
      ok:`옆에 앉았다. 장갑 낀 손으로 그 손을 잡았다.<br><br>하얀 것이 얼굴로 올라온다. 천천히. 눈이 이쪽을 끝까지 본다. 손이 한 번 쥐었다 풀렸다.<br>하얀 것이 다 덮었을 때 그것은 일어나지 않았다. 작업복을 입은 채 그대로 누워 있었다. 일하러 가지 않았다.<br><br>지키는 게 살리는 것만은 아니었다. 끝까지 옆에 있는 것도 지키는 일이다. 첫 줄이 조금 더 무거워졌다.`,
      ng:`옆에 앉는데 그 손이 이쪽 손목을 꽉 쥔다. 사람 힘이 아니다.<br><br>하얀 것이 쥔 손을 타고 이쪽 장갑으로 넘어온다. 장갑을 벗어 던졌다. 손목에 하얀 손자국이 남았다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ hp:-10, spirit:-12 } },
    { l:'② 일어나기 전에 끝을 내 준다.', k:'break', dc:14,
      ok:`칼을 들었다. 눈이 칼을 본다. 피하지 않는다. 두 글자를 한 번 더 한다.<br><br>한 번에 했다. 하얀 것이 멈췄다. 포자가 조금 오르다 가라앉았다.<br>모자를 벗겨 얼굴을 덮어 줬다. 모자 안쪽에 이름이 적혀 있었다.`,
      ng:`칼이 늦었다. 그것이 반쯤 일어났다. 일어난 것은 더 이상 그 얼굴이 아니다.<br><br>모자 아래서 포자가 터졌다. 숨을 참았는데 늦었다. 한참 기침했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, mind:-8 } }
  ] },

{ at:'C4', t:'통로 — 포자 구름',
  x:`포자 짐승이 등을 턴다. 가루가 구름처럼 오른다. 통로를 채운다.<br><br>
    젖은 천으로 입을 막아야 한다. 천이 모자란다. 팀원 하나는 벌써 기침을 한다.<br>
    견습의 망토는 길다. 찢으면 다섯 조각이 나온다.<br><br>
    다섯 조각이면 이쪽 몫은 없다.`,
  o:[
    { l:'① 망토를 찢어 나눠 주고 숨을 참은 채 짐승을 친다.', k:'break', dc:15, cost:{ might:18 },
      ok:`망토를 다섯으로 찢었다. 물을 적셔 하나씩 쥐여 줬다. 이쪽은 숨을 참았다.<br><br>무력으로 숨을 눌러 두고 달렸다. 짐승 목을 쳤다. 두 번. 짐승이 주저앉았다. 등의 가루가 마지막으로 크게 올랐다.<br>통로를 빠져나와 숨을 쉬었다. 목이 따끔하다. 다섯은 천 너머로 멀쩡하게 숨 쉬었다.`,
      ng:`숨을 참다 한 번에 터졌다. 짐승 바로 앞에서.<br><br>가루가 목구멍 깊이 들어갔다. 쳤지만 빗나갔다. 팀원들이 짐승을 잡는 동안 이쪽은 바닥에서 기침만 했다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-6 } },
    { l:'② 짐승 앞을 막고 팀원들을 바람 쪽으로 빼낸다.', k:'bond', dc:14,
      ok:`짐승과 통로 사이에 섰다. 팀원들에게 유리 금 간 쪽을 가리켰다. 바람 드는 쪽.<br><br>넷이 그쪽으로 빠졌다. 짐승은 앞에 선 이쪽을 본다. 등을 털어 가루를 이쪽으로 보낸다.<br>다 빠지고 나서 이쪽도 뒷걸음으로 빠졌다. 등은 안 보였다. 가루는 많이 마셨다.`,
      ng:`막고 서는데 짐승이 이쪽을 지나쳐 기침하는 팀원 쪽으로 갔다.<br><br>약한 쪽을 안다. 따라가 짐승 옆구리를 쳤다. 가루가 터졌다. 둘이 같이 마셨다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C4', t:'중앙 돔 — 둘러선 것들',
  x:`온실 한가운데. 유리 돔 안에 큰 갓이 있다. 부풀었다 꺼진다. 숨 쉰다.<br><br>
    돔 둘레에 작업복 입은 것들이 둘러섰다. 지킨다. 그것을.<br>
    팀이 마지막을 준비한다. 누군가 맨 앞에서 둘러선 것들을 받아 내야 한다. 그 틈으로 넷이 돔에 닿는다.<br><br>
    견습은 저것들을 본다. 지키는 자세다. 이쪽과 같은 자세다.`,
  o:[
    { l:'① 맨 앞에서 둘러선 것들을 받아 낸다.', k:'steady', dc:16, cost:{ might:22 },
      ok:`앞에 섰다. 무력을 발에 박았다. 둘러선 것들이 한꺼번에 왔다. 받았다. 하나, 둘, 셋.<br><br>밀린다. 버틴다. 저것들은 지키려고 미는 것이다. 이쪽도 지키려고 버틴다. 같은 일을 하는 것끼리 맞붙으면 오래 걸린다.<br>등 뒤에서 유리 깨지는 소리가 났다. 넷이 돔에 닿았다. 둘러선 것들이 일제히 힘이 빠졌다. 지킬 것이 없어졌다.<br><br>쓰러진 것들 앞에 한참 서 있었다. 저것들도 앞에 섰던 것들이다. 같은 자세를 마주 받아 보고서야 이쪽 자세가 보였다. 서는 법이 거울처럼 또렷해졌다.`,
      ng:`셋째를 받는데 넷째가 옆으로 돌았다. 이쪽은 앞만 막았다.<br><br>넷째가 돔으로 가던 팀원 등을 덮쳤다. 돌아서 떼어 냈다. 그 사이 앞의 셋이 이쪽을 덮었다. 작업복 냄새가 숨을 막았다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-18, mind:-8 }, wake:1 },
    { l:'② 돔 유리를 깨는 넷 중에 든다.', k:'break', dc:15,
      ok:`앞을 다른 팀원에게 맡겼다. 이쪽은 돔으로 달렸다.<br><br>유리를 칼자루로 쳤다. 금이 간다. 넷이 같이 쳤다. 깨졌다. 갓이 숨을 멈췄다.<br>뒤돌아보니 앞을 맡은 팀원이 무릎을 꿇고 있었다. 버텼다. 이쪽이 서던 자리에서.`,
      ng:`유리가 두껍다. 칼자루가 튕겼다.<br><br>그 사이 둘러선 것 하나가 돔 쪽으로 돌아왔다. 이쪽 등을 잡았다. 앞에 안 섰더니 뒤가 잡혔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-16, spirit:-6 } },
    { l:'③ 둘러선 것들 사이 틈을 본다.', k:'gaze', dc:15,
      ok:`둘러선 것들을 봤다. 다 같은 자세다. 그런데 하나만 발이 반 뼘 뒤에 있다. 늦게 입혀진 것이다.<br><br>그 하나 앞으로 넷을 보냈다. 반 뼘 늦게 막는 것은 반 박자 늦게 막는다. 넷이 그 틈을 뚫었다.<br>자세가 같아도 사람마다 버릇이 남는다. 그 버릇이 틈이었다.`,
      ng:`틈을 보느라 앞에 안 섰다.<br><br>둘러선 것들이 먼저 왔다. 틈이 아니라 이쪽 팀이 둘러싸였다. 겨우 빠져나왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-8 } }
  ] }

]);

// ──────────────────────────────────────────
// 신호수 (signal) · 자원 없음
// ──────────────────────────────────────────
kJob('signal', 'C', [

{ at:'C', t:'몰이 사냥 — 보이지 않는 양쪽',
  x:`몰이 사냥이다. 셋이 놈을 몬다. 둘이 길목에서 기다린다.<br><br>
    모는 쪽과 기다리는 쪽은 서로 안 보인다. 벽 셋을 사이에 뒀다.<br>
    신호수는 가운데 높은 바위에 섰다. 양쪽이 다 보이는 자리. 놈도 보인다.<br><br>
    기다리는 쪽이 창을 너무 일찍 들면 놈이 돌아선다. 너무 늦게 들면 지나간다.`,
  o:[
    { l:'① 놈 발소리에 맞춰 손가락으로 때를 접어 보낸다.', k:'bond', dc:15,
      ok:`놈 발이 땅을 차는 박자를 셌다. 넷에 한 번 크게 디딘다. 그때가 제일 빠르고 제일 못 꺾는다.<br><br>기다리는 쪽에 손을 들어 보였다. 손가락을 하나씩 접었다. 넷. 셋. 둘. 하나에 주먹.<br>주먹에 창 둘이 들렸다. 놈이 거기로 뛰어들었다. 박혔다.<br><br>신호는 뜻을 보내는 것인 줄 알았다. 오늘은 때를 보냈다. 서로 안 보이는 사람들에게 같은 순간을 나눠 주는 손. 손가락 접는 박자가 몸에 붙었다.`,
      ng:`손가락을 접는데 놈이 박자를 바꿨다. 셋에 디뎠다.<br><br>주먹이 늦었다. 창 둘이 놈 꼬리를 찔렀다. 성난 놈이 바위 쪽으로 왔다. 바위 위의 이쪽 쪽으로.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-6 }, wake:1 },
    { l:'② 호루라기로 양쪽에 동시에 알린다.', k:'fix', dc:14,
      ok:`짧게 한 번 불었다. 양쪽 다 들었다. 놈도 들었다.<br><br>놈이 소리에 멈칫했다. 멈칫한 놈은 잡기 쉽다. 기다리던 쪽 창이 들어갔다.`,
      ng:`불었는데 놈이 소리 반대쪽으로 꺾었다. 모는 셋 쪽으로.<br><br>몰던 쪽이 몰렸다. 하나가 받혔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C', t:'귀만 큰 놈 — 소리 없는 사냥',
  x:`이 층 놈은 눈이 없다. 머리에 귀만 크다. 숨소리도 듣는다.<br><br>
    말을 하면 온다. 발을 끌어도 온다. 팀원들은 손짓 다섯을 안다. 멈춰, 가, 아래, 위험, 나를 봐.<br>
    놈을 잡으려면 다섯으로 모자란다. 둘러싸, 기다려, 찔러.<br><br>
    놈이 가까이 있다. 지금 가르쳐야 한다. 소리 없이.`,
  o:[
    { l:'① 손짓 셋을 그 자리에서 만들어 보인다.', k:'bond', dc:15,
      ok:`손바닥으로 원을 그렸다. 둘러싸. 손바닥을 펴고 멈췄다. 기다려. 손가락 둘로 찔렀다. 찔러.<br><br>팀원들이 하나씩 고개를 끄덕인다. 소리 없이.<br>다섯이 원을 그리며 놈을 둘러쌌다. 기다렸다. 놈이 숨소리를 찾는다. 다들 숨을 참았다. 손가락 둘. 다섯 창이 한꺼번에 들어갔다.`,
      ng:`원을 그렸는데 한 사람이 '위험'으로 읽었다. 물러서다 발을 끌었다.<br><br>놈 귀가 그쪽으로 돌았다. 그 사람 팔을 물었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-14, spirit:-6 } },
    { l:'② 돌을 멀리 던져 소리로 놈을 끈다.', k:'sense', dc:14,
      ok:`돌을 멀리 던졌다. 놈이 소리 쪽으로 간다. 등을 보였다.<br><br>그 등에 창이 갔다. 소리도 신호다. 놈한테 보내는 신호.`,
      ng:`돌이 가깝게 떨어졌다. 놈이 그쪽으로 왔다. 이쪽 쪽으로.<br><br>숨을 참았다. 놈이 바로 앞에서 멈췄다. 숨을 쉬고 말았다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-12, mind:-8 } }
  ] },

{ at:'C', t:'어둠 속 — 두 번 울리는 호루라기',
  x:`신호수가 호루라기를 짧게 둘 불었다. 모이라는 신호다.<br><br>
    어둠 속에서 같은 소리가 돌아온다. 짧게 둘. 메아리가 아니다. 메아리는 늦게 오고 작게 온다. 이건 바로 오고 똑같이 온다.<br>
    팀원 넷 중 셋이 모였다. 하나가 소리 쪽으로 갔다. 어둠 속 소리 쪽으로.<br><br>
    그 소리가 다시 분다. 짧게 둘. 이번엔 조금 더 가까이서.`,
  o:[
    { l:'① 따라 들어가 팀원을 데려온다.', k:'bond', dc:15,
      doom:{ title:'두 번째 호루라기', what:'흉내 내는 것에게 끌려갑니다', dc:15, sec:60,
        text:`어둠 속으로 들어갔다. 짧게 하나 불었다. 멈추라는 신호.<br><br>앞에서 팀원이 멈춘다. 그 앞에서 무언가 짧게 하나 분다. 멈추라는 신호. 이쪽 것과 똑같이.<br>팀원 손을 잡았다. 돌아서려는데 발목이 잡힌다. 신호를 배운 것은 손도 있다.<br><br>어둠 속에서 짧게 둘. 모이라는 신호. 이쪽 팀을 부른다.`,
        dieText:`그 층에서는 지금도 호루라기 소리가 난다.<br><br>짧게 둘. 모이라는 뜻이다.<br>소리는 정확하다. 신호수의 버릇까지 들어 있다. 숨을 들이쉴 때 반 박자 끄는 버릇.` },
      ok:`어둠 속으로 들어갔다. 불지 않았다. 팀원 어깨를 손으로 두 번 짚었다. 손 신호다.<br><br>흉내 내는 것은 소리만 배웠다. 어깨 짚는 건 못 배웠다. 팀원이 돌아선다. 손을 잡고 나왔다.<br>뒤에서 짧게 둘이 계속 울렸다. 아무도 안 갔다.<br><br>그날부터 호루라기 앞에 손 신호를 하나 붙이기로 했다. 진짜라는 표시.`,
      win:{ exp:24, dream:3 } },
    { l:'② 정한 적 없는 신호를 불어 진짜와 가짜를 가른다.', k:'gaze', dc:14,
      ok:`짧게, 길게, 짧게. 정한 적 없는 신호를 불었다.<br><br>어둠 속 것이 따라 했다. 짧게, 길게, 짧게. 팀원이 멈칫한다. 정한 적 없는 신호가 두 번 들린다.<br>두 번째로 들리는 쪽이 가짜라는 걸 팀원이 알았다. 돌아서 뛰어왔다.`,
      ng:`새 신호를 불었는데 팀원은 그 뜻을 모른다. 더 헷갈렸다.<br><br>어둠 속 것이 새 신호를 따라 하며 다가온다. 팀원은 그 소리가 이쪽인 줄 알았다. 겨우 붙잡았다. 팔에 손톱자국이 길다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-10 } }
  ] },

{ at:'C', t:'넓은 굴 — 건너편 등불',
  x:`큰 놈이 넓은 굴 한가운데 엎드렸다. 다섯으로는 못 잡는다.<br><br>
    굴 건너편에 다른 팀이 있다. 그쪽도 놈을 노린다. 그쪽도 다섯이다.<br>
    소리치면 놈이 깬다. 건너편까지 서른 걸음. 등불은 보인다.<br><br>
    그쪽은 이쪽 손짓을 모른다. 이쪽도 그쪽 것을 모른다.`,
  o:[
    { l:'① 등불로 두 팀이 같이 쓸 신호를 처음부터 만든다.', k:'bond', dc:15,
      ok:`등불 덮개를 열었다 닫았다. 하나. 그쪽 등불을 가리켰다. 따라 하라고.<br><br>그쪽 등불이 하나 깜빡인다. 됐다. 다음은 둘. 그쪽도 둘. 하나는 예, 둘은 아니오. 셋은 지금.<br>한참 깜빡였다. 놈은 계속 잤다. 셋. 열이 한꺼번에 덮쳤다. 놈이 일어나기 전에 끝났다.<br><br>모르는 사람과 처음부터 말을 만드는 데 백 번이 안 걸렸다. 같이 쓸 말을 짓는 손이 이쪽에게 있었다. 그 손이 오늘 처음 팀 바깥까지 닿았다.`,
      ng:`깜빡이는데 그쪽은 그게 오지 말라는 뜻인 줄 안다. 등불을 꺼 버렸다.<br><br>이쪽 다섯이 혼자 덮쳤다. 놈은 깼다. 반쯤 잡고 반쯤 다쳤다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-8 }, wake:1 },
    { l:'② 굴 벽을 따라 돌아가 직접 말한다.', k:'hide', dc:15,
      ok:`굴 벽에 붙어 돌았다. 서른 걸음이 아니라 백 걸음이었다. 숨을 아꼈다.<br><br>그쪽 반장 귀에 대고 말했다. 셋 세면 같이. 반장이 고개를 끄덕였다.<br>돌아오는 백 걸음이 더 길었다. 셋. 열이 덮쳤다.`,
      ng:`돌다가 놈 꼬리를 밟을 뻔했다. 꼬리가 굴 벽까지 뻗어 있었다.<br><br>놈이 눈을 떴다. 열이 아니라 다섯씩 따로 덮쳤다. 따로 다쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } },
    { l:'③ 돌을 던져 놈을 깨우고 그쪽으로 몬다.', k:'luck', dc:14,
      ok:`돌을 놈 등에 던졌다. 놈이 깬다. 일어나 소리 난 반대쪽을 본다. 그쪽 팀 쪽이다.<br><br>그쪽이 먼저 받았다. 놈이 그쪽과 엉킨 사이에 이쪽이 등을 쳤다. 잡았다.<br>그쪽 반장이 이쪽을 오래 노려봤다. 다친 건 그쪽이 더 많았다.`,
      ng:`던진 돌에 놈이 깨서 돌 날아온 쪽을 봤다.<br><br>놈은 바보가 아니었다. 이쪽으로 왔다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-16, mind:-4 } }
  ] },

{ at:'C', t:'둥지 구멍 — 너무 고른 한 번',
  x:`팀원 하나가 줄을 타고 둥지 구멍으로 내려갔다. 알을 깨러.<br><br>
    줄 신호는 정해 뒀다. 한 번은 괜찮다. 두 번은 더 내려. 세 번은 올려. 네 번은 빨리 올려.<br>
    신호수가 줄을 쥐었다.<br><br>
    줄이 당겨진다. 한 번. 쉬고. 한 번. 쉬고. 한 번. 일정하다. 너무 일정하다.`,
  o:[
    { l:'① 고른 한 번을 사람 손이 아닌 것으로 읽는다.', k:'gaze', dc:15,
      ok:`사람 손은 매번 조금씩 다르다. 이건 똑같다.<br><br>손으로 당긴 게 아니다. 줄이 무언가에 걸려 흔들리는 것이다. 숨 쉬는 무언가에. 그 위에 팀원이 서 있다.<br>네 번을 기다리지 않고 당겼다. 팀원이 올라온다. 발밑에 큰 것이 붙어 따라오다 떨어졌다. 둥지 바닥이 아니라 둥지 주인 등이었다.`,
      ng:`괜찮다는 뜻으로 읽었다. 기다렸다.<br><br>한참 뒤 네 번이 왔다. 정신없이 당겼다. 올라온 팀원 다리에 잇자국이 줄지어 있다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-12, spirit:-8 } },
    { l:'② 이쪽에서 먼저 한 번을 보내 대답을 듣는다.', k:'bond', dc:14,
      ok:`이쪽에서 한 번 당겼다. 괜찮냐는 물음이다.<br><br>대답이 없다. 고른 한 번만 계속 온다. 대답이 없다는 게 대답이다. 당겨 올렸다.<br>팀원이 올라와서 말했다. 아래서 줄을 못 잡고 있었다고. 숨도 못 쉬고 있었다고.`,
      ng:`한 번 보냈는데 아래에서 두 번이 온다. 더 내려 달라는 뜻이다. 내렸다.<br><br>그 두 번은 팀원 손이 아니었다. 줄이 쭉 끌려 내려갔다. 다들 매달려 겨우 올렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C', t:'어긋난 턱 — 손등 두드림',
  x:`팀원 턱이 놈 꼬리에 맞아 어긋났다. 말을 못 한다.<br><br>
    눈은 무언가 말하려 한다. 손가락으로 이쪽 손등을 두드린다. 똑. 똑똑. 똑.<br>
    정한 신호가 아니다. 다급해서 아무렇게나 두드린다.<br><br>
    신호수는 정해지지 않은 신호를 더 잘 듣는다.`,
  o:[
    { l:'① 손등 두드림을 읽는다.', k:'bond', dc:14,
      ok:`두드림을 손등으로 받았다. 셋. 그리고 손가락이 가리킨다. 다시 셋. 손가락이 뒤를 가리킨다.<br><br>뒤에 셋이 있다는 것이다. 돌아보니 벽 틈에 눈이 셋. 같은 놈 새끼들. 숨어서 기다리고 있었다.<br>다들 돌아섰다. 기다리던 것들이 먼저 들켰다.<br><br>말을 잃은 사람에게서 말을 받았다. 정해 둔 것 없이. 사람 손가락은 다급하면 정직해진다. 그 정직함을 듣는 귀가 손등에 생겼다.`,
      ng:`두드림을 아프다는 뜻으로 읽었다. 붕대를 감으려 했다.<br><br>팀원이 고개를 젓는다. 손가락이 뒤를 가리킨다. 늦었다. 등 뒤에서 무언가 덮쳤다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-14, mind:-8 }, wake:1 },
    { l:'② 턱부터 맞춰 준다.', k:'heal', dc:14,
      ok:`턱을 두 손으로 잡고 맞췄다. 딱 소리가 났다.<br><br>팀원이 소리를 질렀다. 그리고 바로 말했다. <span style="color:#d4af37;">"뒤!"</span> 맞춘 턱이 처음 한 말이다. 돌아섰다. 다행히 아직 거리가 있었다.`,
      ng:`맞추는데 더 어긋났다.<br><br>팀원이 정신을 잃었다. 잃기 전에 뒤를 가리켰다. 그건 늦게 봤다.`,
      win:{ exp:16, dream:2, hp:5 }, lose:{ hp:-12, spirit:-6 } }
  ] },

{ at:'C', t:'모닥불 — 새 손짓',
  x:`쉬는 자리. 신호수가 손짓을 가르친다. 다섯으로 모자랐다. 사냥에는 더 필요하다.<br><br>
    뒤. 물린다. 놔. 내가 간다.<br>
    팀원들이 따라 한다. 손이 서툴다. 서툰 손짓은 놈 앞에서 틀린다.<br><br>
    모닥불 너머 어둠에서 무언가 이쪽을 본다. 손짓을 보고 있다.`,
  o:[
    { l:'① 어둠을 등지고 둘러앉아 안쪽으로만 가르친다.', k:'hide', dc:14,
      ok:`다섯이 어둠을 등지고 둘러앉았다. 손은 원 안에서만 움직였다.<br><br>어둠 속 것이 자리를 옮긴다. 안 보이는 모양이다. 한참 돌다 갔다.<br>손짓 넷을 다 익혔다. 다음 날 놈 앞에서 한 번도 안 틀렸다.`,
      ng:`둘러앉았는데 원이 작았다. 팔꿈치가 부딪친다.<br><br>손짓이 커졌다. 등 너머로 보였다. 다음 날 어둠 속에서 누가 '내가 간다'를 했다. 이쪽 팀은 아무도 안 했다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-10, spirit:-6 } },
    { l:'② 보는 쪽이 배우도록 틀린 손짓을 섞어 보인다.', k:'gaze', dc:15,
      ok:`팀원들에게 귓속말을 했다. 지금부터 보이는 건 다 거꾸로라고. 그리고 크게 손짓했다. '뒤'를 '앞'처럼.<br><br>다음 날 굴 앞에서 어둠 속 손 하나가 '뒤'를 했다. 이쪽이 크게 보여 준 대로.<br>다들 앞으로 갔다. 손이 뒤로 물러나다 들켰다. 잡았다.`,
      ng:`거꾸로 보이자는 말을 한 사람이 못 들었다.<br><br>다음 날 그 사람만 거꾸로 움직였다. 굴 앞에서 혼자 뒤로 갔다. 뒤에 놈이 있었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-14, mind:-6 } },
    { l:'③ 손짓 대신 손을 맞잡고 쥐는 박자로 가르친다.', k:'bond', dc:14,
      ok:`옆 사람 손을 잡았다. 꽉 한 번은 '뒤'. 두 번은 '물린다'. 길게는 '놔'. 손등을 쓸면 '내가 간다'.<br><br>다섯이 손을 잡고 돌아가며 연습했다. 어둠 속에서는 아무것도 안 보였을 것이다. 손 잡은 사람들만 보였을 것이다.<br>보이지 않는 신호는 훔쳐 갈 수 없다.`,
      ng:`쥐는 박자가 사람마다 달랐다. 꽉이 얼마나 꽉인지.<br><br>밤새 연습했는데 아침에 다들 손이 아팠다. 첫 굴에서 '놔'를 '뒤'로 읽은 사람이 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-8, hp:-8 } }
  ] },

{ at:'C', t:'통로 벽 — 천천히 묶은 천',
  x:`통로 벽에 천 조각이 묶여 있다. 셋. 같은 높이로.<br><br>
    묶은 모양이 사냥꾼들 표시다. 하나는 놈 있음. 둘은 둘 있음. 셋째는 신호수도 모르는 것이다.<br>
    셋째 천은 묶은 손이 다르다. 서두르지 않았다. 아주 천천히 묶었다.<br><br>
    그 아래 벽에 사람이 기대 있다. 다 끝난 지 오래다.`,
  o:[
    { l:'① 셋째 천의 뜻을 읽는다.', k:'gaze', dc:15,
      ok:`셋째 천 끝이 아래를 가리킨다. 그 사람 손 쪽으로.<br><br>손이 주머니를 쥐고 있다. 펴 보니 꿀 한 줌이 굳어 있다. 끝까지 안 먹은 것이다.<br>천천히 묶은 신호는 뒤에 올 사람에게 쓴 것이다. 남은 걸 남긴다는 표시. 셋째 천을 풀어 그 사람 손목에 감아 줬다.`,
      ng:`아래를 가리키는 줄 알고 바닥을 팠다.<br><br>바닥에 아무것도 없다. 파는 소리에 벽 너머 무언가 깼다. 천이 가리킨 건 그 사람 손이었다. 나중에 알았다.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ hp:-12, spirit:-8 } },
    { l:'② 앞의 두 천을 믿고 둘을 대비해 간다.', k:'bond', dc:14,
      ok:`둘 있다고 했다. 다섯을 둘씩 짝지었다. 남는 하나는 이쪽. 짝끼리 등을 붙이고 가라고 손짓했다.<br><br>모퉁이 둘을 지나 정말 둘이 나왔다. 짝끼리 하나씩 받았다. 이쪽은 양쪽을 다 봤다.<br>앞사람 신호가 맞았다. 앞사람은 거기까지만 왔다.`,
      ng:`둘을 대비했는데 셋이 나왔다. 셋째 천이 셋째였던 모양이다.<br><br>남는 하나를 이쪽이 받았다. 혼자 받기엔 컸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-16, mind:-6 } }
  ] },

{ at:'C1', t:'벽의 종 — 열두 번째 쉼',
  x:`도축장 벽에 종이 달렸다. 줄이 아래로 늘어졌다.<br><br>
    갈고리 레일이 종에 맞춰 돈다. 종이 한 번 울리면 레일이 한 칸 간다. 줄 끝의 것이 한 번 썬다.<br>
    종소리 사이를 셌다. 일정하다. 그런데 열두 번째마다 한 번 길게 쉰다. 그때 줄 끝의 것이 칼을 닦는다.<br><br>
    종을 치는 손이 따로 있다. 보이지 않는다.`,
  o:[
    { l:'① 종줄을 잡고 쉬는 박자를 이쪽이 친다.', k:'bond', dc:15,
      ok:`종줄을 잡았다. 보이지 않는 손이 당기는 힘이 줄을 타고 온다. 그 박자를 따라가다 열하나에서 길게 쉬었다. 한 박자 일찍.<br><br>레일이 선다. 줄 끝의 것이 칼을 닦는다. 이쪽이 쉬는 동안 계속 닦는다. 다섯이 그 사이 줄 아래를 지났다.<br>마지막 사람이 지나고 줄을 놓았다. 보이지 않는 손이 다시 친다. 레일이 돈다.<br><br>남의 신호를 읽기만 하지 않았다. 남의 신호 안에 이쪽 박자를 끼워 넣었다. 남이 치는 종으로 이쪽 말을 했다. 손이 그걸 기억했다.`,
      ng:`종줄을 잡자 보이지 않는 손이 이쪽 손을 잡는다. 차다.<br><br>박자가 엉켰다. 레일이 두 칸 갔다. 줄 끝의 것이 두 번 썬다. 하나는 허공을. 하나는 팀원 소매를.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-14, spirit:-10 }, wake:1 },
    { l:'② 열두 번째 쉼을 기다렸다 한꺼번에 지나간다.', k:'sense', dc:14,
      ok:`다섯을 줄 앞에 세웠다. 손가락으로 종을 셌다. 열. 열하나. 열둘.<br><br>쉼. 다섯이 한꺼번에 뛰었다. 줄 끝의 것은 칼을 닦느라 고개를 숙이고 있었다.<br>건너편에 닿자 종이 다시 울렸다.`,
      ng:`열둘을 셌는데 이번 쉼은 짧았다. 칼을 닦을 게 없었던 모양이다.<br><br>다섯째가 줄 아래 있을 때 레일이 돌았다. 갈고리가 등을 긁고 갔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C1', t:'레일 위 — 갈고리끼리의 말',
  x:`레일 위 갈고리들이 덜그럭거린다. 아무렇게나가 아니다. 셋 덜그럭, 하나 쉼, 둘 덜그럭.<br><br>
    신호수 귀에는 그게 말로 들린다. 갈고리가 갈고리에게 보내는 말.<br>
    소리가 레일을 따라 이쪽으로 온다. 소리를 받은 갈고리가 낮게 내려온다.<br><br>
    누군가 이쪽 자리를 알렸다.`,
  o:[
    { l:'① 칼등으로 레일을 쳐 반대 말을 보낸다.', k:'gaze', dc:15,
      ok:`칼등으로 레일을 쳤다. 하나 덜그럭, 셋 쉼. 방금 들은 것 중에 갈고리가 올라가기 전에 꼭 오던 말.<br><br>내려오던 갈고리들이 멈칫한다. 도로 올라간다. 덜그럭이 레일을 따라 저쪽으로 퍼진다. 이쪽 말이 저쪽 끝까지 갔다.<br>갈고리들이 다 지나갈 때까지 다섯은 서 있었다. 머리 위 한 뼘을.`,
      ng:`쳤는데 박자가 틀렸다. 무슨 말을 했는지 모른다.<br><br>갈고리가 전부 내려왔다. 이쪽으로. 천장이 갈고리로 덮였다. 기어서 빠져나왔다. 등이 긁혔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
    { l:'② 말이 시작되는 갈고리를 찾아 막는다.', k:'sense', dc:15,
      ok:`덜그럭이 어디서 시작되는지 들었다. 레일 첫 굽이. 갈고리 하나에 쇠방울이 달려 있다.<br><br>천을 감아 방울을 막았다. 덜그럭이 끊겼다. 다른 갈고리들이 길을 잃은 듯 제자리에서 흔들렸다.<br>말을 시작하는 쪽이 없으면 아무도 말을 안 한다.`,
      ng:`방울 달린 갈고리를 찾았는데 손이 안 닿는다.<br><br>뛰어오르다 다른 갈고리에 소매가 걸렸다. 매달렸다. 떨어지며 손바닥이 찢겼다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C1', t:'냉동실 — 두꺼운 쇠문',
  x:`쇠문 하나가 닫혔다. 안은 냉동실이다. 팀원 하나가 안에 있다. 놈을 쫓아 들어갔다가 문이 저절로 닫혔다.<br><br>
    문이 두껍다. 소리가 안 지나간다. 두드림은 지나간다.<br>
    안에서 두드린다. 처음엔 크다. 점점 작아진다. 추운 것이다.<br><br>
    바깥에 손잡이가 없다. 안에도 없다고 두드린다.`,
  o:[
    { l:'① 두드림으로 안쪽에 할 일을 알려 준다.', k:'bond', dc:15,
      ok:`문을 두드렸다. 둘, 하나. 들었다는 뜻. 그리고 문틀을 따라 위에서 아래로 셋씩 두드렸다. 경첩이 있는 자리.<br><br>안에서 같은 자리를 두드려 온다. 알아들었다. 안쪽 경첩 핀을 쳐서 빼라는 것. 안과 밖에서 같은 박자로 쳤다. 하나, 둘, 셋에.<br>핀 둘이 빠졌다. 문이 비스듬히 열렸다. 팀원이 하얗게 언 채 기어 나왔다.<br><br>두드림으로 말만 보낸 게 아니었다. 손을 빌려줬다. 안에서 할 수 있는 일을 밖에서 알려 주면 두 사람이 한 일을 한다. 신호가 손이 됐다.`,
      ng:`경첩 자리를 두드렸는데 안에서 못 알아듣는다. 아무 데나 두드려 온다.<br><br>결국 바깥에서 지렛대를 찾아 열었다. 반나절이 걸렸다. 팀원 손가락 둘이 하얗게 굳었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-12, mind:-8 }, wake:1 },
    { l:'② 문틈에 쇠막대를 넣어 비튼다.', k:'fix', dc:15,
      ok:`도축장 바닥의 쇠막대를 주워 문틈에 박았다. 셋이 같이 비틀었다.<br><br>문이 한 뼘 벌어진다. 찬 김이 쏟아진다. 팀원 손이 틈으로 나왔다. 끌어냈다.`,
      ng:`비트는데 막대가 휘었다. 두 번째 막대는 부러졌다.<br><br>부러진 끝이 이쪽 팔을 그었다. 셋째 막대에 문이 열렸다. 오래 걸렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-6 } },
    { l:'③ 같은 박자로 계속 두드려 잠들지 않게 한다.', k:'steady', dc:14,
      ok:`팀원들이 다른 길을 찾는 동안 문 앞에 앉아 두드렸다. 셋, 쉼, 셋.<br><br>안에서 같은 박자로 대답한다. 대답이 느려지면 세게 두드렸다. 그러면 다시 빨라졌다.<br>한 시간 뒤에 팀원들이 환기구를 뜯었다. 안의 팀원은 끝까지 대답했다.`,
      ng:`두드리다 이쪽 손이 얼었다. 쇠문은 바깥도 차다.<br><br>박자가 끊긴 사이 안의 대답도 끊겼다. 환기구를 뜯었을 때 팀원은 웅크린 채 졸고 있었다. 깨우는 데 한참 걸렸다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-10, mind:-8 } }
  ] },

{ at:'C2', t:'천장 실 — 반 박자 먼저 오는 떨림',
  x:`공방 천장에서 실이 수백 내려온다. 끝마다 인형.<br><br>
    실이 떤다. 위에서 손가락이 움직일 때마다. 줄 신호를 아는 사람에게 줄은 당기는 쪽의 말을 나른다.<br>
    이 실들도 나른다. 위층의 말을. 인형들에게.<br><br>
    실 하나가 떤다. 짧게 셋. 그 실 끝 인형이 고개를 든다. 이쪽 팀을 본다.`,
  o:[
    { l:'① 실 떨림을 읽어 인형이 받는 말을 먼저 안다.', k:'gaze', dc:15,
      ok:`실 몇 가닥에 손가락을 얹었다. 떨림을 받았다. 짧게 셋은 봐. 길게 하나는 가. 짧게 하나 길게 하나는 물어.<br><br>인형들이 움직이기 전에 실이 먼저 떤다. 반 박자 먼저. 그 반 박자면 피한다.<br>다섯에게 손짓으로 알렸다. 실이 물어를 할 때마다 이쪽이 멈춰를 했다. 인형들 이가 번번이 허공을 물었다.<br><br>남의 줄을 듣고 남의 명령을 먼저 알았다. 듣기만 했는데 앞섰다. 반 박자 먼저 듣는 귀가 생겼다.`,
      ng:`손가락을 얹었는데 떨림이 손가락으로 건너온다. 이쪽 손이 짧게 셋 떤다.<br><br>팀원들이 그 손을 신호로 봤다. 나를 봐. 다들 이쪽을 봤다. 인형들도 이쪽을 봤다. 동시에 왔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-14, mind:-8 }, wake:1 },
    { l:'② 실 사이를 손짓으로 하나씩 이끈다.', k:'bond', dc:14,
      ok:`실이 덜 떨리는 데만 골라 손짓했다. 왼쪽. 멈춰. 아래. 가.<br><br>다섯이 실 사이를 지났다. 한 사람도 실에 안 닿았다. 실에 닿으면 위에서 안다.<br>지나고 나서 돌아보니 실들이 이쪽이 지나간 길만 비워 두고 떨고 있었다.`,
      ng:`셋째에게 아래를 했는데 셋째가 아래를 보다 실에 이마를 댔다.<br><br>위층에서 손가락 하나가 멈췄다. 그 실 끝 인형이 셋째 쪽으로 떨어져 왔다. 이가 귀를 스쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-8 } }
  ] },

{ at:'C2', t:'태엽 인형 — 똑딱 수',
  x:`바닥에 태엽 인형들이 서 있다. 등마다 열쇠가 돈다. 돌 때마다 똑딱.<br><br>
    똑딱이 멈추면 인형이 움직인다. 열쇠가 다 풀린 것이다. 다시 감기 전까지.<br>
    똑딱을 셌다. 인형마다 다르다. 이건 백. 저건 서른. 저건 아홉.<br><br>
    아홉짜리가 거의 다 풀렸다. 팀원 바로 옆이다.`,
  o:[
    { l:'① 남은 똑딱 수를 손가락으로 알려 순서대로 지나가게 한다.', k:'bond', dc:14,
      ok:`인형마다 손가락으로 남은 수를 보였다. 아홉짜리는 주먹. 지금. 서른짜리는 손가락 셋. 조금 뒤. 백짜리는 손바닥. 아직.<br><br>팀원들이 주먹 쪽부터 피했다. 아홉짜리가 움직였을 때 거기 아무도 없었다. 인형이 허공을 물고 굴렀다.<br>손바닥 쪽을 마지막으로 지났다. 아직이었다.`,
      ng:`서른짜리를 잘못 셌다. 스물이었다.<br><br>손가락 셋을 본 팀원이 느긋하게 지나가다 물렸다. 발목에 작은 이가 줄지어 박혔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } },
    { l:'② 아홉짜리 열쇠를 이쪽이 감아 준다.', k:'fix', dc:15,
      ok:`다가가 열쇠를 쥐었다. 감았다. 똑딱이 다시 많아진다. 인형이 선 채 그대로다.<br><br>그런데 인형 고개가 이쪽으로 돈다. 감아 준 쪽을 본다.<br>지나가는 동안 그 인형만 이쪽을 따라 고개를 돌렸다. 감는 사람을 기다리는 것들이다. 이쪽을 감는 사람으로 기억했다.`,
      ng:`쥐는 순간 똑딱이 멈췄다. 아홉이 끝났다.<br><br>인형이 열쇠 쥔 이쪽 손을 물었다. 사기 턱이 손등에 박혔다. 깨뜨려서 떼어 냈다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C2', t:'진열장 — 처음 보는 손짓',
  x:`진열장 인형들이 손을 든다. 팀원들이 손짓할 때마다.<br><br>
    멈춰를 하면 인형들도 멈춰를 한다. 가를 하면 가. 사기 손가락이 딱딱 소리를 낸다.<br>
    팀원 하나가 장난처럼 나를 봐를 했다. 진열장 전체가 그 사람을 봤다. 그리고 손을 내렸다. 한 인형만 손을 안 내렸다.<br><br>
    그 인형이 이리 오라는 손짓을 한다. 이쪽 팀이 안 쓰는 손짓이다.`,
  o:[
    { l:'① 처음 보는 손짓을 되받아 뜻을 묻는다.', k:'bond', dc:15,
      doom:{ title:'이리 와', what:'인형의 손짓을 따라 진열장 안으로 끌려갑니다', dc:15, sec:55,
        text:`손바닥을 위로 펴서 되받았다. 무슨 뜻이냐고.<br><br>인형이 같은 손짓을 한다. 손바닥 위로. 그리고 다시 이리 와.<br>되받은 순간 이쪽이 진열장의 손짓을 배운 셈이 됐다. 배운 손짓은 따라 하게 된다. 발이 진열장 쪽으로 간다.<br><br>유리문이 열려 있다. 안에 빈자리가 하나.`,
        dieText:`진열장 빈자리가 찼다.<br><br>새 인형은 손을 들고 있다. 손짓을 보내는 모양으로.<br>지나가는 팀에게 신호를 보낸다. 정확하게. 버릇까지.` },
      ok:`손바닥을 위로 펴서 되받았다. 무슨 뜻이냐고.<br><br>인형이 한참 손을 멈춘다. 그리고 다른 손짓을 한다. 진열장 뒤를 가리킨다. 아래를. 아래는 이쪽 손짓이다. 배웠다.<br>진열장 뒤 바닥에 쪽문이 있다. 계단 대신 쓰던 사다리 구멍이다.<br><br>인형은 손을 내렸다. 이쪽은 손짓 하나를 줬고 하나를 받았다. 신호를 주고받는 건 사람끼리만은 아니었다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 손짓을 다 멈추게 하고 귓속말로 바꾼다.', k:'steady', dc:14,
      ok:`팀원들 손을 내리게 했다. 귓속말로 하나씩 전했다. 진열장 앞에서는 손을 쓰지 말자고.<br><br>인형들 손이 하나씩 내려간다. 따라 할 게 없다. 이리 오라던 인형도 손을 내렸다.<br>손짓 없는 신호수는 처음이었다. 이상하게 조용했다.`,
      ng:`귓속말을 하는데 인형들 입이 움직인다. 소리 없이.<br><br>입 모양을 따라 한다. 이쪽 말을. 다들 입을 막고 뛰었다. 진열장 안에서 사기 이가 딱딱 맞부딪쳤다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-10, spirit:-8 } }
  ] },

{ at:'C3', t:'둥근 천장 — 도는 소리',
  x:`뒤집힌 성당에서 소리는 이상하게 간다. 위로 올라가야 할 것이 발밑 둥근 천장에 고인다.<br><br>
    호루라기를 불면 소리가 둥근 천장을 타고 빙 돈다. 한 바퀴 돌아 이쪽 뒤통수로 온다.<br>
    팀원들이 흩어져 종 같은 것들을 잡는 중이다. 모이라는 신호를 보내야 한다.<br><br>
    종 같은 것들은 소리를 먹는다. 소리가 닿으면 아가리를 연다.`,
  o:[
    { l:'① 갈빗대가 모이는 한가운데서 아주 작게 분다.', k:'sense', dc:15,
      ok:`둥근 천장 갈빗대가 꽃잎처럼 모이는 데를 찾았다. 소리가 다 그리로 모인다. 거기서 불면 다 그리로 간다.<br><br>아주 작게 불었다. 숨만큼. 소리가 갈빗대를 타고 다섯 쪽으로 고르게 퍼졌다. 크지 않아서 종들은 못 먹었다.<br>팀원들이 하나씩 모였다. 다들 귀 바로 옆에서 들었다고 했다.`,
      ng:`한가운데인 줄 알았는데 반 걸음 비켜 있었다.<br><br>소리가 한쪽으로 쏠렸다. 종 하나 아가리 안으로. 종이 울었다. 성당 전체가 따라 울었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-12, spirit:-10 } },
    { l:'② 소리 대신 등불을 금박 갈빗대에 비춘다.', k:'bond', dc:14,
      ok:`등불 덮개를 열고 둥근 천장 금박에 비췄다. 빛이 갈빗대를 타고 미끄러진다.<br><br>흩어진 팀원들 발밑으로 빛이 지나간다. 빛이 오는 쪽을 보면 이쪽이 있다.<br>하나씩 빛을 거슬러 왔다. 종들은 빛은 안 먹었다.`,
      ng:`빛이 금박에 튕겨 머리 위 의자들 쪽으로 갔다.<br><br>의자 사이에 매달린 것들이 빛을 봤다. 하나가 위로 떨어지던 걸 멈추고 이쪽으로 떨어져 내려왔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C3', t:'골 바닥 — 뒤집힌 아래',
  x:`뒤집힌 성당에서 위와 아래가 헷갈린다.<br><br>
    신호수가 아래를 했다. 손바닥을 땅으로. 팀원 둘은 발밑 둥근 천장을 봤다. 하나는 머리 위 원래 바닥을 봤다. 원래 아래였던 쪽.<br>
    셋째가 원래 아래로 가려다 발이 떴다. 겨우 잡았다.<br><br>
    손짓은 세상을 기준으로 만든 것이다. 여기서는 세상이 뒤집혔다.`,
  o:[
    { l:'① 발바닥이 닿은 쪽을 아래로 손짓 기준을 바꾼다.', k:'bond', dc:14,
      ok:`다섯을 모았다. 발을 굴렀다. 여기가 아래다. 손바닥을 이쪽 발바닥에 댔다. 이게 아래다.<br><br>그다음부터 아래는 손바닥을 땅에 대지 않고 발바닥에 댔다. 땅이 어디든 발이 아래다.<br>그 뒤로 아무도 헷갈리지 않았다. 둥근 천장 끝까지 다섯이 한 방향을 봤다.<br><br>손짓이 가리키는 쪽을 세상이 아니라 몸에 묶었다. 세상이 뒤집혀도 안 뒤집히는 신호. 손이 신호를 새로 짓는 법을 하나 더 익혔다.`,
      ng:`발을 구르는데 그 소리에 종 같은 것 하나가 아가리를 연다.<br><br>정하기 전에 흩어졌다. 셋째가 또 떴다. 이번엔 둘이 붙잡았다. 둘 다 무릎이 까졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-12, mind:-8 }, wake:1 },
    { l:'② 다 같이 손을 잡고 한 줄로 이끈다.', k:'steady', dc:14,
      ok:`손짓을 그만뒀다. 다섯이 손을 잡았다. 맨 앞이 이쪽.<br><br>이쪽이 디디는 데를 뒷사람이 디딘다. 위가 어디든 아래가 어디든 앞사람 손이 기준이다.<br>골 끝까지 갔다. 손바닥이 땀에 젖었다. 아무도 안 놓았다.`,
      ng:`셋째 손이 땀에 미끄러졌다. 셋째가 떴다.<br><br>넷째가 셋째 발목을 잡았다. 둘이 같이 떴다. 나머지가 둘을 끌어내렸다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C3', t:'성가대 아래 — 숨 쉬는 틈',
  x:`성가대가 노래한다. 입이 많은 것들. 박자가 빈틈없다.<br><br>
    노래가 크면 호루라기도 손뼉도 안 들린다. 팀원들이 이쪽을 본다. 신호를 기다린다. 노래 너머로 무언가 기어 오는 소리가 난다.<br>
    빈틈없는 박자에도 숨 쉬는 자리가 있다. 입이 여럿이면 숨도 여럿이다. 다 같이 쉬는 때가 한 번은 온다.<br><br>
    그 한 번에 신호를 넣어야 한다.`,
  o:[
    { l:'① 성가대가 다 같이 숨 쉬는 틈에 호루라기를 분다.', k:'sense', dc:15,
      doom:{ title:'성가대의 숨', what:'성가대석으로 끌려 올라갑니다', dc:15, sec:55,
        text:`숨 쉬는 틈을 기다렸다. 왔다. 불었다.<br><br>호루라기가 빈 데를 채웠다. 성가대가 그걸 들었다. 노래가 멈추지 않는다. 호루라기 소리를 노래에 넣는다. 입 하나가 이쪽 소리를 낸다.<br>빈 성부가 찼다. 호루라기 성부. 그 성부는 원래 이쪽 것이다.<br><br>손바닥 입들이 이쪽을 향한다. 성가대석이 머리 위에서 내려온다.`,
        dieText:`성가대에 성부가 하나 늘었다.<br><br>노래 중간마다 호루라기 소리가 난다. 짧게. 정확하게.<br>숨 쉬는 틈마다 한 번. 아무도 그 신호를 받으러 오지 않는다.` },
      ok:`틈이 왔다. 불었다. 짧게 하나. 빈 데에 딱 들어갔다.<br><br>성가대는 다음 숨을 쉬느라 못 들었다. 팀원들은 들었다. 모였다. 기어 오던 것이 놓친 자리를 더듬었다.<br>노래가 다시 차올랐을 때 다섯은 문 앞에 있었다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 노래 박자에 맞춰 발을 구르며 걸음을 맞춘다.', k:'bond', dc:14,
      ok:`노래를 거스르지 않았다. 노래 박자를 신호로 썼다. 셋째 박마다 한 걸음. 발로 쿵.<br><br>팀원들이 발 구르는 걸 보고 따라 했다. 노래가 크니 발소리가 묻힌다. 다섯이 같은 박에 걸었다.<br>남의 박자를 빌려 쓰면 남이 이쪽 박자를 못 알아챈다.`,
      ng:`성가대가 박자를 바꿨다. 셋에서 넷으로. 일부러.<br><br>다섯 걸음이 어긋났다. 하나가 넘어졌다. 기어 오던 것이 넘어진 쪽에 먼저 닿았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C4', t:'포자 안개 — 쇠틀',
  x:`온실에 포자가 안개처럼 찼다. 손을 뻗으면 손끝이 안 보인다.<br><br>
    등불은 안개에 먹힌다. 호루라기는 포자를 마시게 한다. 불려면 숨을 들이쉬어야 하니까.<br>
    팀원 다섯이 흩어졌다. 서로 안 보인다.<br><br>
    온실 벽은 유리다. 쇠틀에 유리판이 수백 장. 다 이어져 있다.`,
  o:[
    { l:'① 쇠틀을 두드려 울림으로 부른다.', k:'bond', dc:14,
      ok:`칼자루로 쇠틀을 쳤다. 셋, 쉼, 셋. 쇠는 이어져 있다. 울림이 온실 벽을 다 돈다.<br><br>유리에 손을 짚고 있던 팀원들이 손바닥으로 들었다. 울림이 센 쪽으로 왔다.<br>다섯이 모였다. 숨을 한 번도 크게 안 쉬었다.`,
      ng:`쳤는데 쇠틀이 삭았다. 유리판 하나가 빠져 떨어졌다.<br><br>깨진 소리에 안개 속 무언가 고개를 들었다. 팀원들보다 먼저 왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } },
    { l:'② 바닥 균사에 칼로 줄을 그어 길을 남긴다.', k:'fix', dc:14,
      ok:`칼끝으로 바닥 균사를 그었다. 하얀 바닥에 검은 줄이 난다.<br><br>안개 속에서 발밑은 보인다. 팀원들이 검은 줄을 밟고 따라왔다. 줄 끝에 이쪽이 앉아 있었다.`,
      ng:`그은 줄이 금방 메워진다. 균사가 다시 핀다.<br><br>줄은 반쯤 남았다. 둘은 찾아왔다. 셋은 반나절 걸렸다. 그동안 포자를 많이 마셨다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-10, spirit:-8 } },
    { l:'③ 젖은 천으로 입을 막고 호루라기를 짧게 분다.', k:'luck', dc:15,
      ok:`천을 두 겹 적셔 입을 막았다. 그 틈으로 짧게 하나만 불었다.<br><br>소리가 안개를 뚫고 간다. 팀원들이 왔다. 천은 하얗게 물들었다. 버렸다.`,
      ng:`불려고 숨을 들이켰다. 천이 덜 젖어 있었다.<br><br>포자가 목구멍에 앉았다. 소리 대신 기침이 났다. 기침을 듣고 온 건 팀원이 아니었다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-12, mind:-8 } }
  ] },

{ at:'C4', t:'온실 저편 — 일꾼 부르는 호루라기',
  x:`온실 저편에서 호루라기 소리가 난다. 길게 하나, 짧게 둘.<br><br>
    작업복 입은 것들이 그 소리를 듣고 모인다. 일꾼 부르는 소리다. 옛날 정원사들이 쓰던.<br>
    소리를 들으면 분 사람을 안다. 이건 사람이 분 게 아니다. 숨이 너무 고르다.<br><br>
    소리 나는 쪽에 큰 것이 있다. 모인 것들이 그 앞에 줄을 선다.`,
  o:[
    { l:'① 같은 신호를 반대편에서 불어 하나씩 불러내 잡는다.', k:'bond', dc:15,
      ok:`좁은 통로 끝에 섰다. 팀원들을 양옆에 숨겼다. 길게 하나, 짧게 둘.<br><br>줄 서던 것 중 하나가 고개를 돌린다. 이쪽으로 온다. 일꾼은 부르면 온다. 통로에 들어서자 양옆에서 창이 갔다.<br>또 불었다. 또 왔다. 다섯을 그렇게 잡았다. 저편 큰 것 앞 줄이 짧아졌다.`,
      ng:`불었는데 박자가 조금 빨랐다. 사람 숨이다.<br><br>작업복들이 한꺼번에 고개를 돌렸다. 하나가 아니라 줄 전체가 왔다. 좁은 통로로.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-8 } },
    { l:'② 신호가 끝나는 때를 기다려 반대로 간다.', k:'sense', dc:14,
      ok:`신호가 끝나면 작업복들이 줄을 선다. 줄 선 동안은 안 돌아다닌다.<br><br>그 동안 반대쪽 통로로 갔다. 아무것도 안 마주쳤다. 다 줄 서 있었다.`,
      ng:`신호가 끝났는데 하나가 줄에 안 섰다. 늦게 온 것이다.<br><br>통로에서 마주쳤다. 모자 아래 버섯이 이쪽을 봤다. 포자가 터졌다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-12, spirit:-8 } }
  ] },

{ at:'C4', t:'유리벽 너머 — 다른 팀',
  x:`옆 칸에 다른 팀이 갇혔다. 유리벽 하나 건너. 문이 균사로 막혔다.<br><br>
    그쪽은 이쪽이 보인다. 이쪽도 그쪽이 보인다. 소리는 안 통한다. 유리가 두껍다.<br>
    그쪽 반장이 무언가 손짓한다. 이쪽은 모르는 손짓이다. 다급하다.<br><br>
    그쪽 칸 천장에서 무언가 내려오고 있다. 그쪽은 못 본다. 이쪽에서만 보인다.`,
  o:[
    { l:'① 유리에 입김을 불어 글씨를 거꾸로 쓴다.', k:'fix', dc:15,
      ok:`유리에 입김을 불었다. 하얗게 흐려진 데에 손가락으로 썼다. 그쪽에서 바로 읽히게 거꾸로. 위.<br><br>그쪽 반장이 읽었다. 위를 봤다. 다들 엎드렸다. 내려오던 것이 빈 데에 떨어졌다.<br>그쪽이 창을 들었다. 이쪽은 유리 너머에서 손뼉만 쳤다. 소리는 안 갔다.`,
      ng:`입김을 부는데 유리가 차서 금방 맑아진다.<br><br>글씨가 반만 남았다. 그쪽이 못 읽었다. 내려온 것이 그쪽 하나를 덮었다. 유리 너머라 아무것도 못 했다.`,
      win:{ exp:18, dream:2 }, lose:{ spirit:-12, mind:-6 } },
    { l:'② 그쪽 손짓을 배워 그쪽 말로 대답한다.', k:'bond', dc:15,
      ok:`그쪽 반장 손짓을 봤다. 아까부터 되풀이하는 것 중에 하나. 손가락 셋을 위로 펴는 것. 그걸 할 때 반장 눈이 잠깐 위를 봤다.<br><br>그쪽 말로 위일 것이다. 그걸 그대로 크게 했다. 세 번.<br>그쪽 반장이 위를 봤다. 다들 엎드렸다. 내려오던 것이 빈 데에 떨어졌다.<br><br>남의 말을 배워 남의 말로 대답했다. 신호는 이쪽 것만 있는 게 아니었다. 남의 신호를 빌려 쓰는 귀와 손이 생겼다.`,
      ng:`손가락 셋을 위로 폈는데 그쪽 말로는 그게 셋이라는 뜻이었다.<br><br>그쪽이 셋을 세기 시작했다. 셋에 내려온 것이 닿았다. 그쪽 하나가 깔렸다.`,
      win:{ exp:24, dream:3 }, lose:{ spirit:-12, mind:-8 }, wake:1 },
    { l:'③ 유리를 깨서 직접 소리친다.', k:'break', dc:15,
      ok:`칼자루로 유리를 쳤다. 세 번에 깨졌다. 소리쳤다. 위!<br><br>그쪽이 엎드렸다. 깨진 틈으로 그쪽 칸 포자가 넘어왔다. 이쪽 다섯이 같이 기침했다. 살렸다.`,
      ng:`유리가 안 깨진다. 두 겹이다.<br><br>치는 소리에 그쪽 천장의 것이 이쪽을 봤다. 유리를 타고 이쪽 칸으로 넘어올 길을 찾기 시작했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-6 } }
  ] }

]);

// ──────────────────────────────────────────
// 표사 (escort) · 내공
// ──────────────────────────────────────────
kJob('escort', 'C', [

{ at:'C', t:'사냥 뒤 — 움찔하는 짐',
  x:`놈을 잡았다. 크다. 가죽과 이빨은 값이 나간다. 위로 가져가면.<br><br>
    다섯이 나눠 지기엔 다섯 다 다쳤다. 이쪽이 진다. 짐 지는 게 이쪽 일이다.<br>
    놈은 죽었다. 그런데 등에 지니 가끔 근육이 움찔한다. 죽은 것의 근육은 한동안 제멋대로 논다.<br><br>
    짐이 제멋대로 움직이는 건 질색이다.`,
  o:[
    { l:'① 내공으로 허리를 받치고 끝까지 진다.', k:'steady', dc:15, cost:{ qi:18 },
      ok:`내공을 허리로 내렸다. 졌다. 무겁다. 걸었다.<br><br>계단 셋을 오르는 동안 짐이 두 번 움찔했다. 두 번 다 등으로 눌렀다. 이쪽 등 위에서는 짐은 짐이다.<br>쉬는 자리에 내려놓았다. 이빨 하나가 이쪽 어깨에 박혀 있었다. 움찔할 때 박힌 것이다. 아무도 몰랐다. 이쪽도.`,
      ng:`오르다 짐이 크게 움찔했다. 아니, 숨을 쉬었다. 덜 죽었다.<br><br>등에서 몸을 튼다. 이쪽 목덜미를 문다. 내던졌다. 팀원들이 마저 잡았다. 목덜미가 화끈하다.`,
      win:{ exp:22, dream:3, item:'짐승 고기' }, lose:{ hp:-16, mind:-6 } },
    { l:'② 값나가는 것만 떼어 가볍게 꾸린다.', k:'gaze', dc:14,
      ok:`이빨, 발톱, 가죽 한 장. 고기는 먹을 만큼만. 나머지는 둔다.<br><br>짐이 반의반이 됐다. 값은 반만 줄었다. 표사는 짐 꾸리는 법부터 배운다. 무게로 꾸리지 않고 값으로 꾸린다.`,
      ng:`이빨을 뽑는데 턱이 닫혔다. 죽은 턱이다. 그래도 닫혔다.<br><br>손가락 둘이 끼었다. 칼로 턱을 벌려 뺐다.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ hp:-12, spirit:-6 } }
  ] },

{ at:'C', t:'굴 사이 길 — 표호',
  x:`놈들 굴 사이로 난 길이다. 양옆 구멍마다 눈이 있다.<br><br>
    표사는 길에 들어서면 외친다. 지키는 사람이 붙은 짐이 지나간다고. 건드리면 손해라고.<br>
    산적은 알아듣는다. 놈들은 산적이 아니다.<br><br>
    그래도 외칠 때 실리는 기세는 산적이든 놈이든 똑같이 닿는다.`,
  o:[
    { l:'① 내공을 실어 크게 외치고 다섯을 한 줄로 세운다.', k:'bond', dc:15, cost:{ qi:18 },
      ok:`단전에서 끌어올려 외쳤다. 다섯을 등 뒤에 한 줄로 세웠다. 어깨가 붙게.<br><br>구멍 속 눈들이 하나씩 물러난다. 하나만 안 물러난다. 크다. 기어 나와 이쪽을 본다. 그리고 이쪽 뒤를 본다. 한 줄로 선 다섯을.<br>그것도 물러났다.<br><br>표호는 소리로 먹히는 게 아니었다. 뒤에 선 사람 수로 먹혔다.`,
      ng:`외쳤는데 소리가 굴에 빨려 들어갔다. 메아리가 안 돌아온다.<br><br>대신 구멍마다 무언가 나왔다. 소리 나는 쪽으로. 한 줄로 선 다섯이 한 줄로 물렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-14, spirit:-8 } },
    { l:'② 외치지 않고 숨죽여 지나간다.', k:'hide', dc:14,
      ok:`외치지 않았다. 외치지 않을 때도 안다.<br><br>숨죽인 눈들과 숨죽인 다섯이 서로 모른 척 지나갔다.<br>마지막 구멍 앞에서 무언가 한 번 크게 숨을 들이쉬었다. 아무도 안 돌아봤다.`,
      ng:`숨죽여 가는데 팀원 하나가 미끄러졌다.<br><br>구멍 속 것들이 동시에 나왔다. 외쳤으면 안 나왔을 것이다. 다들 뛰었다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C', t:'다리 물린 반장 — 인표',
  x:`다른 팀 하나가 이쪽을 부른다. 그쪽 반장이 다리를 크게 물렸다. 못 걷는다.<br><br>
    <span style="color:#d4af37;">"표사 아니오? 우리 반장을 계단까지 데려다주시오. 앞은 우리가 치우겠소."</span><br>
    사람을 짐으로 받는 것. 인표. 제일 귀한 짐이고 제일 무거운 짐이다.<br><br>
    반장 다리에서 냄새가 난다. 놈들은 그 냄새를 따라온다.`,
  o:[
    { l:'① 인표를 받고 두 팀에 앞과 옆을 나눠 맡긴다.', k:'bond', dc:15,
      ok:`받았다. 반장을 업었다. 그쪽 넷에게 앞을 맡겼다. 이쪽 넷에게 옆을. 이쪽은 가운데.<br><br>냄새를 따라 놈들이 왔다. 앞에서 그쪽 넷이 막았다. 옆에서 이쪽 넷이 막았다. 가운데는 아무것도 안 닿았다.<br>계단에 닿았다. 반장을 내려놓았다. 반장이 두 팀을 번갈아 본다. 아홉이 짐 하나를 둘러쌌다.<br><br>짐 하나를 두 팀이 같이 지켰다. 지키는 자리를 남에게 나눠 주는 법을 처음 써 봤다. 혼자 지는 짐보다 무거웠다. 그리고 덜 무거웠다.`,
      ng:`업고 일어서자 다리 냄새가 확 퍼졌다.<br><br>놈들이 앞이 아니라 옆에서 왔다. 그쪽 넷은 앞만 봤다. 업은 채로 옆을 받았다. 허벅지를 물렸다. 반장은 안 다쳤다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-6 }, wake:1 },
    { l:'② 받기 전에 다리부터 묶어 냄새를 막는다.', k:'heal', dc:14,
      ok:`짐은 받기 전에 다시 꾸린다. 다리를 물로 씻고 약초를 찧어 붙였다. 천으로 두껍게 감았다.<br><br>냄새가 줄었다. 업었다. 계단까지 놈 하나 안 따라왔다.<br>그쪽 팀이 앞을 치우느라 다친 게 더 많았다. 업힌 반장이 제일 멀쩡했다.`,
      ng:`씻는데 상처에서 냄새가 더 퍼졌다. 물이 냄새를 실어 날랐다.<br><br>감기도 전에 놈들이 왔다. 다리를 벌린 채로 반장을 업고 뛰었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } }
  ] },

{ at:'C', t:'낮은 천장 — 매복 자리',
  x:`통로 천장이 낮아진다. 위에 구멍이 줄지어 났다. 구멍 가장자리가 반들반들하다. 무언가 자주 드나든다.<br><br>
    이런 데는 안다. 산길 협곡과 같다. 위에서 떨어지는 곳.<br>
    매복은 짐을 노린다. 제일 느린 것. 제일 다친 것.<br><br>
    팀에서 제일 다친 사람은 넷째다. 맨 뒤에 있다.`,
  o:[
    { l:'① 넷째를 가운데 두고 넷이 둘러싸 간다.', k:'bond', dc:14,
      ok:`넷째를 가운데 세웠다. 넷이 둘러쌌다. 이쪽은 맨 앞.<br><br>구멍에서 무언가 떨어졌다. 둘러싼 어깨에 맞았다. 가운데는 멀쩡하다.<br>둘째 구멍, 셋째 구멍. 다 어깨로 받았다. 산길 방식은 땅 밑에서도 통한다.`,
      ng:`둘러싸는데 발이 엉킨다. 다섯이 같이 넘어졌다.<br><br>넘어진 위로 구멍 셋에서 한꺼번에 떨어졌다. 가운데까지 닿았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } },
    { l:'② 내공을 귀로 모아 구멍마다 기척을 듣는다.', k:'sense', dc:15, cost:{ qi:15 },
      ok:`숨을 고르고 내공을 귀로 모았다.<br><br>구멍 열 중 셋에서 숨소리가 난다. 그 셋 아래는 뛰어 지나가고 나머지 아래는 걸었다.<br>셋째 구멍 아래를 뛸 때 무언가 떨어졌다. 아무도 없는 자리에.`,
      ng:`모은 내공이 흩어졌다. 귀가 웅웅거린다.<br><br>아무것도 못 들었다. 지나가는데 넷째 머리 위로 떨어졌다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-12, mind:-8 } },
    { l:'③ 구멍마다 고기 한 점씩 던져 넣고 지나간다.', k:'luck', dc:14,
      ok:`말린 고기를 잘게 찢어 구멍마다 던져 올렸다.<br><br>구멍 속에서 씹는 소리가 난다. 씹는 동안은 안 떨어진다.<br>길값이다. 산적이나 놈이나 받으면 길을 낸다.`,
      ng:`던진 고기가 구멍에 안 들어가고 도로 떨어졌다. 넷째 머리 위로.<br><br>고기를 따라 무언가 같이 떨어졌다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-14, mind:-4 } }
  ] },

{ at:'C', t:'들어가기 전 — 다섯 짐',
  x:`사냥에 들어가기 전에 짐을 다시 꾸린다. 창, 밧줄, 횃불. 고기, 물, 약초.<br><br>
    다 들고 가면 느리다. 느리면 놈이 먼저 본다. 덜 들고 가면 모자란다. 모자라면 돌아와야 한다.<br>
    팀원들이 각자 짐을 앞에 놓았다. 다들 자기 것은 다 필요하다고 한다.<br><br>
    표사는 짐을 보면 그 짐으로 며칠 가는지 안다.`,
  o:[
    { l:'① 다섯 짐을 하나로 풀어 일대로 다시 나눈다.', k:'fix', dc:15,
      ok:`다섯 짐을 다 풀어 한데 쌓았다. 누구 것인지 지웠다. 그리고 다시 나눴다. 사람마다 맡을 일대로.<br><br>앞에 서는 사람은 창과 횃불만. 맨 뒤는 물과 약초. 가운데 둘이 고기와 밧줄. 이쪽은 나머지.<br>사냥 중에 아무도 남의 짐을 찾지 않았다. 필요한 게 필요한 사람 등에 있었다.<br><br>짐을 무게로 나누지 않고 일로 나눴다. 짐이 사람을 따라가게 했다. 꾸리는 손이 한 사람 짐에서 다섯 사람 짐으로 넓어졌다.`,
      ng:`다 풀었는데 다시 나누기 전에 놈 소리가 났다.<br><br>다들 아무거나 쥐고 일어섰다. 창 들 사람이 약초를 쥐고 약초 들 사람이 창을 쥐었다. 엉망으로 싸웠다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-14, mind:-8 }, wake:1 },
    { l:'② 이쪽 짐을 비우고 남의 것을 나눠 진다.', k:'steady', dc:14,
      ok:`이쪽 짐을 다 비웠다. 다섯 짐에서 무거운 것만 덜어 이쪽이 졌다.<br><br>넷이 가벼워졌다. 이쪽만 무겁다. 사냥 내내 넷이 빨랐다. 놈이 빠른 넷을 쫓다 지쳤다.<br>무거운 이쪽은 맨 뒤에서 천천히 따라갔다. 놈은 천천히 오는 것엔 관심이 없었다.`,
      ng:`다 지니 허리가 휘었다.<br><br>놈이 그 느린 걸 먼저 봤다. 무거운 짐을 진 채로 받았다. 넘어졌다. 짐 밑에 깔렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-16, spirit:-4 } }
  ] },

{ at:'C', t:'쉬는 자리 — 좁아지는 원',
  x:`쉬는 자리. 사냥한 놈 냄새가 옷에 배었다. 다른 놈들이 그 냄새를 맡는다.<br><br>
    밤에는 안 잔다. 산길에서는 밤에 짐이 제일 많이 없어졌다. 여기서 짐은 잠든 넷이다.<br>
    불빛 바깥으로 무언가 돈다. 원을 그린다. 원이 조금씩 좁아진다.<br><br>
    원 안에 넷이 잔다.`,
  o:[
    { l:'① 내공을 넓게 펴 원을 그리는 것을 센다.', k:'sense', dc:15, cost:{ qi:15 },
      ok:`눈을 감고 내공을 몸 밖으로 폈다. 원을 따라.<br><br>하나가 아니다. 셋이 번갈아 돈다. 하나가 돌면 둘이 쉰다. 쉬는 둘은 같은 자리에 있다. 불 뒤쪽.<br>횃불을 들고 불 뒤로 갔다. 쉬던 둘이 놀라 흩어졌다. 도는 하나만 남았다. 하나는 원을 못 좁힌다.`,
      ng:`펴던 내공이 셋째 기척에서 끊겼다.<br><br>그 사이 원이 확 좁아졌다. 잠든 하나의 발목을 무언가 물고 당겼다. 횃불로 쳐서 떼어 냈다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-14, mind:-6 } },
    { l:'② 불을 하나 더 피워 원 밖에 둔다.', k:'fix', dc:14,
      ok:`장작을 나눠 원 바깥에 불을 하나 더 피웠다.<br><br>도는 것이 두 불 사이에서 망설인다. 불 둘이면 원을 어디로 그려야 할지 모른다.<br>밤새 두 불 사이를 오갔다. 넷 쪽으로는 안 왔다.`,
      ng:`장작이 모자랐다. 두 불이 다 작아졌다.<br><br>작은 불 둘은 큰 불 하나만 못하다. 원이 두 불을 다 넘어 들어왔다.`,
      win:{ exp:15, dream:2, hp:5 }, lose:{ hp:-12, mind:-6 } },
    { l:'③ 원이 좁아질 때마다 한 걸음씩 나가 선다.', k:'steady', dc:15,
      ok:`원이 한 뼘 좁아지면 한 걸음 나가 섰다. 칼을 원 쪽으로 겨누고.<br><br>도는 것이 이쪽 앞에서 원을 다시 넓힌다. 서 있는 것 앞에서는 못 좁힌다. 밤새 나갔다 들어왔다 했다.<br>새벽에 원 자국이 바닥에 남았다. 넷이 잔 자리보다 훨씬 넓었다.<br><br>짐 곁에 붙어 지키던 버릇이 있었다. 오늘은 짐에서 떨어져 나가 지켰다. 지키는 자리가 짐 둘레보다 넓을 수 있다는 걸 발이 먼저 알았다.`,
      ng:`세 번째 나갔을 때 등 뒤로 다른 하나가 돌아 들어왔다.<br><br>원이 둘이었다. 돌아서 넷 쪽으로 뛰었다. 하나가 팔을 긁혔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-12, spirit:-8 }, wake:1 }
  ] },

{ at:'C', t:'굴 앞 — 봉인 찍힌 상자',
  x:`굴 앞으로 놈이 무언가를 끌고 간다. 상자다. 봉인이 찍혔다. 표국 봉인이다.<br><br>
    봉인은 안 뜯겼다. 놈이 이빨로 손잡이를 물고 끈다. 상자 안에서 무언가 달그락거린다.<br>
    표물을 놓친 표사가 어딘가 있었다. 지금은 없다.<br><br>
    봉인 안 뜯긴 표물은 아직 안 끝난 짐이다.`,
  o:[
    { l:'① 놈을 쳐서 표물을 되찾는다.', k:'break', dc:15,
      ok:`달려가 놈 옆구리를 쳤다. 팀원들이 따라 쳤다. 놈이 상자를 놓았다. 쓰러졌다.<br><br>상자를 일으켰다. 봉인은 안 뜯었다. 남의 표물이다. 봉인 아래 받을 사람 이름이 있다. 위쪽 사람이다.<br>이쪽 짐 위에 얹었다. 올라가면 줄 것이다.`,
      ng:`치는데 놈이 상자를 방패처럼 돌렸다.<br><br>칼이 상자를 쳤다. 봉인 귀퉁이가 찢겼다. 놈은 그 틈에 이쪽 팔을 물고 놓았다. 상자는 끌고 갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, spirit:-6 } },
    { l:'② 놈을 따라가 놈이 모아 둔 데를 찾는다.', k:'hide', dc:14,
      ok:`몰래 따라갔다. 굴 안쪽 넓은 데. 상자가 쌓여 있다. 다 봉인이 찍혔다. 다 안 뜯겼다.<br><br>놈은 봉인을 좋아한다. 아니면 봉인 밀랍 냄새를. 뜯을 줄은 모른다.<br>놈이 자는 동안 맨 위 상자 하나를 들고 나왔다. 무거웠다. 남의 표물이 또 하나 늘었다.`,
      ng:`따라가다 상자 더미에 부딪혔다. 와르르 무너졌다.<br><br>놈이 깼다. 상자 사이로 쫓아왔다. 다리를 물렸다.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C', t:'잡은 놈 위 — 먼저 선 발',
  x:`이쪽 팀이 잡은 놈 위에 다른 팀이 서 있다. 숨이 끊기자마자 달려와 먼저 올라섰다.<br><br>
    사냥터에서는 먼저 손대는 쪽이 임자라고들 한다. 그쪽은 손을 안 댔다. 발을 댔다.<br>
    산길에는 표기가 있다. 짐 위에 깃발을 꽂으면 그 깃발 주인 것이다. 여기서는 잡은 놈이 짐이다.<br><br>
    그쪽 반장이 이쪽을 보고 웃는다.`,
  o:[
    { l:'① 놈 머리맡에 서서 법도대로 말한다.', k:'bond', dc:14,
      ok:`놈 머리맡에 섰다. 두 손을 모아 인사했다. 산길 법도대로.<br><br>짐 위에 선 사람이 아니라 짐 앞에 선 사람이 지키는 사람이라고 했다. 이 놈 앞에 선 건 이쪽 다섯이었다고. 피도 이쪽 것이 묻었다고.<br>그쪽 반장이 발을 내렸다. 법도를 아는 사람이었다. 다리 하나를 덜어 줬다. 와 준 값이다.<br><br>깃발이 없어도 서는 자리로 주인이 정해진다. 짐 앞에 서는 몸이 깃발이었다. 오늘은 그 몸을 세워 말로 지켰다. 손이 아니라 자리로 지키는 법이 하나 늘었다.`,
      ng:`인사하는데 그쪽이 웃는다. 법도는 산 위의 이야기라고.<br><br>그쪽이 칼을 뽑았다. 다리 하나를 두고 다퉜다. 결국 반을 빼앗겼다. 이쪽 팔도 베였다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-12, spirit:-8 }, wake:1 },
    { l:'② 내공을 끌어올려 기세로 민다.', k:'break', dc:15, cost:{ qi:18 },
      ok:`한 걸음 나섰다. 내공을 끌어올리자 바닥 핏물이 밀려난다.<br><br>그쪽 반장 웃음이 멎는다. 놈 위에서 내려선다. 싸우면 이기는 게 아니라 다친다는 걸 안다.<br>칼을 한 번도 안 뽑았다. 놈은 이쪽 것으로 남았다.`,
      ng:`기세를 올리는데 그쪽 반장이 안 물러난다.<br><br>칼이 왔다. 막았다. 팔뚝이 베였다. 놈 다리 하나를 그쪽이 들고 갔다.`,
      win:{ exp:18, dream:2, item:'짐승 고기' }, lose:{ hp:-16, spirit:-4 } }
  ] },

{ at:'C1', t:'수레 궤도 — 출하구로 가는 고기',
  x:`레일 아래에 수레 궤도가 있다. 수레에 고기가 가득하다. 수레가 저절로 굴러간다. 출하구 쪽으로.<br><br>
    출하구는 바깥이다. 고기를 내보내는 길이다. 그 길로 사람도 나갈 수 있다.<br>
    다친 둘을 수레에 태우면 된다. 고기를 덜어 내야 한다. 덜어 낸 고기는 바닥에서 다시 자라 수레로 기어오른다.<br><br>
    짐을 실었으면 지키는 것도 수레 위에서다.`,
  o:[
    { l:'① 다친 둘을 싣고 수레에 올라 기어오르는 고기를 쳐낸다.', k:'steady', dc:15, cost:{ qi:20 },
      ok:`고기를 덜어 내고 둘을 눕혔다. 이쪽은 수레 끝에 섰다. 내공을 다리에 내리고.<br><br>바닥 고기가 바퀴를 타고 기어오른다. 칼등으로 쳐냈다. 또 오른다. 또 쳐냈다.<br>출하구 셔터 앞에서 수레가 멈췄다. 둘은 멀쩡하다. 수레 끝에 고기 한 덩이 안 올라왔다.<br><br>팔이 한참 안 내려왔다.`,
      ng:`쳐내는 것보다 오르는 게 빨랐다.<br><br>고기가 누운 사람 발목까지 올라왔다. 붙었다. 칼로 떼어 냈다. 살갗이 같이 왔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-6 } },
    { l:'② 수레 옆을 걸으며 고기를 덜어 낸다.', k:'sense', dc:14,
      ok:`수레를 타지 않고 옆을 따라 걸었다. 바퀴를 타고 오르려는 고기를 손으로 걷어 냈다.<br><br>수레 위 고기 중 안 자라는 덩이가 있다. 다 자란 것이다. 그것만 남기고 나머지를 덜었다.<br>다 자란 고기는 먹을 수 있다. 한 덩이를 챙겼다.`,
      ng:`걸으며 걷어 내다 레일 아래 발이 걸렸다.<br><br>수레가 지나갔다. 바퀴가 발등을 밟았다.`,
      win:{ exp:16, dream:2, item:'짐승 고기' }, lose:{ hp:-14, spirit:-4 } },
    { l:'③ 수레는 두고 다친 둘을 업는다.', k:'bond', dc:14,
      ok:`수레를 믿지 않았다. 짐은 사람이 진다. 하나를 업고 하나는 팀원 둘이 부축했다.<br><br>수레는 앞서 굴러갔다. 출하구 앞에서 셔터에 막혀 멈췄다. 실린 고기가 자라고 자라서 수레를 덮었다.<br>탔으면 같이 덮였다.`,
      ng:`업고 걷는데 수레가 뒤에서 굴러왔다. 궤도가 둘이었다.<br><br>비켜서다 업은 사람과 같이 넘어졌다. 수레가 지나가며 이쪽 등을 쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } }
  ] },

{ at:'C1', t:'갈고리 — 꼬리표',
  x:`갈고리마다 꼬리표가 달렸다. 고깃덩이마다. 어디로 보내는지 적혔다.<br><br>
    꼬리표는 읽을 줄 안다. 짐에는 갈 데가 있다.<br>
    꼬리표마다 같은 데로 간다. 출하. 그런데 하나만 다르다. 이쪽 팀원 이름이 적혔다. 빈 갈고리에 매달린 꼬리표다.<br><br>
    빈 갈고리가 그 팀원 쪽으로 내려온다.`,
  o:[
    { l:'① 꼬리표를 떼어 이쪽 허리에 맨다.', k:'bond', dc:15,
      doom:{ title:'꼬리표', what:'갈고리에 걸려 끌려갑니다', dc:15, sec:60,
        text:`꼬리표를 떼어 이쪽 허리에 맸다. 짐이 바뀌었다.<br><br>갈고리가 바뀐 짐을 찾아온다. 정확하다. 허리띠에 걸린다. 들린다.<br>표사는 짐을 지키는 사람이다. 짐이 되어 본 적은 없다. 짐은 무겁고 아무 데도 못 간다.<br><br>레일이 돈다. 줄 끝에서 칼 소리가 난다.`,
        dieText:`꼬리표대로 갔다.<br><br>표사는 받은 짐을 끝까지 보낸다. 이번 짐은 표사였다.<br>줄 끝에 꼬리표 하나가 떨어져 있다. 받는 쪽 칸에 도장이 찍혔다.` },
      ok:`꼬리표를 떼어 이쪽 허리에 맸다. 그 아래 숯으로 한 줄 더 적었다. 표사 동행.<br><br>갈고리가 내려오다 멈칫한다. 꼬리표를 더듬는다. 지키는 사람이 붙은 짐이다. 한참 머뭇거리다 올라갔다.<br>표호는 소리로만 하는 게 아니었다. 적어 둬도 먹힌다.<br><br>팀원이 이쪽 허리의 꼬리표를 보고 웃다가 운다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 팀원을 갈고리가 안 닿는 기둥 뒤로 옮긴다.', k:'evade', dc:14,
      ok:`팀원 팔을 끌어 기둥 뒤로 갔다. 갈고리는 레일을 못 벗어난다.<br><br>빈 갈고리가 기둥 앞에서 흔들린다. 꼬리표가 팔랑인다. 못 온다.<br>기둥 뒤로만 골라 다음 층 계단까지 갔다. 꼬리표 달린 갈고리가 레일 끝까지 따라왔다.`,
      ng:`기둥 뒤로 가는데 레일이 굽었다. 기둥 뒤까지 이어져 있었다.<br><br>갈고리가 팀원 옷깃에 걸렸다. 둘이 매달려 옷을 찢었다. 팀원 목에 쇠 자국이 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-8 } }
  ] },

{ at:'C1', t:'출하 통로 — 머리 높이의 갈고리',
  x:`출하구로 가는 길이 갈고리 줄 바로 아래다. 다른 길은 없다.<br><br>
    갈고리가 머리 높이로 돈다. 일정하게. 빈 갈고리는 아래로 처진다. 지나가는 것을 낚는다.<br>
    다섯 중 둘은 키가 크다. 하나는 다쳐서 허리를 못 숙인다.<br><br>
    짐을 낮게 싣는 법은 안다. 짐이 사람이어도.`,
  o:[
    { l:'① 다친 사람을 눕혀 넷이 낮게 들고 간다.', k:'bond', dc:15,
      ok:`다친 사람을 문짝에 눕혔다. 넷이 네 귀퉁이를 잡았다. 무릎을 굽히고. 허리 높이로.<br><br>갈고리가 머리 위를 지나간다. 누운 사람 코끝 한 뼘 위를. 다섯이 같은 박자로 무릎을 굽혔다.<br>통로를 다 지났다. 무릎이 다들 후들거렸다.<br><br>혼자 지는 것과 여럿이 드는 것은 다르다. 혼자 지면 짐 높이가 이쪽 등 높이다. 여럿이 들면 짐 높이를 고를 수 있다. 드는 손을 늘려 짐 길을 고르는 법을 처음 썼다.`,
      ng:`네 귀퉁이 높이가 안 맞았다. 문짝이 기울었다.<br><br>누운 사람 어깨가 갈고리에 걸렸다. 문짝째 들렸다. 넷이 매달려 끌어내렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-14, mind:-8 }, wake:1 },
    { l:'② 갈고리 박자를 세어 하나씩 보낸다.', k:'sense', dc:14,
      ok:`빈 갈고리가 처지는 박자를 셌다. 셋 지나고 한 번.<br><br>처지는 갈고리가 지난 직후에 하나씩 보냈다. 허리 못 숙이는 사람은 맨 마지막에, 이쪽이 등을 받쳐서.<br>갈고리 끝이 그 사람 정수리를 스쳤다. 머리카락 몇 올을 가져갔다.`,
      ng:`셋째를 보내는데 박자가 바뀌었다. 둘 지나고 한 번.<br><br>셋째 목덜미에 갈고리가 닿았다. 옷깃이 찢겨 나갔다. 살갗도 조금.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-6 } }
  ] },

{ at:'C2', t:'출고장 — 쌓인 상자',
  x:`공방 출고장이다. 나무 상자가 쌓였다. 상자마다 인형이 하나씩 들었다. 짚에 싸서.<br><br>
    상자 겉에 받을 곳이 적혀 있다. 다 같다. 위층.<br>
    안 보낸 짐을 보면 마음이 편치 않다. 쌓인 지 오래다. 아무도 안 날랐다.<br><br>
    상자 하나가 안에서 똑똑 두드린다. 다른 상자들보다 크다.`,
  o:[
    { l:'① 상자들은 봉한 채 옆으로 치워 길을 낸다.', k:'steady', dc:14,
      ok:`상자를 하나씩 들어 옆으로 쌓았다. 열지 않았다. 남의 짐이다.<br><br>상자 안에서 사기가 짚에 스치는 소리가 난다. 들 때마다 안의 것이 이쪽을 향해 돌아눕는다.<br>길이 났다. 두드리는 상자는 맨 마지막까지 안 건드렸다. 두드림이 그쳤다.`,
      ng:`들어 올린 상자 바닥이 빠졌다. 짚과 함께 인형이 쏟아졌다.<br><br>이가 먼저 나왔다. 손등을 물고 매달렸다. 짚 냄새가 났다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-12, mind:-6 } },
    { l:'② 두드리는 큰 상자만 연다.', k:'bond', dc:15,
      ok:`큰 상자 못을 뽑았다. 짚을 헤쳤다.<br><br>사람이다. 다른 팀 옷이다. 손목과 발목이 실로 묶였다. 입에 짚이 물렸다. 위층으로 보낼 짐으로 꾸려져 있었다.<br>실을 끊고 짚을 뺐다. 그 사람이 한참 숨만 쉬었다.<br><br>짐 꼬리표를 떼어 버렸다. 이 짐은 위층으로 안 간다. 이쪽이 받은 짐이 됐다.`,
      ng:`못을 뽑는데 두드림이 멈췄다. 상자 안에서 이가 딱딱 맞부딪친다.<br><br>짚 사이로 사기 손이 나왔다. 이쪽 손목을 잡았다. 큰 상자에는 큰 인형이 들어 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-14, spirit:-8 } }
  ] },

{ at:'C2', t:'계단까지 마흔 걸음 — 실 붙은 짐',
  x:`팀원 하나가 실에 걸렸다. 손목, 발목, 목덜미. 위층으로 이어졌다.<br><br>
    실을 끊으면 새 실이 내려온다. 끊고 끊고 또 끊었다. 실은 끝이 없다.<br>
    짐은 업고 간다. 실이 붙은 채로라도. 계단까지 가면 위층 실은 거기까지 안 닿는다. 아래층에서 누가 그렇게 말했다.<br><br>
    계단까지 마흔 걸음.`,
  o:[
    { l:'① 실 붙은 채 업고 내공으로 마흔 걸음을 버틴다.', k:'steady', dc:15, cost:{ qi:22 },
      doom:{ title:'실 붙은 짐', what:'인형 실에 감겨 위층으로 끌려 올라갑니다', dc:15, sec:55,
        text:`업었다. 내공을 다리에 내렸다. 걸었다. 열. 스물.<br><br>위에서 당긴다. 등의 팀원이 가벼워진다. 들리는 것이다. 놓지 않았다. 팀원이 들리면 이쪽도 들린다.<br>서른. 발끝이 바닥을 긁는다. 마흔까지 열 걸음 남았다. 발이 바닥에 안 닿는다.<br><br>둘이 같이 천장 쪽으로 오른다. 바닥 틈이 가까워진다.`,
        dieText:`위층에 인형이 둘 늘었다.<br><br>하나가 하나를 업은 모양으로.<br>업힌 쪽은 위층 진열장에서 지금도 안 내려온다. 업은 쪽이 안 놓으니까.` },
      ok:`업었다. 내공을 다리에 내렸다. 서른까지는 걸었다. 서른부터는 끌었다. 위에서 당기는 쪽과.<br><br>마흔. 계단 첫 칸에 발을 디뎠다. 실이 툭툭 끊긴다. 정말 거기까지만 닿았다.<br>팀원을 내려놓았다. 손목 실 자국을 문질러 줬다. 이쪽 다리는 한참 떨렸다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 바닥 틈에 칼을 꽂아 실을 감아 묶어 둔다.', k:'fix', dc:15,
      ok:`천장 틈 대신 바닥 틈을 봤다. 실이 바닥 쪽에서 팀원에게 꺾여 들어온다. 꺾이는 자리에 칼을 꽂았다.<br><br>실을 칼자루에 감았다. 위에서 당겨도 칼이 버틴다. 팀원 쪽 실이 느슨해진다. 그 사이 끊었다.<br>칼은 거기 두고 왔다. 위층에서 밤새 칼자루를 당기는 소리가 났을 것이다.`,
      ng:`감는데 칼이 바닥에서 뽑혔다.<br><br>칼이 실에 매달려 위로 올라간다. 팀원도 같이. 다리를 잡고 버텼다. 칼은 잃었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-8 } }
  ] },

{ at:'C2', t:'작은 인형 — 맡긴 꾸러미',
  x:`작은 인형 하나가 이쪽 발치에 와 섰다. 다른 것들과 다르다. 안 문다.<br><br>
    두 손에 꾸러미를 들었다. 손바닥만 하다. 이쪽에 내민다. 고개를 위층 쪽으로 든다.<br>
    위층으로 가져가 달라는 것이다.<br><br>
    표사는 받은 짐은 끝까지 간다. 그러니 받기 전에 짐을 본다.`,
  o:[
    { l:'① 받기 전에 꾸러미를 열어 본다.', k:'gaze', dc:15,
      ok:`받아 들기 전에 끈을 풀었다. 안에 가위가 있다. 작고 녹슬었다. 실 끊는 가위.<br><br>인형이 위층을 본다. 그리고 제 정수리를 본다. 정수리에 실이 붙어 있다. 위로.<br>보내 달라는 게 아니었다. 끊어 달라는 것이었다. 인형은 가위를 쥘 손가락이 없다.<br><br>가위로 인형 정수리 실을 끊었다. 인형이 그 자리에 앉았다. 다시는 안 움직였다.<br>짐을 보면 짐이 갈 데가 보인다고 배웠다. 오늘은 짐을 내민 쪽이 무엇을 바라는지가 보였다. 짐 너머를 보는 눈이 하나 늘었다.`,
      ng:`끈을 풀자 꾸러미 안에서 이가 쏟아졌다. 작은 것들. 젖니.<br><br>인형이 이쪽을 본다. 받은 짐을 함부로 연 표사를. 진열장 쪽에서 딱딱 소리가 모인다. 다들 뛰었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-12, spirit:-10 }, wake:1 },
    { l:'② 받지 않고 지나간다.', k:'steady', dc:14,
      ok:`받지 않았다. 갈 데 모르는 짐은 안 받는다.<br><br>인형이 꾸러미를 든 채 서 있다. 다섯이 다 지나갈 때까지. 꾸러미를 내민 손이 안 내려간다.<br>계단에서 돌아봤다. 아직 내밀고 있었다.`,
      ng:`지나가는데 인형이 따라온다. 꾸러미를 내민 채로.<br><br>계단까지 따라왔다. 계단 앞에서 꾸러미를 떨어뜨렸다. 쏟아진 건 이였다. 젖니. 그걸 줍는 소리를 듣고 다른 것들이 모였다.`,
      win:{ exp:14, dream:2 }, lose:{ mind:-10, spirit:-8 } }
  ] },

{ at:'C3', t:'둥근 천장 — 위로 떨어지려는 짐',
  x:`뒤집힌 성당에서 짐이 이상하다. 등에 진 짐이 자꾸 머리 쪽으로 쏠린다. 원래 아래였던 쪽으로.<br><br>
    배낭 끈이 어깨를 파고든다. 짐이 위로 떨어지려 한다. 이 성당에서 오래 머문 것들이 그렇게 된다.<br>
    팀원 하나 배낭이 벌써 떴다. 끈째 팀원 어깨를 끌어 올린다. 팀원이 발끝으로 선다.<br><br>
    짐이 사람을 끌고 가게 둘 수는 없다.`,
  o:[
    { l:'① 다섯 짐을 다 받아 이쪽 몸에 묶고 내공으로 누른다.', k:'steady', dc:15, cost:{ qi:20 },
      ok:`다섯 배낭을 다 받아 이쪽 허리와 어깨에 묶었다. 내공을 아래로 내렸다. 발바닥에.<br><br>짐 다섯이 위로 당긴다. 이쪽은 아래로 버틴다. 걸었다. 둥근 천장 골을 따라. 한 걸음마다 무릎을 눌렀다.<br>골 끝 구멍 앞에서 짐이 제 무게로 돌아왔다. 다섯 배낭이 한꺼번에 내려앉았다. 무릎이 꺾였다.`,
      ng:`묶는 동안 다섯 짐이 한꺼번에 떴다. 이쪽 발이 떴다.<br><br>팀원들이 다리를 잡았다. 배낭 하나를 놓쳤다. 의자들 사이로 떨어져 올라갔다. 물주머니가 들어 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-14, mind:-6 } },
    { l:'② 짐을 가슴 쪽으로 돌려 매고 끈을 짧게 친다.', k:'fix', dc:14,
      ok:`배낭을 등에서 가슴으로 돌렸다. 끈을 짧게. 짐이 머리 쪽으로 가려면 이쪽 턱을 지나야 한다.<br><br>다섯이 다 그렇게 맸다. 짐이 턱밑에서 버둥거린다. 숨이 갑갑하다. 그래도 사람이 안 들렸다.`,
      ng:`돌려 매는 사이 끈이 풀렸다. 배낭이 얼굴을 치고 올라갔다.<br><br>코피가 났다. 피가 아래로 떨어졌다. 배낭은 위로 떨어졌다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-12, spirit:-6 } }
  ] },

{ at:'C3', t:'골 바닥 — 두건 쓴 순례자',
  x:`둥근 천장 골에 누가 앉아 있다. 순례자 옷이다. 두건이 깊다.<br><br>
    <span style="color:#d4af37;">"건너편 제단까지 데려다주시오. 혼자는 못 건너오."</span><br>
    골 건너편에 제단이 있다. 거꾸로. 그 사이에 종 같은 것들이 줄지어 섰다.<br><br>
    두건 아래가 안 보인다. 손은 보인다. 손가락마다 마디가 하나씩 더 있다.`,
  o:[
    { l:'① 표를 받고 다섯이 둘러싸 종 사이를 건넌다.', k:'bond', dc:15,
      ok:`받았다. 짐이 무엇이든 받으면 끝까지 간다.<br><br>순례자를 가운데 두고 다섯이 둘러쌌다. 종 사이를 건넜다. 종들이 순례자 쪽으로 기울다 둘러싼 어깨에 막혔다.<br>제단 앞에서 순례자가 무릎을 꿇었다. 두건을 벗었다. 아래는 비어 있었다. 옷이 천천히 내려앉았다. 다 왔다는 듯.<br><br>짐이 사람인지 아닌지 묻지 않고 받았다. 어디로 가는지만 알면 데려다줄 수 있었다. 받는 짐의 폭이 한 뼘 넓어졌다. 손가락 마디가 하나 더 있는 손을 잡아 본 건 처음이었다.`,
      ng:`둘러싸고 가는데 종 하나가 순례자를 향해 울었다.<br><br>순례자가 이쪽 팔을 잡는다. 마디 많은 손가락이 감긴다. 겁이 난 것이다. 겁난 손은 세다. 팔에 손가락 자국이 길게 남았다.`,
      win:{ exp:24, dream:3, spirit:6 }, lose:{ hp:-10, spirit:-12 }, wake:1 },
    { l:'② 받기 전에 두건 아래부터 보여 달라 한다.', k:'gaze', dc:15,
      ok:`짐은 받기 전에 본다. 두건을 벗어 달라고 했다.<br><br>순례자가 한참 가만있다. 그리고 일어선다. 혼자. 종 사이로 걸어간다. 못 건넌다던 길을.<br>제단에 닿아 돌아본다. 두건 아래는 끝내 안 보였다. 혼자 건널 수 있는 것이었다. 누가 같이 가 주길 바랐을 뿐이다.`,
      ng:`벗어 달라는 말에 두건이 이쪽으로 기운다.<br><br>안에서 숨이 나온다. 차다. 촛농 냄새. 이쪽 얼굴에 하얀 것이 엉겼다. 떼어 내는 데 한참 걸렸다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-10, spirit:-8 } }
  ] },

{ at:'C3', t:'구멍 앞 — 종 사이 길목',
  x:`다음 구멍 앞 골이 좁다. 양옆에 종 같은 것들이 아가리를 벌리고 섰다. 길목이다.<br><br>
    표사는 길목을 안다. 산길 협곡. 양옆에서 덮치는 자리.<br>
    사람이 지나가면 종이 운다. 울리는 종은 아가리가 닫힌다. 닫힐 때 옆에 있는 것을 문다.<br><br>
    길목에서는 짐을 가운데 두고 사람이 둘러싼다. 둘러싼 사람이 물린다.`,
  o:[
    { l:'① 맨 바깥에 서서 종 쪽 어깨를 맡는다.', k:'steady', dc:15,
      doom:{ title:'종의 아가리', what:'종 아가리에 물려 끌려 들어갑니다', dc:15, sec:55,
        text:`종 쪽 맨 바깥에 섰다. 다섯을 안쪽에 두고 걸었다.<br><br>첫 종이 울었다. 아가리가 닫힌다. 어깨로 받았다. 테두리가 어깨를 문다. 놓지 않는다.<br>종이 이쪽을 안으로 당긴다. 혀가 나와 허리를 감는다.<br><br>안쪽의 다섯은 멀쩡하다. 길목이 원래 그렇다.`,
        dieText:`길목은 다시 조용하다.<br><br>종 하나가 다른 종보다 조금 무겁다. 아가리 테두리에 천 조각이 끼었다.<br>다음 팀이 지나갈 때 그 종만 안 운다. 안쪽에서 누가 막고 있다.` },
      ok:`종 쪽 맨 바깥에 섰다. 첫 종이 울었다. 아가리가 닫힌다. 어깨를 빼며 칼집을 대신 밀어 넣었다.<br><br>종이 칼집을 물었다. 닫힌 아가리는 다음에 울 때까지 안 열린다.<br>둘째, 셋째. 칼집, 허리띠, 빈 수통. 물릴 것을 하나씩 내줬다. 다섯이 다 지났다.<br><br>짐을 하나씩 버리며 사람을 지켰다. 길값이었다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 돌을 굴려 종을 먼저 울리고 닫힌 틈에 지나간다.', k:'sense', dc:14,
      ok:`돌을 굴렸다. 종들이 차례로 운다. 아가리가 차례로 닫힌다.<br><br>닫힌 종은 다음에 울 때까지 안 연다. 마지막 종이 닫히자마자 다섯이 뛰었다.<br>뒤에서 종들이 하나씩 다시 열렸다. 다 지난 뒤였다.`,
      ng:`돌이 중간에 멈췄다. 반만 울었다.<br><br>안 운 종 앞을 지나는데 그 종이 울었다. 팀원 소매를 물었다. 소매째 잘라 내고 뛰었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-6 } }
  ] },

{ at:'C4', t:'짐 속 솜털',
  x:`온실에 들어오고 나서 짐이 무거워졌다. 배낭마다 하얀 솜털이 핀다.<br><br>
    포자다. 짐 안까지 들어갔다. 고기에, 약초에, 물주머니 주둥이에.<br>
    상한 짐은 냄새로 안다. 상한 짐은 성한 짐까지 상하게 한다.<br><br>
    버려야 한다. 무엇을 버리는지가 문제다.`,
  o:[
    { l:'① 하나하나 냄새를 맡아 상한 것만 가른다.', k:'gaze', dc:15,
      ok:`짐을 다 풀었다. 하나씩 코에 댔다. 상한 건 단내가 난다. 썩은 꿀 같은.<br><br>고기 반, 약초 셋, 물주머니 하나. 버렸다. 수칙대로. 나머지는 다시 꾸렸다. 성한 것끼리.<br>버린 쪽 더미가 밤새 하얗게 부풀었다. 같이 뒀으면 다 저렇게 됐다.`,
      ng:`맡다가 포자를 들이켰다. 단내가 목에 걸렸다.<br><br>기침하는 사이 상한 것과 성한 것이 섞였다. 다 버렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-12, mind:-6 } },
    { l:'② 다 버리고 온실 안에서 봉한 것을 찾는다.', k:'luck', dc:14,
      ok:`짐을 통째로 버렸다. 아까웠다.<br><br>전실 쪽 선반에 밀랍으로 봉한 통이 있다. 정원사들 몫이다. 깨 보니 말린 고기가 들었다. 포자가 못 들어갔다.<br>봉인은 그래서 하는 것이다.`,
      ng:`다 버렸는데 봉한 통은 없었다.<br><br>빈손으로 한 단을 더 내려갔다. 배가 고팠다. 손이 떨렸다.`,
      win:{ exp:15, dream:2, item:'말린 고기' }, lose:{ mind:-10, hp:-8 } },
    { l:'③ 짐을 불에 그슬려 솜털을 태운다.', k:'fix', dc:15,
      ok:`횃불을 배낭 겉에 천천히 둘렀다. 솜털이 오그라든다. 하얀 연기가 난다.<br><br>안까지는 못 태운다. 겉만. 그래도 겉이 그을리니 더 안 핀다.<br>그을린 고기 냄새가 났다. 먹을 만했다.`,
      ng:`그을리는데 솜털이 불을 탔다. 확 번졌다.<br><br>배낭 하나가 통째로 탔다. 불 끄다 손바닥을 데었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-4 } }
  ] },

{ at:'C4', t:'업은 등 — 따뜻한 숨',
  x:`팀원이 포자를 마셨다. 걷지 못한다. 업었다.<br><br>
    업은 등이 따뜻하다. 너무 따뜻하다. 팀원 숨에서 가루가 나온다. 이쪽 목덜미에 앉는다.<br>
    업고 가면 이쪽도 옮는다. 안 업고 가면 팀원은 여기 남는다. 남은 것들이 작업복을 입는 걸 봤다.<br><br>
    표사는 짐을 안 내려놓는다.`,
  o:[
    { l:'① 내공을 등으로 돌려 옮겨붙는 포자를 밀어낸다.', k:'steady', dc:15, cost:{ qi:20 },
      ok:`내공을 등으로 돌렸다. 살갗 밖으로 밀었다. 열이 난다.<br><br>목덜미에 앉은 가루가 땀에 씻겨 흘러내린다. 붙지 못한다. 업힌 팀원 숨도 이쪽 등 열에 조금씩 맑아진다.<br>한 단을 다 내려갔다. 내려놓으니 등에 하얀 땀자국이 넓게 남았다. 털어 냈다.`,
      ng:`밀어내는 데 내공이 모자랐다.<br><br>목덜미가 가렵다. 가려운 데가 단단해진다. 칼끝으로 긁어 냈다. 따끔한 게 오래 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-14, mind:-8 } },
    { l:'② 젖은 천을 둘 사이에 두르고 업는다.', k:'fix', dc:14,
      ok:`천을 물에 적셔 이쪽 등과 목덜미에 둘렀다. 팀원 입에도 하나.<br><br>가루가 천에 앉는다. 천이 하얘진다. 쉴 때마다 갈았다. 천 다섯 장이 하얘졌다.<br>버렸다. 수칙대로.`,
      ng:`천이 금방 말랐다. 온실은 따뜻하다.<br><br>마른 천은 가루를 못 막는다. 목이 붓기 시작했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-6 } }
  ] },

{ at:'C4', t:'중앙으로 가는 수레',
  x:`작업복 입은 것이 수레를 민다. 수레에 사람이 실렸다. 다른 팀 사람이다. 숨은 쉰다. 몸에 하얀 것이 반쯤 덮였다.<br><br>
    수레는 온실 한가운데로 간다. 큰 갓이 숨 쉬는 쪽으로. 거름처럼 실어 간다.<br>
    작업복은 수레를 정성껏 민다. 바퀴가 돌부리에 걸리면 들어 넘긴다. 짐을 아끼는 손이다.<br><br>
    그 손을 안다. 이쪽 손이다.`,
  o:[
    { l:'① 수레 앞을 막고 법도대로 짐을 넘겨받는다.', k:'bond', dc:15,
      ok:`수레 앞에 섰다. 손잡이를 같이 쥐었다. 여기서부터는 이쪽이 나르겠다고. 두 손을 모아.<br><br>작업복이 멈춘다. 짐을 넘겨받는 법을 아는 몸이다. 넘겨받는 쪽이 법도를 지키면 넘기는 쪽도 지킨다. 손을 놓고 물러섰다.<br>수레를 돌렸다. 한가운데가 아니라 올라가는 쪽으로. 실린 사람은 이쪽이 끝까지 데려갔다.<br><br>법도는 사람끼리의 말인 줄 알았다. 손으로 하는 법도는 사람 아닌 것에게도 닿았다. 넘겨받는 손이 그걸 기억했다.`,
      ng:`앞을 막자 작업복이 수레를 더 세게 민다. 짐을 지키는 손이다. 이쪽처럼.<br><br>수레가 이쪽 정강이를 들이받았다. 실린 사람이 굴러떨어졌다. 하얀 것이 바닥에 닿자 바닥 균사가 반긴다. 둘이 같이 겨우 떼어 냈다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-16, spirit:-8 }, wake:1 },
    { l:'② 작업복을 쓰러뜨리고 수레를 뺏는다.', k:'break', dc:15,
      ok:`작업복 무릎을 걷어찼다. 무너진다. 모자가 굴렀다.<br><br>수레를 잡았다. 실린 사람 몸의 하얀 것을 칼등으로 긁어 냈다. 깊지 않았다. 아직.<br>무너진 작업복은 일어나려다 그만뒀다. 밀 수레가 없으니까.`,
      ng:`걷어찼는데 작업복이 수레를 놓지 않는다.<br><br>쓰러지면서 수레를 끌고 쓰러졌다. 실린 사람이 균사 바닥에 엎어졌다. 일으켰을 때 얼굴 반쪽이 하얬다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-8 } },
    { l:'③ 수레를 따라가 한가운데를 먼저 본다.', k:'hide', dc:15,
      ok:`몰래 따라갔다. 수레가 돔 앞에 선다. 작업복이 실린 사람을 내리려 한다.<br><br>그때 뛰어나가 실린 사람을 낚아챘다. 돔 안의 큰 갓이 부풀었다 꺼지는 박자를 봤다. 숨 쉴 때 둘레의 것들이 한꺼번에 굳는다.<br>그 박자를 기억해 두고 돌아왔다. 다음에 올 때 쓸 것이다.`,
      ng:`따라가다 돔 둘레의 것들에게 들켰다.<br><br>수레째 둘러싸였다. 실린 사람을 업고 뚫고 나왔다. 등에 하얀 손자국이 여럿 찍혔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-16, spirit:-6 } }
  ] }

]);

